INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C1','soc',4,2,'u2',1,'지역문제의 의미 — 지역 주민의 생활을 불편하게 하거나 지역 주민들 사이에 갈등을 일으키는 문제 · 개인이 아닌 여러 사람과 관련된 공동의 문제, 개인이 해결하기 어려움 · 지역 곳곳에서 일어나고 주민들이 함께 해결해야 함 · 지역의 상황에 따라 다르게 나타남 · 내가 독감에 걸린 일은 개인의 일이지만 예방 수칙을 지키지 않아 이웃에게 옮으면 지역문제로 커짐 · 층간 소음은 주민 사이 갈등 · 공사장 소음, 쓰레기 무단 배출, 주차 공간 부족, 교통 혼잡 · 해결하지 않으면 불편이 계속됨(큰비에 도로가 잠겨 마을이 고립, 문화유산 훼손)',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C2','soc',4,2,'u2',2,'우리 지역의 문제 확인하기 — 지역을 직접 둘러보기, 시·도청 누리집에서 주민이 올린 글 찾아보기, 지역 신문 기사나 뉴스 살펴보기, 지역 주민과 면담하기 · 지역의 일에 관심을 가지면 문제가 보임 · 교통 혼잡·안전·환경 오염·주차·쓰레기·시설 부족 문제 · 설문 조사로 확인하고 모둠별로 토의해 해결하고 싶은 문제를 정함 · 횟수만으로 정하지 않음 · 사람마다 생각과 경험이 달라 다양하게 나타남 · 정하는 기준: 얼마나 빨리 해결해야 하는가, 얼마나 많은 사람이 해결을 바라는가, 내가 얼마나 관심이 있는가 · 토의로 의견 차이를 좁힘',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C3','soc',4,2,'u2',3,'지역문제의 원인 찾기 — 원인을 알려면 지역문제와 관련 있는 다양한 자료가 필요 · 자료 모으기: 장소 답사, 시·도청 누리집, 지역 신문이나 뉴스, 주민 면담과 설문 조사 · 자료의 종류: 통계 자료(표·그래프), 신문 기사, 공익 광고, 설문 조사 결과 · 자료 → 정보 찾기 → 뜻 해석 → 종합해 원인 파악 · 주차 문제: 자동차 수에 비해 주차 공간 부족(표), 저녁에 부족(그래프), 불법 주차 피해를 잘 모름(기사), 규칙을 지키려는 마음 부족(설문) → 원인 둘 · 의견만이 아니라 사실을 확인하는 객관적인 자료',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C4','soc',4,2,'u2',4,'지역문제의 해결 방안 찾기 — 원인을 알아본 후에 원인과 관련한 해결 방안을 찾음 · 여러 방안의 장단점을 비교하고 대화와 타협으로 의견을 조정해 알맞은 방안을 정함 · 평가 기준: 효과가 큰가, 비용이 적게 드나, 실천할 수 있나, 누군가에게 피해를 주지 않나 · 부족한 부분은 버리지 않고 보완하여 수정 · 객관적인 자료와 사실에 근거해 의견 제시 · 더 합리적인 해결 방안 · 쓰레기 문제 방안(분리배출 교육, 캠페인, 종량제 봉투 가격 올리기) · 공유(공유 주차장, 공공 자전거)',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C5','soc',4,2,'u2',5,'지역문제의 해결 방안 실천하기 — 해결 방안을 정한 다음 구체적인 계획을 세워 실천 · 주민이 실천할 수 있는 일(분리배출, 쓰레기 양 줄이기, 정해진 곳에 버리기)과 공공 기관의 협조가 필요한 일(분리수거함 설치, 종량제 봉투 가격, 무단 투기 단속) · 공공 기관에 제안서(제목·보낼 곳·제안한 까닭·주요 제안 내용) — 실태와 실천 방안이 분명하게 · 시청 게시판에 공공 기관 주차장 개방 요청, 주민과 함께 캠페인 → 다툼·불법 주차 줄어듦 · 지역 주민과 공공 기관이 힘을 모아야 · 주민 모두가 꾸준히 노력 · 지능형 교통 시스템 연구원',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C6','soc',4,2,'u2',6,'지역문제의 해결 정리 — 지역문제의 의미와 종류 → 우리 지역의 문제 확인 → 자료를 분석해 원인 → 토의로 해결 방안 → 실천 · 문제 확인하기 → 원인 찾기 → 해결 방안 정하기의 차례 · 지역문제는 삶을 불편하게 하거나 갈등을 일으킴 · 대화와 타협으로 의견 조정 · 주민과 공공 기관이 함께 실천 · 지역 주민 모두가 관심을 갖고 꾸준히 노력 · 공익 광고 영상 기획(장면 순서·장면·설명·대사·자막·배경음·효과음) · 공원 꾸미기(그림 솜씨보다 담은 가치)',ARRAY['[4사09-01] 지역문제의 의미를 알고, 지역문제의 원인을 탐구하여 해결 방안을 찾고 실천한다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C7','soc',4,2,'u2',7,'우리 지역의 자랑거리 — 지역에는 자연환경·역사·문화·생산물 등과 관련 있는 자랑거리가 있음 · 자랑거리를 살펴보면 그 지역의 독특한 점이나 특징을 알 수 있음(큰 강이 흐르는 곳, 아주 오래전부터 사람이 살던 곳, 옛 솜씨를 이어 오는 곳 등) · 관광 안내 자료를 무료로 주는 까닭 = 지역과 자랑거리를 널리 알리려고 · 조사 방법: 시·도청이나 지역 문화원 누리집 검색, 오래 사신 어른께 여쭈어보기, 지역 안내 자료·안내 책자 · 의병(백성이 나라나 고장을 지키려고 스스로 만든 군대) · 퍼레이드 연기자',ARRAY['[4사09-02] 지역의 자랑거리를 조사하고, 지역을 알리려는 지역 사회의 다양한 노력을 탐구한다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C8','soc',4,2,'u2',8,'자랑거리를 알리는 다양한 노력 — 지역을 알리고 발전시킬 수 있어서(관광객이 오면 지역 경제에 도움) · 자연환경: 관광 상품 개발(갯벌 머드 축제·머드 상품) · 역사: 축제나 전시회, 유적지 체험 프로그램 · 문화: 민속 축제, 체험 행사, 민속놀이·체육 행사 · 생산물: 박람회, 직거래 장터, 축제 · 축제는 네 갈래 모두에 쓰이고 체험 프로그램은 역사·문화에 쓰임 · 조사 방법: 시·군·구청 누리집, 사회 관계망 서비스, 지역 소식지, 관광 안내 자료',ARRAY['[4사09-02] 지역의 자랑거리를 조사하고, 지역을 알리려는 지역 사회의 다양한 노력을 탐구한다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C9','soc',4,2,'u2',9,'자랑거리를 알리는 활동 — 소개할 자랑거리 정하기 → 모둠에서 소개 방법 정하기 → 알맞은 소개 자료 만들기 · 만화(4~6장면, 말풍선 — 쉽고 재미있게) · 포스터(그림·사진, 설명 문구 — 더 잘 표현) · 안내도(백지도에 색칠, 자료 붙이기, 선으로 잇기 — 위치와 특징을 한눈에) · 세 방법 모두 첫 걸음은 꾸밀 자랑거리 정리 · 사회 관계망 서비스: 확인되지 않은 정보 게시 0, 저작권, 개인 소식·사진 허락 없이 게시 0 · 많은 사람이 이해하게 소개, 관심을 가지고 듣기 → 지역 이해와 자부심',ARRAY['[4사09-02] 지역의 자랑거리를 조사하고, 지역을 알리려는 지역 사회의 다양한 노력을 탐구한다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u2-C10','soc',4,2,'u2',10,'지역을 알리는 노력 정리 — 자연환경·역사·문화·생산물 자랑거리, 누리집·사회 관계망 서비스·소식지·관광 안내 자료로 알리는 노력, 소개 자료로 알리는 활동 되짚기 · 지역마다 자연환경·역사·문화가 다르고 생산물도 다름 · 자랑거리로 지역문제를 알 수 있는 것은 아님 · 정리는 다양한 방법으로(동시 짓기 — 생산물 세 가지 이상 / 상품 기획하기 — 자랑거리·까닭·상품 그림), 둘 가운데 하나를 골라 함 · 활동에 참여하며 우리 지역에 관심',ARRAY['[4사09-02] 지역의 자랑거리를 조사하고, 지역을 알리려는 지역 사회의 다양한 노력을 탐구한다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X01','soc',4,'u2',ARRAY['SO4-2-u2-C1']::text[],'한 사람에게만 생긴 일과 지역문제를 가르지 못하거나, 개인의 일이 이웃에게 번져 지역문제가 될 수 있음을 놓친다','여러 주민의 생활 · 주민 사이 갈등') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X02','soc',4,'u2',ARRAY['SO4-2-u2-C1']::text[],'지역문제는 한 사람이나 다른 지역 사람이 해결한다고 여겨, 주민이 함께 해결해야 함을 놓친다','지역 주민 모두가 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X03','soc',4,'u2',ARRAY['SO4-2-u2-C1']::text[],'지역문제는 어느 지역에서나 똑같이 나타난다고 여긴다','지역의 상황에 따라 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X04','soc',4,'u2',ARRAY['SO4-2-u2-C1']::text[],'지역문제를 그냥 두어도 저절로 사라지거나 아무 일이 없다고 여긴다','두면 불편이 계속돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X05','soc',4,'u2',ARRAY['SO4-2-u2-C2']::text[],'우리 지역의 문제를 확인하는 방법을 잘못 안다(상상하기, 다른 지역 것을 옮겨 적기 등)','둘러보기 · 누리집 · 기사 · 면담') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X06','soc',4,'u2',ARRAY['SO4-2-u2-C2']::text[],'해결하고 싶은 지역문제를 횟수나 제비뽑기·가위바위보로만 정해도 된다고 여겨 모둠 토의를 놓친다','횟수는 참고 · 토의로 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X07','soc',4,'u2',ARRAY['SO4-2-u2-C2']::text[],'사람마다 해결하고 싶은 지역문제가 같다고, 또는 지역문제는 한 가지뿐이라고 여긴다','생각과 경험이 서로 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X08','soc',4,'u2',ARRAY['SO4-2-u2-C2']::text[],'해결하고 싶은 문제를 정하는 기준을 잘못 안다(누가 먼저 말했나, 이름이 멋진가 등)','얼마나 급한가 · 몇 사람이 바라나 · 내 관심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X09','soc',4,'u2',ARRAY['SO4-2-u2-C3']::text[],'원인을 자료 없이 느낌이나 의견으로 정하거나, 원인을 먼저 정해 놓고 맞는 자료만 모은다','사실을 확인하는 자료가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X10','soc',4,'u2',ARRAY['SO4-2-u2-C3']::text[],'자료 한 장만 보아도 원인을 알 수 있다고 여겨, 여러 자료의 정보를 종합해야 함을 놓친다','여러 자료를 겹쳐 종합해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X11','soc',4,'u2',ARRAY['SO4-2-u2-C3']::text[],'자료의 종류·모으는 방법을 잘못 알거나, 자료에서 찾은 정보와 원인을 헷갈린다','자료 → 정보 → 뜻 → 원인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X12','soc',4,'u2',ARRAY['SO4-2-u2-C4']::text[],'해결 방안을 원인과 관계없이 찾거나, 원인을 알아보기 전에 찾는다','원인을 알아본 뒤 원인과 이어진 방안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X13','soc',4,'u2',ARRAY['SO4-2-u2-C4']::text[],'해결 방안을 평가하는 기준을 잘못 안다(누가 먼저 말했나, 말한 사람의 목소리 등)','효과 · 비용 · 실천 · 피해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X14','soc',4,'u2',ARRAY['SO4-2-u2-C4']::text[],'점수를 더한 값만 보거나 낮은 점수를 받은 방안은 곧바로 버린다고 여겨, 부족한 부분을 보완함을 놓친다','부족한 부분을 보완해 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X15','soc',4,'u2',ARRAY['SO4-2-u2-C4']::text[],'내 방안과 친구 방안이 다르면 끝까지 고집하거나 무조건 따른다고 여겨, 자료에 근거한 대화와 타협을 놓친다','자료와 사실 · 대화와 타협') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X16','soc',4,'u2',ARRAY['SO4-2-u2-C5']::text[],'해결 방안을 정하면 끝이라고, 또는 공공 기관이 해 줄 때까지 기다리면 된다고 여긴다','구체적인 계획을 세워 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X17','soc',4,'u2',ARRAY['SO4-2-u2-C5']::text[],'주민이 스스로 할 수 있는 일과 공공 기관의 협조가 필요한 일을 바꾸어 나눈다','설치 · 단속은 공공 기관에 부탁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X18','soc',4,'u2',ARRAY['SO4-2-u2-C5']::text[],'제안서에 들어갈 내용을 잘못 알거나, 까닭과 내용을 구체적으로 써야 하는 까닭을 놓친다','제목 · 보낼 곳 · 까닭 · 내용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X19','soc',4,'u2',ARRAY['SO4-2-u2-C5']::text[],'지역문제는 공공 기관만, 또는 한 사람만 노력해도 해결된다고 여긴다','주민과 공공 기관이 힘을 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X20','soc',4,'u2',ARRAY['SO4-2-u2-C6']::text[],'지역문제를 해결하는 차례를 잘못 안다(해결 방안을 먼저 정하고 원인을 찾는 등)','확인 → 원인 → 방안 → 실천') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X21','soc',4,'u2',ARRAY['SO4-2-u2-C6']::text[],'지역문제 해결을 정리하는 활동에서 겉모습(그림 솜씨·화려함)만 보고 담긴 해결 방안이나 가치를 놓친다','무엇을 알리고 무엇을 담았나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X22','soc',4,'u2',ARRAY['SO4-2-u2-C7']::text[],'자랑거리의 갈래(자연환경·역사·문화·생산물)를 잘못 나누거나 지역문제를 자랑거리로 여긴다','산과 강 · 옛 자취 · 축제 · 나는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X23','soc',4,'u2',ARRAY['SO4-2-u2-C7']::text[],'자랑거리를 살펴보는 까닭을 이름을 외우는 것으로 여겨, 그 지역의 독특한 점과 특징을 놓친다','그 지역이 어떤 곳인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X24','soc',4,'u2',ARRAY['SO4-2-u2-C7']::text[],'자랑거리를 조사하는 방법을 잘못 안다(옆 지역 것을 옮겨 적기, 조사할 수 없다고 여기기 등)','누리집 · 어른께 여쭈기 · 안내 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X25','soc',4,'u2',ARRAY['SO4-2-u2-C8']::text[],'지역이 자랑거리를 알리는 까닭을 잘못 안다(사람이 오지 못하게, 다른 지역에 넘기려고 등)','지역을 알리고 발전시켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X26','soc',4,'u2',ARRAY['SO4-2-u2-C8']::text[],'알리는 방법을 한 가지로 좁히거나 갈래와 알리는 방법을 잘못 짝짓는다','축제는 네 갈래 모두 · 박람회·장터는 생산물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X27','soc',4,'u2',ARRAY['SO4-2-u2-C9']::text[],'소개 자료를 만드는 차례를 잘못 안다(자료를 먼저 만들고 자랑거리를 나중에 정하는 등)','자랑거리 → 방법 → 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X28','soc',4,'u2',ARRAY['SO4-2-u2-C9']::text[],'만화·포스터·안내도의 만드는 방법과 좋은 점을 서로 바꾸어 안다','안내도는 위치를 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X29','soc',4,'u2',ARRAY['SO4-2-u2-C9']::text[],'사회 관계망 서비스로 소개할 때 확인되지 않은 정보나 남의 사진·소식을 허락 없이 올려도 된다고 여긴다','정확한 정보 · 저작권 · 허락') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X30','soc',4,'u2',ARRAY['SO4-2-u2-C10']::text[],'지역마다 생산물이 같다고 여기거나, 자랑거리로 지역문제를 알 수 있다고 여긴다','지역마다 나는 것이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u2-X31','soc',4,'u2',ARRAY['SO4-2-u2-C10']::text[],'배운 내용을 정리하는 방법은 한 가지뿐이라고, 또는 고를 수 있는 두 활동을 모두 해야 한다고 여긴다','다양한 방법 · 하나를 골라도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#1','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',1,'mc','auto','지역 주민의 생활을 불편하게 하거나 지역 주민들 사이에 갈등을 일으키는 문제를 무엇이라고 하나요?',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"mc","stem":"지역 주민의 생활을 불편하게 하거나 지역 주민들 사이에 갈등을 일으키는 문제를 무엇이라고 하나요?","options":[{"t":"지역문제","correct":true},{"t":"가족 여행","mis":"SO4-2-u2-X01"},{"t":"학급 규칙","mis":"SO4-2-u2-X01"},{"t":"개인의 취미","mis":"SO4-2-u2-X01"}],"explanation":["지역에서 생겨요.","여러 주민에게 닿아요.","지역문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#2','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',1,'sa','auto','층간 소음은 위아래 집 주민들 사이에 ○○을 일으켜요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"sa","stem":"층간 소음은 위아래 집 주민들 사이에 ○○을 일으켜요. ○○에 알맞은 두 글자를 쓰세요.","answer":["갈등"],"explanation":["서로 다투게 돼요.","갈◯이에요.","갈등이에요."],"asset":{"type":"passage","lines":["가. 내가 독감에 걸려 집에서 쉬고 있어요.","나. 공사장에서 참기 힘든 소음이 나요.","다. 골목에 쓰레기를 아무 데나 버려요.","라. 층간 소음으로 위아래 집 사이에 다툼이 생겼어요."],"title":"네 장의 카드"},"mis":"SO4-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#3','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',1,'ox','auto','지역문제는 개인이 아닌 여러 사람과 관련된 공동의 문제예요.',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"ox","stem":"지역문제는 개인이 아닌 여러 사람과 관련된 공동의 문제예요.","answer":"O","reason_options":[{"t":"지역에 함께 사는 여러 주민의 생활과 관련 있기 때문에","correct":true},{"t":"한 사람에게만 생긴 일이기 때문에","mis":"SO4-2-u2-X01"}],"mis":"SO4-2-u2-X01","explanation":["누구와 관련 있나요?","여러 사람이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#4','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',1,'mc','auto','네 장의 카드 가운데 지역문제로 보기 어려운 것은 무엇인가요?',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"mc","stem":"네 장의 카드 가운데 지역문제로 보기 어려운 것은 무엇인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"SO4-2-u2-X01"},{"t":"다","mis":"SO4-2-u2-X01"},{"t":"라","mis":"SO4-2-u2-X01"}],"explanation":["한 사람의 일을 찾아요.","우리 집만 불편해요.","가예요."],"asset":{"type":"passage","lines":["가. 내가 독감에 걸려 집에서 쉬고 있어요.","나. 공사장에서 참기 힘든 소음이 나요.","다. 골목에 쓰레기를 아무 데나 버려요.","라. 층간 소음으로 위아래 집 사이에 다툼이 생겼어요."],"title":"네 장의 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#5','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',2,'mc','auto','지역문제는 누가 해결해야 하나요?',ARRAY['SO4-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"mc","stem":"지역문제는 누가 해결해야 하나요?","options":[{"t":"지역에 사는 주민 모두가 함께","correct":true},{"t":"불편을 겪은 한 사람만","mis":"SO4-2-u2-X02"},{"t":"다른 지역 사람들이","mis":"SO4-2-u2-X02"},{"t":"기사를 쓴 기자만","mis":"SO4-2-u2-X02"}],"explanation":["지역에 누가 사나요?","주민 모두예요.","함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#6','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',2,'mc','auto','세 동네의 지역문제를 보고 알 수 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X03','SO4-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"mc","stem":"세 동네의 지역문제를 보고 알 수 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"지역문제는 지역의 상황에 따라 다르게 나타나요","correct":true},{"t":"지역문제는 어디서나 똑같아요","mis":"SO4-2-u2-X03"},{"t":"지역문제는 한 동네에만 있어요","mis":"SO4-2-u2-X03"},{"t":"지역문제는 주민과 관계없어요","mis":"SO4-2-u2-X01"}],"explanation":["세 동네를 견주어요.","문제가 달라요.","상황에 따라 달라요."],"asset":{"type":"passage","lines":["○○동 — 오래된 아파트가 많아 주차할 곳이 모자란다.","△△동 — 공장이 많아 하천으로 폐수가 흘러든다.","□□동 — 큰 도로가 하나뿐이라 아침마다 길이 막힌다."],"title":"세 동네의 지역문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#7','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',2,'ox','auto','독감 이야기에서 독감이 이웃 여러 집에 옮은 뒤에는 지역문제가 되었어요.',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"ox","stem":"독감 이야기에서 독감이 이웃 여러 집에 옮은 뒤에는 지역문제가 되었어요.","answer":"O","reason_options":[{"t":"다른 주민들의 건강을 해치고 여러 집의 생활을 불편하게 했기 때문에","correct":true},{"t":"독감은 처음부터 언제나 지역문제이기 때문에","mis":"SO4-2-u2-X01"}],"mis":"SO4-2-u2-X01","explanation":["처음엔 우리 집만이에요.","나중엔 이웃 여러 집이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["처음 — 내가 독감에 걸려 집에서 쉬었다. 우리 집만 불편했다.","나중 — 예방 수칙을 지키지 않고 밖에 나갔다.","그 뒤 — 이웃 여러 집에 독감이 옮아 이웃들도 앓게 되었다."],"title":"독감 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#8','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',2,'match','auto','카드와 그 일이 지역문제인 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"match","stem":"카드와 그 일이 지역문제인 까닭을 알맞게 이으세요.","pairs":[{"l":"공사장 소음","r":"여러 주민의 생활이 불편해져요"},{"l":"층간 소음","r":"이웃 사이에 갈등이 생겨요"},{"l":"쓰레기 무단 배출","r":"골목이 더러워져 여러 사람이 불편해요"}],"mis":"SO4-2-u2-X01","explanation":["소음은 생활을 불편하게 해요.","층간 소음은 다툼이에요.","쓰레기도 여럿이 불편해요."],"asset":{"type":"passage","lines":["가. 내가 독감에 걸려 집에서 쉬고 있어요.","나. 공사장에서 참기 힘든 소음이 나요.","다. 골목에 쓰레기를 아무 데나 버려요.","라. 층간 소음으로 위아래 집 사이에 다툼이 생겼어요."],"title":"네 장의 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#9','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',2,'blank','auto','기사 가처럼 도로가 물에 잠기는 문제를 해결하지 않으면 주민들이 마을 밖으로 (    ) 수 없어 불편해져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"blank","stem":"기사 가처럼 도로가 물에 잠기는 문제를 해결하지 않으면 주민들이 마을 밖으로 (    ) 수 없어 불편해져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"나갈","correct":true},{"t":"잠잘","mis":"SO4-2-u2-X04"},{"t":"노래할","mis":"SO4-2-u2-X04"},{"t":"웃을","mis":"SO4-2-u2-X04"}],"explanation":["도로가 잠겼어요.","길이 막혀요.","나갈 수 없어요."],"asset":{"type":"passage","lines":["기사 가 — 여름철 큰비가 오면 마을로 들어오는 도로가 물에 잠긴다.","기사 나 — 지역에 전해 오는 문화유산이 훼손되고 있다."],"title":"지역 신문 기사 두 장(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_basic#10','soc',4,2,'u2','L01','g4_2_soc_u2_L01_basic','lesson_basic','SO4-2-u2-C1',3,'mc','auto','기사 나의 문제를 해결하지 않으면 어떤 일이 일어날 수 있나요?',ARRAY['SO4-2-u2-X04','SO4-2-u2-X03']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"mc","stem":"기사 나의 문제를 해결하지 않으면 어떤 일이 일어날 수 있나요?","options":[{"t":"뒤에 올 사람들에게 물려줄 문화유산을 올바로 지키지 못할 수 있어요","correct":true},{"t":"문화유산이 저절로 새것이 돼요","mis":"SO4-2-u2-X04"},{"t":"아무 일도 일어나지 않아요","mis":"SO4-2-u2-X04"},{"t":"다른 지역의 문화유산이 생겨요","mis":"SO4-2-u2-X03"}],"explanation":["훼손되고 있어요.","그대로 두면요?","지키지 못해요."],"asset":{"type":"passage","lines":["기사 가 — 여름철 큰비가 오면 마을로 들어오는 도로가 물에 잠긴다.","기사 나 — 지역에 전해 오는 문화유산이 훼손되고 있다."],"title":"지역 신문 기사 두 장(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#1','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',2,'mc','auto','독감 이야기에서 독감이 지역문제로 바뀐 때는 언제인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X04']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"mc","stem":"독감 이야기에서 독감이 지역문제로 바뀐 때는 언제인가요?","options":[{"t":"이웃 여러 집에 독감이 옮았을 때","correct":true},{"t":"내가 처음 독감에 걸렸을 때","mis":"SO4-2-u2-X01"},{"t":"집에서 혼자 쉬었을 때","mis":"SO4-2-u2-X01"},{"t":"독감이 다 나았을 때","mis":"SO4-2-u2-X04"}],"explanation":["처음엔 우리 집만이에요.","이웃에게 옮았어요.","그때 바뀌었어요."],"asset":{"type":"passage","lines":["처음 — 내가 독감에 걸려 집에서 쉬었다. 우리 집만 불편했다.","나중 — 예방 수칙을 지키지 않고 밖에 나갔다.","그 뒤 — 이웃 여러 집에 독감이 옮아 이웃들도 앓게 되었다."],"title":"독감 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#2','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',2,'ox','auto','층간 소음은 두 집에만 닿으니 지역문제가 아니에요.',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"ox","stem":"층간 소음은 두 집에만 닿으니 지역문제가 아니에요.","answer":"X","reason_options":[{"t":"두 집이라도 주민들 사이에 갈등을 일으키는 문제이기 때문에","correct":true},{"t":"닿는 집이 적으면 언제나 개인의 일이기 때문에","mis":"SO4-2-u2-X01"}],"mis":"SO4-2-u2-X01","explanation":["몇 집인지보다요.","갈등이 생겼어요.","그래서 X예요."],"asset":{"type":"passage","lines":["가. 내가 독감에 걸려 집에서 쉬고 있어요.","나. 공사장에서 참기 힘든 소음이 나요.","다. 골목에 쓰레기를 아무 데나 버려요.","라. 층간 소음으로 위아래 집 사이에 다툼이 생겼어요."],"title":"네 장의 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#3','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',3,'mc','auto','개인의 일이 지역문제로 커질 수 있다는 것을 가장 잘 보여 주는 것은 무엇인가요?',ARRAY['SO4-2-u2-X03','SO4-2-u2-X04','SO4-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"mc","stem":"개인의 일이 지역문제로 커질 수 있다는 것을 가장 잘 보여 주는 것은 무엇인가요?","options":[{"t":"독감 이야기","correct":true},{"t":"세 동네의 지역문제","mis":"SO4-2-u2-X03"},{"t":"지역 신문 기사 나","mis":"SO4-2-u2-X04"},{"t":"공사장 소음 카드","mis":"SO4-2-u2-X02"}],"explanation":["처음과 나중이 달라요.","우리 집에서 이웃으로요.","독감 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#4','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',3,'error','auto','지역문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X03','SO4-2-u2-X01','SO4-2-u2-X02']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"error","stem":"지역문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지역문제는 어느 지역이나 똑같이 나타나.」","correct":true,"mis_target":"SO4-2-u2-X03"},{"t":"친구 가 — 「주민들 사이에 갈등을 일으키는 문제도 지역문제야.」","mis":"SO4-2-u2-X01"},{"t":"친구 다 — 「주민 모두가 함께 해결해야 해.」","mis":"SO4-2-u2-X02"}],"explanation":["세 동네를 떠올려요.","문제가 달랐어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["○○동 — 오래된 아파트가 많아 주차할 곳이 모자란다.","△△동 — 공장이 많아 하천으로 폐수가 흘러든다.","□□동 — 큰 도로가 하나뿐이라 아침마다 길이 막힌다."],"title":"세 동네의 지역문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#5','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',3,'mc','auto','지역문제의 특징으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X02','SO4-2-u2-X01']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"mc","stem":"지역문제의 특징으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"한 사람의 노력만으로 쉽게 해결할 수 있어요","correct":true},{"t":"지역 곳곳에서 일어나요","mis":"SO4-2-u2-X02"},{"t":"여러 사람과 관련된 공동의 문제예요","mis":"SO4-2-u2-X01"},{"t":"주민들이 함께 해결해야 해요","mis":"SO4-2-u2-X02"}],"explanation":["특징을 떠올려요.","혼자 해결할까요?","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#6','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',3,'ox','auto','세 동네의 문제가 서로 다른 까닭은 동네마다 상황이 다르기 때문이에요.',ARRAY['SO4-2-u2-X03']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"ox","stem":"세 동네의 문제가 서로 다른 까닭은 동네마다 상황이 다르기 때문이에요.","answer":"O","reason_options":[{"t":"아파트가 많은지, 공장이 많은지, 도로가 몇 개인지가 동네마다 다르기 때문에","correct":true},{"t":"지역문제는 아무렇게나 생기기 때문에","mis":"SO4-2-u2-X03"}],"mis":"SO4-2-u2-X03","explanation":["동네의 모습을 봐요.","저마다 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["○○동 — 오래된 아파트가 많아 주차할 곳이 모자란다.","△△동 — 공장이 많아 하천으로 폐수가 흘러든다.","□□동 — 큰 도로가 하나뿐이라 아침마다 길이 막힌다."],"title":"세 동네의 지역문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#7','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',3,'mc','auto','「주차 공간 부족」이 지역문제인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X04']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C1","difficulty":3,"kind":"mc","stem":"「주차 공간 부족」이 지역문제인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주차할 곳을 두고 주민들이 다투고 여러 사람이 불편해지기 때문이에요","correct":true},{"t":"차가 한 대뿐이기 때문이에요","mis":"SO4-2-u2-X01"},{"t":"주차는 개인의 취미이기 때문이에요","mis":"SO4-2-u2-X01"},{"t":"그냥 두면 저절로 나아지기 때문이에요","mis":"SO4-2-u2-X04"}],"explanation":["누가 불편할까요?","여러 주민이에요.","다툼도 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#8','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',4,'mc','auto','네 장의 카드와 독감 이야기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C1","difficulty":4,"kind":"mc","stem":"네 장의 카드와 독감 이야기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 주민의 생활이나 주민 사이의 관계에 닿으면 지역문제가 돼요","correct":true},{"t":"카드에 적힌 일은 모두 개인의 일이에요","mis":"SO4-2-u2-X01"},{"t":"지역문제는 처음부터 정해져 있어요","mis":"SO4-2-u2-X01"},{"t":"지역문제는 한 사람이 해결해요","mis":"SO4-2-u2-X02"}],"explanation":["닿는 집을 봐요.","여럿에게 닿아요.","지역문제가 돼요."],"asset":{"type":"passage","lines":["가. 내가 독감에 걸려 집에서 쉬고 있어요.","나. 공사장에서 참기 힘든 소음이 나요.","다. 골목에 쓰레기를 아무 데나 버려요.","라. 층간 소음으로 위아래 집 사이에 다툼이 생겼어요."],"title":"네 장의 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#9','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',4,'mc','auto','지역 신문 기사 두 장을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X04','SO4-2-u2-X02','SO4-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":4,"kind":"mc","stem":"지역 신문 기사 두 장을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역문제를 그냥 두면 주민의 불편이 계속되거나 소중한 것을 잃을 수 있어 함께 해결해야 해요","correct":true},{"t":"지역문제는 그냥 두면 저절로 사라져요","mis":"SO4-2-u2-X04"},{"t":"기사에 나온 문제는 기자가 해결해요","mis":"SO4-2-u2-X02"},{"t":"지역문제는 날씨와만 관련 있어요","mis":"SO4-2-u2-X03"}],"explanation":["가는 도로예요.","나는 문화유산이에요.","그냥 두면 안 돼요."],"asset":{"type":"passage","lines":["기사 가 — 여름철 큰비가 오면 마을로 들어오는 도로가 물에 잠긴다.","기사 나 — 지역에 전해 오는 문화유산이 훼손되고 있다."],"title":"지역 신문 기사 두 장(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L01_challenge#10','soc',4,2,'u2','L01','g4_2_soc_u2_L01_challenge','lesson_challenge','SO4-2-u2-C1',4,'essay','teacher','독감 이야기에서 「처음」은 개인의 일이고 「그 뒤」는 지역문제예요. 왜 그렇게 달라졌는지 지역문제의 뜻과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C1","difficulty":4,"kind":"essay","stem":"독감 이야기에서 「처음」은 개인의 일이고 「그 뒤」는 지역문제예요. 왜 그렇게 달라졌는지 지역문제의 뜻과 이어 쓰세요.","answer_guide":{"answer":"예: 처음에는 나 혼자 독감에 걸려 우리 집만 불편했으니 개인의 일이에요. 그 뒤에는 이웃 여러 집에 독감이 옮아 여러 주민의 생활을 불편하게 했으니, 지역 주민의 생활을 불편하게 하는 지역문제가 되었어요.","scoring_points":["처음이 개인의 일인 까닭을 썼는가","그 뒤에 여러 주민에게 닿았음을 썼는가","지역문제의 뜻과 이었는가"]},"explanation":["처음을 봐요.","그 뒤를 봐요.","뜻과 이어요."],"asset":{"type":"passage","lines":["처음 — 내가 독감에 걸려 집에서 쉬었다. 우리 집만 불편했다.","나중 — 예방 수칙을 지키지 않고 밖에 나갔다.","그 뒤 — 이웃 여러 집에 독감이 옮아 이웃들도 앓게 되었다."],"title":"독감 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#1','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',1,'mc','auto','우리 지역의 문제를 확인하는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X05']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"mc","stem":"우리 지역의 문제를 확인하는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"눈을 감고 상상하기","correct":true},{"t":"지역을 직접 둘러보기","mis":"SO4-2-u2-X05"},{"t":"지역 신문 기사 살펴보기","mis":"SO4-2-u2-X05"},{"t":"지역 주민과 면담하기","mis":"SO4-2-u2-X05"}],"explanation":["실제로 살펴봐요.","상상은 확인이 아니에요.","그것을 골라요."],"asset":{"type":"passage","lines":["㉠ 지역을 직접 둘러보며 찾아봐요.","㉡ 시·도청 누리집에서 주민이 올린 글을 찾아봐요.","㉢ 지역 신문 기사나 뉴스를 살펴봐요.","㉣ 지역 주민과 면담해요."],"title":"우리 지역의 문제를 확인하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#2','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',1,'sa','auto','지역 주민을 직접 만나 이야기를 나누며 지역의 문제를 알아보는 방법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"sa","stem":"지역 주민을 직접 만나 이야기를 나누며 지역의 문제를 알아보는 방법은 무엇인가요? 두 글자로 쓰세요.","answer":["면담"],"explanation":["만나서 이야기해요.","면◯이에요.","면담이에요."],"asset":{"type":"passage","lines":["㉠ 지역을 직접 둘러보며 찾아봐요.","㉡ 시·도청 누리집에서 주민이 올린 글을 찾아봐요.","㉢ 지역 신문 기사나 뉴스를 살펴봐요.","㉣ 지역 주민과 면담해요."],"title":"우리 지역의 문제를 확인하는 방법"},"mis":"SO4-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#3','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',1,'ox','auto','지역에서 일어나는 일에 관심을 가지면 지역에 어떤 문제가 있는지 알 수 있어요.',ARRAY['SO4-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"ox","stem":"지역에서 일어나는 일에 관심을 가지면 지역에 어떤 문제가 있는지 알 수 있어요.","answer":"O","reason_options":[{"t":"눈여겨보면 주민들이 겪는 불편이 보이기 때문에","correct":true},{"t":"지역문제는 관심과 관계없이 숨어 있기 때문에","mis":"SO4-2-u2-X05"}],"mis":"SO4-2-u2-X05","explanation":["관심을 가져요.","불편이 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#4','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',1,'mc','auto','친구 열둘이 찾은 지역문제에서 칸이 가장 많은 줄은 몇 개인가요?',ARRAY['SO4-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"mc","stem":"친구 열둘이 찾은 지역문제에서 칸이 가장 많은 줄은 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"SO4-2-u2-X06"},{"t":"3개","mis":"SO4-2-u2-X06"},{"t":"6개","mis":"SO4-2-u2-X06"}],"explanation":["칸을 세어요.","셋인 줄을 찾아요.","두 줄이에요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#5','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',2,'mc','auto','해결하고 싶은 지역문제를 정하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X06','SO4-2-u2-X08']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"mc","stem":"해결하고 싶은 지역문제를 정하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"조사한 결과를 참고해 모둠별로 토의하여 정해요","correct":true},{"t":"가위바위보로 정해요","mis":"SO4-2-u2-X06"},{"t":"가장 먼저 말한 사람의 생각으로 정해요","mis":"SO4-2-u2-X08"},{"t":"칸 수만 보고 판이 정해 줘요","mis":"SO4-2-u2-X06"}],"explanation":["조사 결과가 있어요.","이야기를 나눠요.","토의로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#6','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',2,'match','auto','우리 지역의 문제를 확인하는 방법과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"match","stem":"우리 지역의 문제를 확인하는 방법과 하는 일을 알맞게 이으세요.","pairs":[{"l":"직접 둘러보기","r":"지역 곳곳을 걸으며 살펴봐요"},{"l":"누리집 찾아보기","r":"주민이 올린 글을 읽어요"},{"l":"기사 살펴보기","r":"지역 신문이나 뉴스를 봐요"},{"l":"면담하기","r":"주민을 만나 이야기를 들어요"}],"mis":"SO4-2-u2-X05","explanation":["걷기예요.","글 읽기예요.","만나기도 있어요."],"asset":{"type":"passage","lines":["㉠ 지역을 직접 둘러보며 찾아봐요.","㉡ 시·도청 누리집에서 주민이 올린 글을 찾아봐요.","㉢ 지역 신문 기사나 뉴스를 살펴봐요.","㉣ 지역 주민과 면담해요."],"title":"우리 지역의 문제를 확인하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#7','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',2,'ox','auto','친구 열둘이 찾은 지역문제가 여러 가지로 나뉜 것은 사람마다 생각과 경험이 다르기 때문이에요.',ARRAY['SO4-2-u2-X07']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"ox","stem":"친구 열둘이 찾은 지역문제가 여러 가지로 나뉜 것은 사람마다 생각과 경험이 다르기 때문이에요.","answer":"O","reason_options":[{"t":"친구마다 겪은 불편이 서로 다르기 때문에","correct":true},{"t":"지역문제는 한 가지뿐이기 때문에","mis":"SO4-2-u2-X07"}],"mis":"SO4-2-u2-X07","explanation":["줄이 여섯이에요.","겪은 일이 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#8','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',2,'blank','auto','모둠에서 토의하면 서로의 생각을 주고받으며 의견의 (    )를 좁혀 갈 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"blank","stem":"모둠에서 토의하면 서로의 생각을 주고받으며 의견의 (    )를 좁혀 갈 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"차이","correct":true},{"t":"크기","mis":"SO4-2-u2-X06"},{"t":"소리","mis":"SO4-2-u2-X06"},{"t":"순서","mis":"SO4-2-u2-X06"}],"explanation":["생각이 서로 달라요.","그 거리를 줄여요.","차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#9','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',2,'mc','auto','해결하고 싶은 문제를 정하는 기준 ②에 맞는 물음은 무엇인가요?',ARRAY['SO4-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"mc","stem":"해결하고 싶은 문제를 정하는 기준 ②에 맞는 물음은 무엇인가요?","options":[{"t":"이 문제의 해결을 바라는 사람이 얼마나 많을까?","correct":true},{"t":"이 문제를 누가 먼저 말했을까?","mis":"SO4-2-u2-X08"},{"t":"이 문제의 이름이 멋질까?","mis":"SO4-2-u2-X08"},{"t":"이 문제를 해결하면 내가 상을 받을까?","mis":"SO4-2-u2-X08"}],"explanation":["기준 ②를 읽어요.","많은 사람이에요.","그 물음이에요."],"asset":{"type":"passage","lines":["기준 ① 문제를 얼마나 빨리 해결해야 하는가?","기준 ② 얼마나 많은 사람이 해결을 바라는가?","기준 ③ 내가 그 문제에 얼마나 관심이 있는가?"],"title":"해결하고 싶은 문제를 정하는 기준"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_basic#10','soc',4,2,'u2','L02','g4_2_soc_u2_L02_basic','lesson_basic','SO4-2-u2-C2',3,'mc','auto','친구 다의 말이 알맞은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X06','SO4-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"mc","stem":"친구 다의 말이 알맞은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"칸의 수는 참고하고, 기준에 맞춰 토의해 정하기 때문이에요","correct":true},{"t":"칸이 가장 적은 줄을 고르기 때문이에요","mis":"SO4-2-u2-X06"},{"t":"친구 가의 말을 무조건 따르기 때문이에요","mis":"SO4-2-u2-X06"},{"t":"문제는 한 가지뿐이기 때문이에요","mis":"SO4-2-u2-X07"}],"explanation":["칸이 같은 줄이 둘이에요.","기준으로 견줘요.","토의로 정해요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"칸이 가장 많은 교통 혼잡 문제로 바로 정하자."},{"who":"친구 나","text":"환경 오염 문제도 칸이 셋이야. 하천 냄새 때문에 불편한 사람이 많아."},{"who":"친구 다","text":"두 문제를 기준에 맞춰 견주어 보고 이야기를 나누어 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#1','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',2,'mc','auto','칸이 가장 많은 줄이 둘일 때 해결하고 싶은 문제를 정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X06','SO4-2-u2-X08']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"mc","stem":"칸이 가장 많은 줄이 둘일 때 해결하고 싶은 문제를 정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두 문제를 기준에 맞춰 견주고 모둠에서 이야기를 나누어 정해요","correct":true},{"t":"둘 다 지우고 처음부터 다시 세요","mis":"SO4-2-u2-X06"},{"t":"먼저 적힌 줄로 정해요","mis":"SO4-2-u2-X08"},{"t":"칸이 가장 적은 줄로 정해요","mis":"SO4-2-u2-X06"}],"explanation":["칸이 같아요.","횟수로는 못 가려요.","토의로 정해요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#2','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',2,'ox','auto','칸이 가장 많은 줄이 아닌 문제를 골라도, 토의로 까닭을 나누어 정했다면 괜찮아요.',ARRAY['SO4-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"ox","stem":"칸이 가장 많은 줄이 아닌 문제를 골라도, 토의로 까닭을 나누어 정했다면 괜찮아요.","answer":"O","reason_options":[{"t":"칸의 수는 참고하는 값이고 정하는 일은 토의로 하기 때문에","correct":true},{"t":"칸이 가장 많은 줄만 고를 수 있기 때문에","mis":"SO4-2-u2-X06"}],"mis":"SO4-2-u2-X06","explanation":["칸의 수는 참고예요.","토의로 정해요.","그래서 O예요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#3','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',3,'mc','auto','친구 가의 말에서 고쳐야 할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X06','SO4-2-u2-X08']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"mc","stem":"친구 가의 말에서 고쳐야 할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"칸이 같은 문제가 또 있으니 바로 정하지 말고 토의해야 해요","correct":true},{"t":"교통 혼잡은 지역문제가 아니에요","mis":"SO4-2-u2-X01"},{"t":"칸을 세면 안 돼요","mis":"SO4-2-u2-X06"},{"t":"기준은 하나도 필요 없어요","mis":"SO4-2-u2-X08"}],"explanation":["칸이 셋인 줄이 몇 개죠?","둘이에요.","바로 정하면 안 돼요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"칸이 가장 많은 교통 혼잡 문제로 바로 정하자."},{"who":"친구 나","text":"환경 오염 문제도 칸이 셋이야. 하천 냄새 때문에 불편한 사람이 많아."},{"who":"친구 다","text":"두 문제를 기준에 맞춰 견주어 보고 이야기를 나누어 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#4','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',3,'error','auto','해결하고 싶은 문제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"error","stem":"해결하고 싶은 문제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「목소리가 가장 큰 친구가 고른 문제로 하자.」","correct":true,"mis_target":"SO4-2-u2-X08"},{"t":"친구 가 — 「많은 사람이 해결을 바라는 문제를 생각해 보자.」","mis":"SO4-2-u2-X08"},{"t":"친구 다 — 「빨리 해결해야 하는 문제인지도 따져 보자.」","mis":"SO4-2-u2-X08"}],"explanation":["기준을 떠올려요.","목소리는 기준이 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["기준 ① 문제를 얼마나 빨리 해결해야 하는가?","기준 ② 얼마나 많은 사람이 해결을 바라는가?","기준 ③ 내가 그 문제에 얼마나 관심이 있는가?"],"title":"해결하고 싶은 문제를 정하는 기준"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#5','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',3,'mc','auto','하천 냄새 문제를 누리집 글로 확인했어요. 더 확실히 알아보려면 어떤 방법을 함께 쓰면 좋을까요?',ARRAY['SO4-2-u2-X05']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"mc","stem":"하천 냄새 문제를 누리집 글로 확인했어요. 더 확실히 알아보려면 어떤 방법을 함께 쓰면 좋을까요?","options":[{"t":"하천에 직접 가서 둘러보고 주변 주민과 면담해요","correct":true},{"t":"하천 냄새를 상상해 그려요","mis":"SO4-2-u2-X05"},{"t":"다른 지역 누리집 글을 옮겨 적어요","mis":"SO4-2-u2-X05"},{"t":"아무것도 더 하지 않아요","mis":"SO4-2-u2-X05"}],"explanation":["글로 알았어요.","직접 보고 들어요.","여러 방법을 함께 써요."],"asset":{"type":"passage","lines":["㉠ 지역을 직접 둘러보며 찾아봐요.","㉡ 시·도청 누리집에서 주민이 올린 글을 찾아봐요.","㉢ 지역 신문 기사나 뉴스를 살펴봐요.","㉣ 지역 주민과 면담해요."],"title":"우리 지역의 문제를 확인하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#6','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',3,'ox','auto','친구 열둘이 모두 같은 문제를 찾아야 제대로 조사한 거예요.',ARRAY['SO4-2-u2-X07']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"ox","stem":"친구 열둘이 모두 같은 문제를 찾아야 제대로 조사한 거예요.","answer":"X","reason_options":[{"t":"사람마다 생각과 경험이 달라 찾은 문제가 다양할 수 있기 때문에","correct":true},{"t":"모두 같아야 조사가 끝나기 때문에","mis":"SO4-2-u2-X07"}],"mis":"SO4-2-u2-X07","explanation":["줄이 여섯이었어요.","다양해도 괜찮아요.","그래서 X예요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#7','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',3,'mc','auto','기준 ①~③으로 견주었더니 환경 오염 문제가 더 빨리 해결해야 하는 문제였어요. 알맞은 생각은 무엇인가요?',ARRAY['SO4-2-u2-X06','SO4-2-u2-X08']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C2","difficulty":3,"kind":"mc","stem":"기준 ①~③으로 견주었더니 환경 오염 문제가 더 빨리 해결해야 하는 문제였어요. 알맞은 생각은 무엇인가요?","options":[{"t":"칸이 같으니 기준과 토의를 바탕으로 환경 오염 문제를 고를 수 있어요","correct":true},{"t":"칸이 같으면 아무것도 고를 수 없어요","mis":"SO4-2-u2-X06"},{"t":"먼저 말한 교통 혼잡을 골라야 해요","mis":"SO4-2-u2-X08"},{"t":"기준은 고르는 데 쓰면 안 돼요","mis":"SO4-2-u2-X08"}],"explanation":["칸은 똑같이 셋이에요.","기준 ①을 봤어요.","토의로 골라요."],"asset":{"type":"passage","lines":["기준 ① 문제를 얼마나 빨리 해결해야 하는가?","기준 ② 얼마나 많은 사람이 해결을 바라는가?","기준 ③ 내가 그 문제에 얼마나 관심이 있는가?"],"title":"해결하고 싶은 문제를 정하는 기준"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#8','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',4,'mc','auto','친구 열둘이 찾은 지역문제와 친구들의 대화를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X06','SO4-2-u2-X07']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C2","difficulty":4,"kind":"mc","stem":"친구 열둘이 찾은 지역문제와 친구들의 대화를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"조사 결과는 참고하고, 기준을 세워 토의해 해결하고 싶은 문제를 정해요","correct":true},{"t":"칸이 가장 많은 줄이 언제나 답이에요","mis":"SO4-2-u2-X06"},{"t":"대화는 문제를 정하는 데 필요 없어요","mis":"SO4-2-u2-X06"},{"t":"지역문제는 모두 같은 문제예요","mis":"SO4-2-u2-X07"}],"explanation":["칸이 같은 줄이 있어요.","대화를 나눴어요.","기준과 토의예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"칸이 가장 많은 교통 혼잡 문제로 바로 정하자."},{"who":"친구 나","text":"환경 오염 문제도 칸이 셋이야. 하천 냄새 때문에 불편한 사람이 많아."},{"who":"친구 다","text":"두 문제를 기준에 맞춰 견주어 보고 이야기를 나누어 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#9','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',4,'mc','auto','우리 지역의 문제를 찾는 방법 ㉠~㉣을 함께 쓰면 좋은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X05','SO4-2-u2-X04','SO4-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C2","difficulty":4,"kind":"mc","stem":"우리 지역의 문제를 찾는 방법 ㉠~㉣을 함께 쓰면 좋은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 곳에서 살펴보면 주민들이 겪는 불편을 빠짐없이 알 수 있어요","correct":true},{"t":"한 가지 방법은 모두 쓸모없어요","mis":"SO4-2-u2-X05"},{"t":"방법이 많을수록 문제가 사라져요","mis":"SO4-2-u2-X04"},{"t":"다른 지역의 문제를 알 수 있어요","mis":"SO4-2-u2-X03"}],"explanation":["보기·읽기·듣기가 있어요.","서로 채워 줘요.","빠짐없이 알아요."],"asset":{"type":"passage","lines":["㉠ 지역을 직접 둘러보며 찾아봐요.","㉡ 시·도청 누리집에서 주민이 올린 글을 찾아봐요.","㉢ 지역 신문 기사나 뉴스를 살펴봐요.","㉣ 지역 주민과 면담해요."],"title":"우리 지역의 문제를 확인하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L02_challenge#10','soc',4,2,'u2','L02','g4_2_soc_u2_L02_challenge','lesson_challenge','SO4-2-u2-C2',4,'essay','teacher','친구 열둘이 찾은 지역문제를 보고, 우리 모둠이 해결하고 싶은 문제를 하나 고른 뒤 기준 하나를 들어 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":4,"kind":"essay","stem":"친구 열둘이 찾은 지역문제를 보고, 우리 모둠이 해결하고 싶은 문제를 하나 고른 뒤 기준 하나를 들어 까닭을 쓰세요.","answer_guide":{"answer":"예: 환경 오염 문제를 고르고 싶어요. 하천으로 폐수가 흘러가면 물이 더러워지고 냄새가 나서 빨리 해결해야 하기 때문이에요(기준 ①). 모둠 친구들과도 이 까닭을 나누어 정할 거예요.","scoring_points":["문제를 하나 골랐는가","기준 하나를 들었는가","토의로 정한다는 점을 썼는가"]},"explanation":["문제를 골라요.","기준을 들어요.","까닭을 써요."],"asset":{"type":"passage","lines":["교통 혼잡 문제 — ✔✔✔","환경 오염 문제 — ✔✔✔","주차 문제 — ✔✔","쓰레기 문제 — ✔✔","안전 문제 — ✔","시설 부족 문제 — ✔"],"title":"친구 열둘이 찾은 지역문제(칸 하나 = 한 명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#1','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',1,'mc','auto','지역문제가 일어난 원인을 알려면 무엇이 필요한가요?',ARRAY['SO4-2-u2-X09']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"mc","stem":"지역문제가 일어난 원인을 알려면 무엇이 필요한가요?","options":[{"t":"지역문제와 관련 있는 다양한 자료","correct":true},{"t":"한 사람의 느낌","mis":"SO4-2-u2-X09"},{"t":"빠른 걸음","mis":"SO4-2-u2-X09"},{"t":"조용한 교실","mis":"SO4-2-u2-X09"}],"explanation":["사실을 확인해요.","자료가 필요해요.","다양한 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#2','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',1,'sa','auto','표나 그래프처럼 수를 정리해 나타낸 자료를 「○○ 자료」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"sa","stem":"표나 그래프처럼 수를 정리해 나타낸 자료를 「○○ 자료」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["통계"],"explanation":["수를 모아 정리해요.","통◯예요.","통계예요."],"asset":{"type":"passage","lines":["자료 ① 표 — 자동차 수와 주차 공간의 수","자료 ② 그래프 — 시간대별로 주차된 자동차 수","자료 ③ 신문 기사 — 불법 주차로 생긴 문제","자료 ④ 설문 조사 결과 — 주차 문제에 관한 주민 생각"],"title":"한 모둠이 모은 주차 문제 자료"},"mis":"SO4-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#3','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',1,'ox','auto','신문 기사와 설문 조사 결과도 지역문제와 관련 있는 자료가 될 수 있어요.',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"ox","stem":"신문 기사와 설문 조사 결과도 지역문제와 관련 있는 자료가 될 수 있어요.","answer":"O","reason_options":[{"t":"지역문제에 관한 사실이나 주민들의 생각을 알려 주기 때문에","correct":true},{"t":"자료는 표와 그래프뿐이기 때문에","mis":"SO4-2-u2-X11"}],"mis":"SO4-2-u2-X11","explanation":["자료 ③·④를 봐요.","기사와 설문이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["자료 ① 표 — 자동차 수와 주차 공간의 수","자료 ② 그래프 — 시간대별로 주차된 자동차 수","자료 ③ 신문 기사 — 불법 주차로 생긴 문제","자료 ④ 설문 조사 결과 — 주차 문제에 관한 주민 생각"],"title":"한 모둠이 모은 주차 문제 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#4','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',1,'mc','auto','자료를 모으는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"mc","stem":"자료를 모으는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"눈을 감고 떠올리기","correct":true},{"t":"문제가 일어난 장소를 찾아가 살펴보기","mis":"SO4-2-u2-X11"},{"t":"시·도청 누리집에서 자료 찾기","mis":"SO4-2-u2-X11"},{"t":"주민에게 설문 조사하기","mis":"SO4-2-u2-X11"}],"explanation":["실제로 살펴봐요.","떠올리기는 아니에요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#5','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',2,'mc','auto','정보 ②는 어떤 자료에서 찾은 것인가요?',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"mc","stem":"정보 ②는 어떤 자료에서 찾은 것인가요?","options":[{"t":"자료 ② 그래프","correct":true},{"t":"자료 ① 표","mis":"SO4-2-u2-X11"},{"t":"자료 ③ 신문 기사","mis":"SO4-2-u2-X11"},{"t":"자료 ④ 설문 조사 결과","mis":"SO4-2-u2-X11"}],"explanation":["시간대가 나와요.","저녁에 부족해요.","그래프예요."],"asset":{"type":"passage","lines":["① 자동차 수에 비해 주차 공간의 수가 부족해요.","② 낮보다는 주로 저녁에 주차 공간이 부족해요.","③ 불법 주차로 생기는 문제를 잘 모르는 사람이 많아요.","④ 정해진 곳에 주차해야 하는 규칙을 지키려는 마음이 부족해요."],"title":"자료에서 찾은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#6','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',2,'match','auto','자료와 그 자료에서 찾은 정보를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"match","stem":"자료와 그 자료에서 찾은 정보를 알맞게 이으세요.","pairs":[{"l":"표","r":"자동차 수에 비해 주차 공간이 부족해요"},{"l":"그래프","r":"주로 저녁에 주차 공간이 부족해요"},{"l":"신문 기사","r":"불법 주차 문제를 잘 모르는 사람이 많아요"},{"l":"설문 조사 결과","r":"규칙을 지키려는 마음이 부족해요"}],"mis":"SO4-2-u2-X11","explanation":["표는 수를 견줘요.","그래프는 시간대예요.","기사와 설문도 이어요."],"asset":{"type":"passage","lines":["① 자동차 수에 비해 주차 공간의 수가 부족해요.","② 낮보다는 주로 저녁에 주차 공간이 부족해요.","③ 불법 주차로 생기는 문제를 잘 모르는 사람이 많아요.","④ 정해진 곳에 주차해야 하는 규칙을 지키려는 마음이 부족해요."],"title":"자료에서 찾은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#7','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',2,'ox','auto','정보를 종합해 찾은 원인 ㉮는 자료 한 장만 보고 알아낸 거예요.',ARRAY['SO4-2-u2-X10']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"ox","stem":"정보를 종합해 찾은 원인 ㉮는 자료 한 장만 보고 알아낸 거예요.","answer":"X","reason_options":[{"t":"정보 ①과 ②를 함께 보아서 알아낸 것이기 때문에","correct":true},{"t":"원인은 언제나 자료 한 장이면 충분하기 때문에","mis":"SO4-2-u2-X10"}],"mis":"SO4-2-u2-X10","explanation":["괄호를 읽어요.","①·② 둘이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["원인 ㉮ — 주차 공간이 부족해요. (정보 ①·② 를 함께 보아서)","원인 ㉯ — 불법 주차 피해가 얼마나 심각한지 잘 모르는 주민이 많아요. (정보 ③·④ 를 함께 보아서)"],"title":"정보를 종합해 찾은 원인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
