INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_basic#10','soc',4,2,'u2','L03','g4_2_soc_u2_L03_basic','lesson_basic','SO4-2-u2-C3',3,'mc','auto','의견 가와 의견 나 가운데 원인을 알아보는 방법으로 더 알맞은 것과 그 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X09']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"mc","stem":"의견 가와 의견 나 가운데 원인을 알아보는 방법으로 더 알맞은 것과 그 까닭은 무엇인가요?","options":[{"t":"의견 나 — 사실을 확인할 수 있는 자료를 모으기 때문이에요","correct":true},{"t":"의견 가 — 느낌만으로 정할 수 있기 때문이에요","mis":"SO4-2-u2-X09"},{"t":"의견 가 — 가장 먼저 말했기 때문이에요","mis":"SO4-2-u2-X09"},{"t":"둘 다 아니에요 — 원인은 찾을 수 없기 때문이에요","mis":"SO4-2-u2-X09"}],"explanation":["길이를 재고 수를 조사해요.","사실을 확인해요.","의견 나예요."],"asset":{"type":"passage","lines":["문제 — 우리 동네에는 자전거가 다닐 길이 좁아요.","의견 가 — 「자전거 타는 사람이 조심하면 돼요.」","의견 나 — 「자전거 도로 길이를 재 보고, 이용하는 사람 수를 조사해 봐요.」"],"title":"자전거 길 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#1','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',2,'mc','auto','자료 ④를 빼면 정보를 종합해 찾은 원인 가운데 어느 것을 세우기 어려워지나요?',ARRAY['SO4-2-u2-X10']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"mc","stem":"자료 ④를 빼면 정보를 종합해 찾은 원인 가운데 어느 것을 세우기 어려워지나요?","options":[{"t":"원인 ㉯","correct":true},{"t":"원인 ㉮","mis":"SO4-2-u2-X10"},{"t":"둘 다 그대로 서요","mis":"SO4-2-u2-X10"},{"t":"원인이 하나 더 생겨요","mis":"SO4-2-u2-X10"}],"explanation":["④는 어디에 쓰였나요?","㉯의 괄호예요.","㉯가 어려워요."],"asset":{"type":"passage","lines":["원인 ㉮ — 주차 공간이 부족해요. (정보 ①·② 를 함께 보아서)","원인 ㉯ — 불법 주차 피해가 얼마나 심각한지 잘 모르는 주민이 많아요. (정보 ③·④ 를 함께 보아서)"],"title":"정보를 종합해 찾은 원인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#2','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',2,'ox','auto','「낮보다는 주로 저녁에 주차 공간이 부족해요」는 자료에서 찾은 정보예요.',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"ox","stem":"「낮보다는 주로 저녁에 주차 공간이 부족해요」는 자료에서 찾은 정보예요.","answer":"O","reason_options":[{"t":"그래프를 분석해서 알아낸 내용이기 때문에","correct":true},{"t":"자료를 모으는 방법이기 때문에","mis":"SO4-2-u2-X11"}],"mis":"SO4-2-u2-X11","explanation":["그래프에서 나왔어요.","알아낸 내용이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 자동차 수에 비해 주차 공간의 수가 부족해요.","② 낮보다는 주로 저녁에 주차 공간이 부족해요.","③ 불법 주차로 생기는 문제를 잘 모르는 사람이 많아요.","④ 정해진 곳에 주차해야 하는 규칙을 지키려는 마음이 부족해요."],"title":"자료에서 찾은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#3','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',3,'mc','auto','한 모둠이 주차 문제의 원인을 알아본 차례로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X10','SO4-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"mc","stem":"한 모둠이 주차 문제의 원인을 알아본 차례로 알맞은 것은 무엇인가요?","options":[{"t":"자료를 모아 정보를 찾고, 그 뜻을 해석해 종합한 뒤 원인을 파악했어요","correct":true},{"t":"원인을 먼저 정하고 그에 맞는 자료만 모았어요","mis":"SO4-2-u2-X09"},{"t":"자료 한 장을 보고 바로 원인을 정했어요","mis":"SO4-2-u2-X10"},{"t":"자료를 모으기만 하면 원인이 저절로 적혔어요","mis":"SO4-2-u2-X11"}],"explanation":["자료가 먼저예요.","정보와 뜻을 봐요.","종합해 원인이에요."],"asset":{"type":"passage","lines":["자료 ① 표 — 자동차 수와 주차 공간의 수","자료 ② 그래프 — 시간대별로 주차된 자동차 수","자료 ③ 신문 기사 — 불법 주차로 생긴 문제","자료 ④ 설문 조사 결과 — 주차 문제에 관한 주민 생각"],"title":"한 모둠이 모은 주차 문제 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#4','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',3,'error','auto','원인을 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X10']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"error","stem":"원인을 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「원인을 먼저 정해 놓고 그 원인에 맞는 자료만 모으자.」","correct":true,"mis_target":"SO4-2-u2-X09"},{"t":"친구 가 — 「표와 그래프를 함께 보니 주차 공간이 부족해.」","mis":"SO4-2-u2-X10"},{"t":"친구 나 — 「기사와 설문을 겹쳐 보니 피해를 잘 몰라.」","mis":"SO4-2-u2-X10"}],"explanation":["자료가 먼저일까요?","원인이 먼저면 안 돼요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 자동차 수에 비해 주차 공간의 수가 부족해요.","② 낮보다는 주로 저녁에 주차 공간이 부족해요.","③ 불법 주차로 생기는 문제를 잘 모르는 사람이 많아요.","④ 정해진 곳에 주차해야 하는 규칙을 지키려는 마음이 부족해요."],"title":"자료에서 찾은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#5','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',3,'mc','auto','원인을 알아볼 때 의견만이 아니라 사실을 확인하는 자료를 함께 보는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X10']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"mc","stem":"원인을 알아볼 때 의견만이 아니라 사실을 확인하는 자료를 함께 보는 까닭은 무엇인가요?","options":[{"t":"느낌이나 의견만으로는 문제가 일어난 까닭을 확인하기 어렵기 때문이에요","correct":true},{"t":"의견은 모두 잘못되었기 때문이에요","mis":"SO4-2-u2-X09"},{"t":"자료가 많을수록 빨리 끝나기 때문이에요","mis":"SO4-2-u2-X10"},{"t":"자료를 모으는 일이 재미있기 때문이에요","mis":"SO4-2-u2-X09"}],"explanation":["의견은 사람마다 달라요.","사실을 확인해요.","그래서 자료가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#6','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',3,'ox','auto','자전거 길 이야기에서 의견 가만으로도 자전거 길 문제의 원인을 확실히 알 수 있어요.',ARRAY['SO4-2-u2-X09']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"ox","stem":"자전거 길 이야기에서 의견 가만으로도 자전거 길 문제의 원인을 확실히 알 수 있어요.","answer":"X","reason_options":[{"t":"의견 가는 사실을 확인하는 자료 없이 말한 의견이기 때문에","correct":true},{"t":"의견은 언제나 사실과 같기 때문에","mis":"SO4-2-u2-X09"}],"mis":"SO4-2-u2-X09","explanation":["의견 가를 읽어요.","자료가 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["문제 — 우리 동네에는 자전거가 다닐 길이 좁아요.","의견 가 — 「자전거 타는 사람이 조심하면 돼요.」","의견 나 — 「자전거 도로 길이를 재 보고, 이용하는 사람 수를 조사해 봐요.」"],"title":"자전거 길 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#7','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',3,'mc','auto','자전거 길 문제의 원인을 찾으려고 모을 자료로 가장 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"mc","stem":"자전거 길 문제의 원인을 찾으려고 모을 자료로 가장 알맞지 않은 것은 무엇인가요?","options":[{"t":"친구가 좋아하는 자전거 색깔","correct":true},{"t":"자전거 도로 길이를 정리한 표","mis":"SO4-2-u2-X11"},{"t":"자전거 이용자 수를 나타낸 그래프","mis":"SO4-2-u2-X11"},{"t":"자전거 길에 관한 주민 설문 조사 결과","mis":"SO4-2-u2-X11"}],"explanation":["문제와 관련 있나요?","색깔은 관계없어요.","그것을 골라요."],"asset":{"type":"passage","lines":["문제 — 우리 동네에는 자전거가 다닐 길이 좁아요.","의견 가 — 「자전거 타는 사람이 조심하면 돼요.」","의견 나 — 「자전거 도로 길이를 재 보고, 이용하는 사람 수를 조사해 봐요.」"],"title":"자전거 길 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#8','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',4,'mc','auto','자료를 하나 빼면 원인 하나가 서지 못하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X10','SO4-2-u2-X11']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C3","difficulty":4,"kind":"mc","stem":"자료를 하나 빼면 원인 하나가 서지 못하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"원인은 여러 자료에서 찾은 정보를 종합해야 보이기 때문이에요","correct":true},{"t":"원인은 자료와 관계없기 때문이에요","mis":"SO4-2-u2-X09"},{"t":"자료 한 장만 있어도 원인이 보이기 때문이에요","mis":"SO4-2-u2-X10"},{"t":"자료의 종류는 하나뿐이기 때문이에요","mis":"SO4-2-u2-X11"}],"explanation":["㉮는 ①·②예요.","하나가 빠지면요?","종합이 안 돼요."],"asset":{"type":"passage","lines":["원인 ㉮ — 주차 공간이 부족해요. (정보 ①·② 를 함께 보아서)","원인 ㉯ — 불법 주차 피해가 얼마나 심각한지 잘 모르는 주민이 많아요. (정보 ③·④ 를 함께 보아서)"],"title":"정보를 종합해 찾은 원인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#9','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',4,'mc','auto','자료 넷·정보 넷·원인 둘을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X11','SO4-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C3","difficulty":4,"kind":"mc","stem":"자료 넷·정보 넷·원인 둘을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다양한 자료를 모아 분석하고 정보를 종합하면 지역문제의 원인을 찾을 수 있어요","correct":true},{"t":"원인은 사람마다 마음대로 정해요","mis":"SO4-2-u2-X09"},{"t":"정보와 원인은 같은 말이에요","mis":"SO4-2-u2-X11"},{"t":"원인은 알 수 없으니 그냥 둬요","mis":"SO4-2-u2-X04"}],"explanation":["자료가 넷이에요.","정보도 넷이에요.","원인은 둘이에요."],"asset":{"type":"passage","lines":["원인 ㉮ — 주차 공간이 부족해요. (정보 ①·② 를 함께 보아서)","원인 ㉯ — 불법 주차 피해가 얼마나 심각한지 잘 모르는 주민이 많아요. (정보 ③·④ 를 함께 보아서)"],"title":"정보를 종합해 찾은 원인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L03_challenge#10','soc',4,2,'u2','L03','g4_2_soc_u2_L03_challenge','lesson_challenge','SO4-2-u2-C3',4,'essay','teacher','자전거 길 문제의 원인을 찾으려고 해요. 모을 자료 두 가지와 모으는 방법을 쓰고, 왜 자료를 여러 가지 모아야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C3","difficulty":4,"kind":"essay","stem":"자전거 길 문제의 원인을 찾으려고 해요. 모을 자료 두 가지와 모으는 방법을 쓰고, 왜 자료를 여러 가지 모아야 하는지 쓰세요.","answer_guide":{"answer":"예: 자전거 도로 길이를 정리한 표는 시·도청 누리집에서 찾고, 자전거 길에 관한 주민 생각은 설문 조사로 모을 거예요. 자료 한 장만으로는 원인을 알기 어렵고, 여러 자료에서 찾은 정보를 종합해야 원인이 보이기 때문이에요.","scoring_points":["자료 두 가지를 썼는가","모으는 방법을 썼는가","여러 자료를 종합하는 까닭을 썼는가"]},"explanation":["자료를 정해요.","방법을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["문제 — 우리 동네에는 자전거가 다닐 길이 좁아요.","의견 가 — 「자전거 타는 사람이 조심하면 돼요.」","의견 나 — 「자전거 도로 길이를 재 보고, 이용하는 사람 수를 조사해 봐요.」"],"title":"자전거 길 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#1','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',1,'mc','auto','지역문제의 해결 방안은 언제 찾나요?',ARRAY['SO4-2-u2-X12']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"mc","stem":"지역문제의 해결 방안은 언제 찾나요?","options":[{"t":"문제가 일어난 원인을 알아본 후에","correct":true},{"t":"문제를 찾기 전에","mis":"SO4-2-u2-X12"},{"t":"원인과 상관없이 아무 때나","mis":"SO4-2-u2-X12"},{"t":"실천을 모두 마친 뒤에","mis":"SO4-2-u2-X12"}],"explanation":["지난 시간을 떠올려요.","원인을 알아봤어요.","그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#2','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',1,'sa','auto','해결 방안을 평가하는 기준 가운데 「얼마나 큰 도움이 되는가?」를 묻는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"sa","stem":"해결 방안을 평가하는 기준 가운데 「얼마나 큰 도움이 되는가?」를 묻는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["효과"],"explanation":["도움이 큰지 봐요.","효◯예요.","효과예요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"},"mis":"SO4-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#3','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',1,'ox','auto','해결 방안을 평가하는 기준에 「누군가에게 피해를 주지 않나요?」도 들어가요.',ARRAY['SO4-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"ox","stem":"해결 방안을 평가하는 기준에 「누군가에게 피해를 주지 않나요?」도 들어가요.","answer":"O","reason_options":[{"t":"해결 방안이 다른 사람을 힘들게 하면 안 되기 때문에","correct":true},{"t":"피해는 해결 방안과 관계없기 때문에","mis":"SO4-2-u2-X13"}],"mis":"SO4-2-u2-X13","explanation":["기준 넷을 떠올려요.","피해 없음이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#4','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',1,'mc','auto','해결 방안을 평가하는 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X13']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"mc","stem":"해결 방안을 평가하는 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"누가 먼저 말했나요?","correct":true},{"t":"효과가 큰가요?","mis":"SO4-2-u2-X13"},{"t":"비용이 적게 드나요?","mis":"SO4-2-u2-X13"},{"t":"실천할 수 있나요?","mis":"SO4-2-u2-X13"}],"explanation":["방안을 살피는 기준이에요.","말한 사람은 관계없어요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#5','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',2,'mc','auto','여러 해결 방안이 나왔을 때 해야 할 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X12','SO4-2-u2-X15','SO4-2-u2-X14']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"mc","stem":"여러 해결 방안이 나왔을 때 해야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"각 방안의 장단점을 비교하고 대화와 타협으로 의견을 조정해요","correct":true},{"t":"가장 먼저 떠오른 방안으로 정해요","mis":"SO4-2-u2-X12"},{"t":"의견이 다르면 그만둬요","mis":"SO4-2-u2-X15"},{"t":"방안을 모두 버려요","mis":"SO4-2-u2-X14"}],"explanation":["방안이 여럿이에요.","좋은 점과 아쉬운 점이 있어요.","견주고 조정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#6','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',2,'match','auto','평가표에서 각 방안의 1점 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"match","stem":"평가표에서 각 방안의 1점 자리를 알맞게 이으세요.","pairs":[{"l":"㉮ 분리배출 교육","r":"효과"},{"l":"㉯ 캠페인","r":"실천"},{"l":"㉰ 봉투 가격 올리기","r":"실천과 피해 없음"}],"mis":"SO4-2-u2-X14","explanation":["㉮의 첫 칸이 1이에요.","㉯는 셋째 칸이에요.","㉰는 둘이에요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#7','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',2,'ox','auto','평가표에서 더한 값이 가장 큰 ㉮도 처음에는 「멈춰」예요.',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"ox","stem":"평가표에서 더한 값이 가장 큰 ㉮도 처음에는 「멈춰」예요.","answer":"O","reason_options":[{"t":"네 기준 가운데 1점인 자리가 하나 있기 때문에","correct":true},{"t":"더한 값이 가장 작기 때문에","mis":"SO4-2-u2-X14"}],"mis":"SO4-2-u2-X14","explanation":["㉮는 10이에요.","그런데 1점이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#8','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',2,'blank','auto','평가 기준에서 부족한 점수를 받은 해결 방안은 곧바로 버리지 않고 부족한 부분을 (    )하여 수정해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"blank","stem":"평가 기준에서 부족한 점수를 받은 해결 방안은 곧바로 버리지 않고 부족한 부분을 (    )하여 수정해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"보완","correct":true},{"t":"포기","mis":"SO4-2-u2-X14"},{"t":"비밀","mis":"SO4-2-u2-X14"},{"t":"반복","mis":"SO4-2-u2-X14"}],"explanation":["버리지 않아요.","고쳐서 채워요.","보완이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#9','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',2,'mc','auto','보완할 점 넷 가운데 ㉯ 캠페인의 부족한 자리를 채우기에 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"mc","stem":"보완할 점 넷 가운데 ㉯ 캠페인의 부족한 자리를 채우기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"보완 ②","correct":true},{"t":"보완 ①","mis":"SO4-2-u2-X14"},{"t":"보완 ③","mis":"SO4-2-u2-X14"},{"t":"보완 ④","mis":"SO4-2-u2-X14"}],"explanation":["㉯는 실천이 1점이에요.","할 수 있게 미리 협의해요.","보완 ②예요."],"asset":{"type":"passage","lines":["보완 ① 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내해요.","보완 ② 캠페인의 구체적인 방법을 미리 충분히 협의하고 홍보해요.","보완 ③ 공공 기관의 협조를 구하는 제안서를 써요.","보완 ④ 분리배출을 잘하는 주민에게 지역 시장에서 쓸 포인트를 쌓아 줘요."],"title":"보완할 점 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_basic#10','soc',4,2,'u2','L04','g4_2_soc_u2_L04_basic','lesson_basic','SO4-2-u2-C4',3,'mc','auto','내가 낸 해결 방안이 친구들과 다를 때 알맞은 태도는 무엇인가요?',ARRAY['SO4-2-u2-X15']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"mc","stem":"내가 낸 해결 방안이 친구들과 다를 때 알맞은 태도는 무엇인가요?","options":[{"t":"자료와 사실에 근거해 의견을 내고 대화와 타협으로 조정해요","correct":true},{"t":"내 의견을 끝까지 고집해요","mis":"SO4-2-u2-X15"},{"t":"친구 의견을 무조건 따라요","mis":"SO4-2-u2-X15"},{"t":"의견을 내지 않고 가만히 있어요","mis":"SO4-2-u2-X15"}],"explanation":["의견이 달라요.","근거를 들어요.","대화와 타협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#1','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',2,'mc','auto','평가표에서 ㉰를 「계속」으로 바꾸려면 몇 자리를 보완해야 하나요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"mc","stem":"평가표에서 ㉰를 「계속」으로 바꾸려면 몇 자리를 보완해야 하나요?","options":[{"t":"2자리","correct":true},{"t":"1자리","mis":"SO4-2-u2-X14"},{"t":"3자리","mis":"SO4-2-u2-X14"},{"t":"보완하지 않아도 돼요","mis":"SO4-2-u2-X14"}],"explanation":["㉰의 1점을 세어요.","실천과 피해 없음이에요.","두 자리예요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#2','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',2,'ox','auto','㉰에 보완 ③만 하면 ㉰는 「계속」이 돼요.',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"ox","stem":"㉰에 보완 ③만 하면 ㉰는 「계속」이 돼요.","answer":"X","reason_options":[{"t":"피해 없음 자리가 아직 1점으로 남아 있기 때문에","correct":true},{"t":"한 자리만 보완하면 언제나 계속이 되기 때문에","mis":"SO4-2-u2-X14"}],"mis":"SO4-2-u2-X14","explanation":["③은 실천을 채워요.","피해 없음이 남았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["보완 ① 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내해요.","보완 ② 캠페인의 구체적인 방법을 미리 충분히 협의하고 홍보해요.","보완 ③ 공공 기관의 협조를 구하는 제안서를 써요.","보완 ④ 분리배출을 잘하는 주민에게 지역 시장에서 쓸 포인트를 쌓아 줘요."],"title":"보완할 점 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#3','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',3,'mc','auto','더한 값이 가장 큰 방안을 바로 고르지 않는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X14','SO4-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"mc","stem":"더한 값이 가장 큰 방안을 바로 고르지 않는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"더한 값이 커도 부족한 자리가 있으면 실제로 문제를 풀기 어렵기 때문이에요","correct":true},{"t":"더한 값이 가장 작은 방안이 언제나 좋기 때문이에요","mis":"SO4-2-u2-X14"},{"t":"점수는 처음부터 쓸모없기 때문이에요","mis":"SO4-2-u2-X13"},{"t":"먼저 말한 방안을 골라야 하기 때문이에요","mis":"SO4-2-u2-X13"}],"explanation":["㉮는 10이에요.","효과가 1이에요.","부족한 자리가 있어요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#4','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',3,'error','auto','해결 방안을 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X14','SO4-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"error","stem":"해결 방안을 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉰는 1점이 둘이니 아예 버리자.」","correct":true,"mis_target":"SO4-2-u2-X14"},{"t":"친구 나 — 「㉰도 제안서와 포인트로 보완해 보자.」","mis":"SO4-2-u2-X14"},{"t":"친구 다 — 「장단점을 견주고 대화로 맞추자.」","mis":"SO4-2-u2-X15"}],"explanation":["1점이 둘이에요.","버릴까요?","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["보완 ① 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내해요.","보완 ② 캠페인의 구체적인 방법을 미리 충분히 협의하고 홍보해요.","보완 ③ 공공 기관의 협조를 구하는 제안서를 써요.","보완 ④ 분리배출을 잘하는 주민에게 지역 시장에서 쓸 포인트를 쌓아 줘요."],"title":"보완할 점 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#5','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',3,'mc','auto','보완 ④는 ㉰의 어느 자리를 채우나요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"mc","stem":"보완 ④는 ㉰의 어느 자리를 채우나요?","options":[{"t":"피해 없음","correct":true},{"t":"효과","mis":"SO4-2-u2-X14"},{"t":"비용","mis":"SO4-2-u2-X14"},{"t":"실천","mis":"SO4-2-u2-X14"}],"explanation":["가격이 오르면 부담돼요.","포인트로 덜어 줘요.","피해 없음이에요."],"asset":{"type":"passage","lines":["보완 ① 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내해요.","보완 ② 캠페인의 구체적인 방법을 미리 충분히 협의하고 홍보해요.","보완 ③ 공공 기관의 협조를 구하는 제안서를 써요.","보완 ④ 분리배출을 잘하는 주민에게 지역 시장에서 쓸 포인트를 쌓아 줘요."],"title":"보완할 점 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#6','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',3,'ox','auto','공유 주차장은 주차 공간이 부족하다는 원인과 이어진 해결 방안이에요.',ARRAY['SO4-2-u2-X12']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"ox","stem":"공유 주차장은 주차 공간이 부족하다는 원인과 이어진 해결 방안이에요.","answer":"O","reason_options":[{"t":"공간을 나누어 써서 부족한 주차 공간을 채우기 때문에","correct":true},{"t":"공유는 원인과 관계없는 방안이기 때문에","mis":"SO4-2-u2-X12"}],"mis":"SO4-2-u2-X12","explanation":["원인은 공간 부족이에요.","나누어 써요.","그래서 O예요."],"asset":{"type":"passage","lines":["물건이나 공간을 서로 나누고 빌려 쓰는 것을 공유라고 해요.","공유 주차장 — 주차 공간이 부족한 문제를 풀려고 만들었어요.","공공 자전거 — 교통 혼잡과 대기 오염 문제를 풀려고 들였어요."],"title":"나누고 빌려 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#7','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',3,'mc','auto','「자전거 길이 부족하니 모든 도로를 좁혀 자전거 길로 만들자」는 의견을 보완해야 하는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X12','SO4-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"mc","stem":"「자전거 길이 부족하니 모든 도로를 좁혀 자전거 길로 만들자」는 의견을 보완해야 하는 까닭은 무엇인가요?","options":[{"t":"도로가 좁아져 교통 혼잡이라는 다른 문제가 생길 수 있기 때문이에요","correct":true},{"t":"자전거 길은 원래 필요 없기 때문이에요","mis":"SO4-2-u2-X12"},{"t":"의견을 낸 사람이 어리기 때문이에요","mis":"SO4-2-u2-X13"},{"t":"비용이 전혀 들지 않기 때문이에요","mis":"SO4-2-u2-X13"}],"explanation":["모든 도로를 좁혀요.","차는 어떻게 될까요?","다른 피해가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#8','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',4,'mc','auto','평가표와 보완할 점을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X14','SO4-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C4","difficulty":4,"kind":"mc","stem":"평가표와 보완할 점을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"기준으로 재어 부족한 자리를 찾고 보완해 더 합리적인 방안을 정해요","correct":true},{"t":"더한 값이 가장 큰 방안을 바로 골라요","mis":"SO4-2-u2-X14"},{"t":"1점이 있는 방안은 모두 버려요","mis":"SO4-2-u2-X14"},{"t":"기준은 아무렇게나 정해요","mis":"SO4-2-u2-X13"}],"explanation":["기준으로 재요.","부족한 자리가 보여요.","보완해요."],"asset":{"type":"passage","lines":["보완 ① 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내해요.","보완 ② 캠페인의 구체적인 방법을 미리 충분히 협의하고 홍보해요.","보완 ③ 공공 기관의 협조를 구하는 제안서를 써요.","보완 ④ 분리배출을 잘하는 주민에게 지역 시장에서 쓸 포인트를 쌓아 줘요."],"title":"보완할 점 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#9','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',4,'mc','auto','공유 주차장과 공공 자전거를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X12','SO4-2-u2-X13']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C4","difficulty":4,"kind":"mc","stem":"공유 주차장과 공공 자전거를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"원인에 맞는 방안을 찾으면 자원과 비용을 아끼며 지역문제를 풀 수 있어요","correct":true},{"t":"공유는 지역문제와 관계없어요","mis":"SO4-2-u2-X12"},{"t":"해결 방안은 한 가지 문제에만 써요","mis":"SO4-2-u2-X12"},{"t":"공유하면 비용이 더 많이 들어요","mis":"SO4-2-u2-X13"}],"explanation":["주차와 교통이에요.","나누어 써요.","원인과 이어져요."],"asset":{"type":"passage","lines":["물건이나 공간을 서로 나누고 빌려 쓰는 것을 공유라고 해요.","공유 주차장 — 주차 공간이 부족한 문제를 풀려고 만들었어요.","공공 자전거 — 교통 혼잡과 대기 오염 문제를 풀려고 들였어요."],"title":"나누고 빌려 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L04_challenge#10','soc',4,2,'u2','L04','g4_2_soc_u2_L04_challenge','lesson_challenge','SO4-2-u2-C4',4,'essay','teacher','평가표에서 ㉮를 골라 부족한 자리를 찾고, 어떻게 보완하면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C4","difficulty":4,"kind":"essay","stem":"평가표에서 ㉮를 골라 부족한 자리를 찾고, 어떻게 보완하면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ㉮ 분리배출 교육은 효과가 1점이라 부족해요. 학교에서만 교육하면 집에서는 잘 지키지 않을 수 있으니, 가정에도 분리배출의 중요성을 알리는 자료를 만들어 안내하면 효과가 커질 거예요.","scoring_points":["부족한 자리를 바르게 찾았는가","보완 방법을 썼는가","보완하면 나아지는 까닭을 썼는가"]},"explanation":["1점을 찾아요.","보완 방법을 정해요.","까닭을 써요."],"asset":{"type":"passage","lines":["기준 — 효과 · 비용 · 실천 · 피해 없음 (3 매우 그렇다 · 2 그렇다 · 1 보통)","㉮ 분리배출 교육 — 1 · 3 · 3 · 3 (더한 값 10)","㉯ 캠페인 — 2 · 3 · 1 · 3 (더한 값 9)","㉰ 봉투 가격 올리기 — 3 · 3 · 1 · 1 (더한 값 8)","규칙 — 1점인 자리가 하나라도 있으면 「멈춰」, 보완해서 고쳐요."],"title":"한 모둠의 평가표(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#1','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',1,'mc','auto','주민들의 의견을 모아 해결 방안을 정한 다음에 할 일은 무엇인가요?',ARRAY['SO4-2-u2-X16']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"mc","stem":"주민들의 의견을 모아 해결 방안을 정한 다음에 할 일은 무엇인가요?","options":[{"t":"구체적인 계획을 세워 실천해요","correct":true},{"t":"곧바로 잊어버려요","mis":"SO4-2-u2-X16"},{"t":"공공 기관이 해 줄 때까지 기다려요","mis":"SO4-2-u2-X16"},{"t":"방안을 처음부터 다시 찾아요","mis":"SO4-2-u2-X16"}],"explanation":["정한 것으로 끝일까요?","해 보는 걸음이 남았어요.","계획을 세워 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#2','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',1,'sa','auto','공공 기관에 해결 방안을 알리고 협조를 구하려고 쓰는 글을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"sa","stem":"공공 기관에 해결 방안을 알리고 협조를 구하려고 쓰는 글을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["제안서"],"explanation":["방안을 제안해요.","제안◯예요.","제안서예요."],"asset":{"type":"passage","lines":["제목 — 분리수거함 설치를 제안합니다","보낼 곳 — ○○시청","제안한 까닭 — 골목에 분리수거함이 없어 쓰레기와 재활용품을 그냥 버려요.","주요 제안 내용 — 골목마다 분리수거함을 놓고 분리배출 방법을 안내해 주세요."],"title":"한 모둠의 제안서"},"mis":"SO4-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#3','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',1,'ox','auto','분리배출하기는 주민이 스스로 실천할 수 있는 일이에요.',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"ox","stem":"분리배출하기는 주민이 스스로 실천할 수 있는 일이에요.","answer":"O","reason_options":[{"t":"주민 한 사람 한 사람이 집에서 바로 할 수 있는 일이기 때문에","correct":true},{"t":"공공 기관만 할 수 있는 일이기 때문에","mis":"SO4-2-u2-X17"}],"mis":"SO4-2-u2-X17","explanation":["가를 봐요.","우리가 할 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#4','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',1,'mc','auto','실천 방안 여섯 가운데 공공 기관의 협조가 필요한 일은 무엇인가요?',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"mc","stem":"실천 방안 여섯 가운데 공공 기관의 협조가 필요한 일은 무엇인가요?","options":[{"t":"라. 분리수거함 설치하기","correct":true},{"t":"가. 분리배출하기","mis":"SO4-2-u2-X17"},{"t":"나. 쓰레기 양 줄이기","mis":"SO4-2-u2-X17"},{"t":"다. 정해진 곳에 쓰레기 버리기","mis":"SO4-2-u2-X17"}],"explanation":["설치하는 일이에요.","우리가 바로 못 해요.","라예요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#5','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',2,'mc','auto','한 모둠은 공공 기관 주차장을 열어 달라는 일을 어떻게 실천했나요?',ARRAY['SO4-2-u2-X17','SO4-2-u2-X16']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"mc","stem":"한 모둠은 공공 기관 주차장을 열어 달라는 일을 어떻게 실천했나요?","options":[{"t":"시청 게시판에 열어 달라는 글을 올렸어요","correct":true},{"t":"주차장을 직접 만들었어요","mis":"SO4-2-u2-X17"},{"t":"혼자서 주차장을 썼어요","mis":"SO4-2-u2-X16"},{"t":"아무것도 하지 않았어요","mis":"SO4-2-u2-X16"}],"explanation":["실천 ㉠을 읽어요.","게시판이에요.","글을 올렸어요."],"asset":{"type":"passage","lines":["문제 — 동네에 주차 공간이 부족해 주민들이 다투었다.","실천 ㉠ 시청 게시판에 저녁 시간대에 공공 기관 주차장을 열어 달라는 글을 올렸다.","실천 ㉡ 주민들과 함께 불법 주차의 심각성을 알리는 캠페인을 벌였다.","결과 — 주차 공간이 늘어 다툼이 줄고, 불법 주차를 하는 자동차도 줄었다."],"title":"한 모둠의 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#6','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',2,'match','auto','제안서의 칸과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"match","stem":"제안서의 칸과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"제목","r":"분리수거함 설치를 제안합니다"},{"l":"보낼 곳","r":"○○시청"},{"l":"제안한 까닭","r":"분리수거함이 없어 그냥 버려요"},{"l":"주요 제안 내용","r":"골목마다 분리수거함을 놓아 주세요"}],"mis":"SO4-2-u2-X18","explanation":["제목이 맨 앞이에요.","보낼 곳은 시청이에요.","까닭과 내용을 이어요."],"asset":{"type":"passage","lines":["제목 — 분리수거함 설치를 제안합니다","보낼 곳 — ○○시청","제안한 까닭 — 골목에 분리수거함이 없어 쓰레기와 재활용품을 그냥 버려요.","주요 제안 내용 — 골목마다 분리수거함을 놓고 분리배출 방법을 안내해 주세요."],"title":"한 모둠의 제안서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#7','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',2,'ox','auto','제안서에 쓴 사람이 좋아하는 음식을 꼭 써야 해요.',ARRAY['SO4-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"ox","stem":"제안서에 쓴 사람이 좋아하는 음식을 꼭 써야 해요.","answer":"X","reason_options":[{"t":"제안서에는 지역문제와 관련 있는 제목·보낼 곳·까닭·내용을 쓰기 때문에","correct":true},{"t":"좋아하는 음식이 있어야 받는 곳이 기뻐하기 때문에","mis":"SO4-2-u2-X18"}],"mis":"SO4-2-u2-X18","explanation":["제안서 네 칸을 봐요.","음식은 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["제목 — 분리수거함 설치를 제안합니다","보낼 곳 — ○○시청","제안한 까닭 — 골목에 분리수거함이 없어 쓰레기와 재활용품을 그냥 버려요.","주요 제안 내용 — 골목마다 분리수거함을 놓고 분리배출 방법을 안내해 주세요."],"title":"한 모둠의 제안서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#8','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',2,'blank','auto','지역문제는 지역 주민과 (    )이 힘을 모아야 해결할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X19']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"blank","stem":"지역문제는 지역 주민과 (    )이 힘을 모아야 해결할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공공 기관","correct":true},{"t":"다른 지역","mis":"SO4-2-u2-X19"},{"t":"한 사람","mis":"SO4-2-u2-X19"},{"t":"관광객","mis":"SO4-2-u2-X19"}],"explanation":["우리가 할 일이 있어요.","부탁할 일도 있어요.","공공 기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#9','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',2,'mc','auto','한 모둠이 실천한 뒤에 동네가 달라진 점은 무엇인가요?',ARRAY['SO4-2-u2-X16','SO4-2-u2-X19']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"mc","stem":"한 모둠이 실천한 뒤에 동네가 달라진 점은 무엇인가요?","options":[{"t":"주차 공간이 늘어 주민들의 다툼이 줄었어요","correct":true},{"t":"주차 공간이 더 줄었어요","mis":"SO4-2-u2-X16"},{"t":"불법 주차가 더 늘었어요","mis":"SO4-2-u2-X16"},{"t":"아무것도 달라지지 않았어요","mis":"SO4-2-u2-X19"}],"explanation":["결과를 읽어요.","공간이 늘었어요.","다툼이 줄었어요."],"asset":{"type":"passage","lines":["문제 — 동네에 주차 공간이 부족해 주민들이 다투었다.","실천 ㉠ 시청 게시판에 저녁 시간대에 공공 기관 주차장을 열어 달라는 글을 올렸다.","실천 ㉡ 주민들과 함께 불법 주차의 심각성을 알리는 캠페인을 벌였다.","결과 — 주차 공간이 늘어 다툼이 줄고, 불법 주차를 하는 자동차도 줄었다."],"title":"한 모둠의 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_basic#10','soc',4,2,'u2','L05','g4_2_soc_u2_L05_basic','lesson_basic','SO4-2-u2-C5',3,'mc','auto','제안한 까닭과 주요 제안 내용을 구체적으로 써야 하는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X18']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"제안한 까닭과 주요 제안 내용을 구체적으로 써야 하는 까닭은 무엇인가요?","options":[{"t":"지역문제의 실태와 실천 방안이 분명해야 받는 곳이 무엇을 할지 알 수 있기 때문이에요","correct":true},{"t":"글을 길게 써야 하기 때문이에요","mis":"SO4-2-u2-X18"},{"t":"받는 곳을 놀라게 하려고요","mis":"SO4-2-u2-X18"},{"t":"빨리 끝내려고요","mis":"SO4-2-u2-X18"}],"explanation":["받는 곳을 생각해요.","무엇을 할지 알아야 해요.","분명하게 써요."],"asset":{"type":"passage","lines":["제목 — 분리수거함 설치를 제안합니다","보낼 곳 — ○○시청","제안한 까닭 — 골목에 분리수거함이 없어 쓰레기와 재활용품을 그냥 버려요.","주요 제안 내용 — 골목마다 분리수거함을 놓고 분리배출 방법을 안내해 주세요."],"title":"한 모둠의 제안서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#1','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',2,'mc','auto','실천 방안 여섯 가운데 주민이 스스로 할 수 있는 일은 모두 몇 가지인가요?',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"mc","stem":"실천 방안 여섯 가운데 주민이 스스로 할 수 있는 일은 모두 몇 가지인가요?","options":[{"t":"3가지","correct":true},{"t":"1가지","mis":"SO4-2-u2-X17"},{"t":"5가지","mis":"SO4-2-u2-X17"},{"t":"6가지","mis":"SO4-2-u2-X17"}],"explanation":["가·나·다를 봐요.","라·마·바는 부탁해요.","세 가지예요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#2','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',2,'ox','auto','쓰레기 무단 투기 단속하기는 주민 한 사람이 혼자 시작할 수 있는 일이에요.',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"ox","stem":"쓰레기 무단 투기 단속하기는 주민 한 사람이 혼자 시작할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"단속은 공공 기관의 협조가 필요한 일이기 때문에","correct":true},{"t":"단속은 누구나 혼자 할 수 있기 때문에","mis":"SO4-2-u2-X17"}],"mis":"SO4-2-u2-X17","explanation":["바를 봐요.","단속하는 일이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#3','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',3,'mc','auto','한 모둠의 실천 ㉠과 ㉡을 나눈 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X17','SO4-2-u2-X16']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"한 모둠의 실천 ㉠과 ㉡을 나눈 것으로 알맞은 것은 무엇인가요?","options":[{"t":"㉠은 공공 기관에 협조를 구한 일, ㉡은 주민이 함께 한 일","correct":true},{"t":"㉠과 ㉡ 모두 공공 기관만 한 일","mis":"SO4-2-u2-X19"},{"t":"㉠은 주민이 혼자 한 일, ㉡은 공공 기관이 한 일","mis":"SO4-2-u2-X17"},{"t":"㉠과 ㉡ 모두 아무도 하지 않은 일","mis":"SO4-2-u2-X16"}],"explanation":["㉠은 시청에 글이에요.","㉡은 주민과 캠페인이에요.","둘을 나눠요."],"asset":{"type":"passage","lines":["문제 — 동네에 주차 공간이 부족해 주민들이 다투었다.","실천 ㉠ 시청 게시판에 저녁 시간대에 공공 기관 주차장을 열어 달라는 글을 올렸다.","실천 ㉡ 주민들과 함께 불법 주차의 심각성을 알리는 캠페인을 벌였다.","결과 — 주차 공간이 늘어 다툼이 줄고, 불법 주차를 하는 자동차도 줄었다."],"title":"한 모둠의 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#4','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',3,'error','auto','실천 방안을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X17','SO4-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"error","stem":"실천 방안을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「분리수거함 설치는 우리끼리 오늘 바로 할 수 있어.」","correct":true,"mis_target":"SO4-2-u2-X17"},{"t":"친구 가 — 「쓰레기 양 줄이기는 우리가 할 수 있어.」","mis":"SO4-2-u2-X17"},{"t":"친구 나 — 「종량제 봉투 가격은 제안서로 부탁하자.」","mis":"SO4-2-u2-X18"}],"explanation":["설치는 누가 하나요?","공공 기관이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#5','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',3,'mc','auto','제안서 한 장으로 함께 부탁할 수 있는 일끼리 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"제안서 한 장으로 함께 부탁할 수 있는 일끼리 묶은 것은 무엇인가요?","options":[{"t":"라 · 마 · 바","correct":true},{"t":"가 · 나 · 다","mis":"SO4-2-u2-X17"},{"t":"가 · 라 · 바","mis":"SO4-2-u2-X17"},{"t":"나 · 다 · 마","mis":"SO4-2-u2-X17"}],"explanation":["부탁할 일을 찾아요.","설치·가격·단속이에요.","라·마·바예요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#6','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',3,'ox','auto','한 모둠의 동네가 달라진 것은 공공 기관 혼자의 힘 덕분이에요.',ARRAY['SO4-2-u2-X19']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"ox","stem":"한 모둠의 동네가 달라진 것은 공공 기관 혼자의 힘 덕분이에요.","answer":"X","reason_options":[{"t":"주민들이 글을 올리고 함께 캠페인을 벌인 노력이 더해졌기 때문에","correct":true},{"t":"주민은 아무것도 하지 않았기 때문에","mis":"SO4-2-u2-X19"}],"mis":"SO4-2-u2-X19","explanation":["㉠·㉡을 봐요.","주민이 움직였어요.","그래서 X예요."],"asset":{"type":"passage","lines":["문제 — 동네에 주차 공간이 부족해 주민들이 다투었다.","실천 ㉠ 시청 게시판에 저녁 시간대에 공공 기관 주차장을 열어 달라는 글을 올렸다.","실천 ㉡ 주민들과 함께 불법 주차의 심각성을 알리는 캠페인을 벌였다.","결과 — 주차 공간이 늘어 다툼이 줄고, 불법 주차를 하는 자동차도 줄었다."],"title":"한 모둠의 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#7','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',3,'mc','auto','지능형 교통 시스템 연구원이 지역문제 해결에 도움을 주는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"지능형 교통 시스템 연구원이 지역문제 해결에 도움을 주는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"교통 정보를 모아 처리하고 전달해 교통 혼잡을 줄이는 데 도움을 줘요","correct":true},{"t":"쓰레기를 직접 줍기만 해요","mis":"SO4-2-u2-X19"},{"t":"교통 표지판을 모두 떼어 내요","mis":"SO4-2-u2-X19"},{"t":"도로를 모두 없애요","mis":"SO4-2-u2-X19"}],"explanation":["교통 정보를 모아요.","차가 어디서 막히나요?","혼잡을 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#8','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',4,'mc','auto','실천 방안 여섯과 한 모둠의 제안서를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X17','SO4-2-u2-X16','SO4-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C5","difficulty":4,"kind":"mc","stem":"실천 방안 여섯과 한 모둠의 제안서를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리가 할 일은 직접 실천하고, 공공 기관에 부탁할 일은 제안서로 협조를 구해요","correct":true},{"t":"모든 일은 우리가 혼자 할 수 있어요","mis":"SO4-2-u2-X17"},{"t":"모든 일은 공공 기관에 맡기고 기다려요","mis":"SO4-2-u2-X16"},{"t":"제안서에는 아무 내용이나 써요","mis":"SO4-2-u2-X18"}],"explanation":["두 갈래로 나뉘어요.","할 일과 부탁할 일이에요.","제안서로 부탁해요."],"asset":{"type":"passage","lines":["제목 — 분리수거함 설치를 제안합니다","보낼 곳 — ○○시청","제안한 까닭 — 골목에 분리수거함이 없어 쓰레기와 재활용품을 그냥 버려요.","주요 제안 내용 — 골목마다 분리수거함을 놓고 분리배출 방법을 안내해 주세요."],"title":"한 모둠의 제안서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#9','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',4,'mc','auto','주민들의 노력으로 지역의 모습이 달라질 수 있었던 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X16']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C5","difficulty":4,"kind":"mc","stem":"주민들의 노력으로 지역의 모습이 달라질 수 있었던 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주민 모두가 관심을 갖고 공공 기관과 힘을 모아 꾸준히 노력했기 때문이에요","correct":true},{"t":"한 사람이 큰 목소리를 냈기 때문이에요","mis":"SO4-2-u2-X19"},{"t":"문제가 저절로 사라졌기 때문이에요","mis":"SO4-2-u2-X16"},{"t":"공공 기관이 혼자 다 했기 때문이에요","mis":"SO4-2-u2-X19"}],"explanation":["한 사람이었나요?","여럿이 함께했어요.","꾸준히 노력했어요."],"asset":{"type":"passage","lines":["문제 — 동네에 주차 공간이 부족해 주민들이 다투었다.","실천 ㉠ 시청 게시판에 저녁 시간대에 공공 기관 주차장을 열어 달라는 글을 올렸다.","실천 ㉡ 주민들과 함께 불법 주차의 심각성을 알리는 캠페인을 벌였다.","결과 — 주차 공간이 늘어 다툼이 줄고, 불법 주차를 하는 자동차도 줄었다."],"title":"한 모둠의 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L05_challenge#10','soc',4,2,'u2','L05','g4_2_soc_u2_L05_challenge','lesson_challenge','SO4-2-u2-C5',4,'essay','teacher','우리 동네 쓰레기 문제를 풀려고 해요. 우리가 할 수 있는 일 하나와 공공 기관에 부탁할 일 하나를 쓰고, 부탁할 일을 어떻게 알릴지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C5","difficulty":4,"kind":"essay","stem":"우리 동네 쓰레기 문제를 풀려고 해요. 우리가 할 수 있는 일 하나와 공공 기관에 부탁할 일 하나를 쓰고, 부탁할 일을 어떻게 알릴지 쓰세요.","answer_guide":{"answer":"예: 우리는 집에서 쓰레기를 분리배출하고 쓰레기 양을 줄일 거예요. 골목에 분리수거함을 설치하는 일은 공공 기관에 부탁해야 하니, 제목·보낼 곳·제안한 까닭·주요 제안 내용을 구체적으로 쓴 제안서를 시청에 보낼 거예요.","scoring_points":["우리가 할 일을 썼는가","공공 기관에 부탁할 일을 썼는가","제안서 등 알리는 방법을 썼는가"]},"explanation":["우리 일을 써요.","부탁할 일을 써요.","알리는 방법을 써요."],"asset":{"type":"passage","lines":["가. 분리배출하기","나. 쓰레기 양 줄이기","다. 정해진 곳에 쓰레기 버리기","라. 분리수거함 설치하기","마. 쓰레기 종량제 봉투 가격 올리기","바. 쓰레기 무단 투기 단속하기"],"title":"쓰레기 문제의 실천 방안 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#1','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',1,'mc','auto','지역문제를 해결하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C6","difficulty":1,"kind":"mc","stem":"지역문제를 해결하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"문제 확인하기 → 원인 찾기 → 해결 방안 정하기","correct":true},{"t":"해결 방안 정하기 → 원인 찾기 → 문제 확인하기","mis":"SO4-2-u2-X20"},{"t":"원인 찾기 → 문제 확인하기 → 해결 방안 정하기","mis":"SO4-2-u2-X20"},{"t":"해결 방안 정하기 → 문제 확인하기 → 원인 찾기","mis":"SO4-2-u2-X20"}],"explanation":["문제부터 알아요.","다음은 원인이에요.","그다음 방안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#2','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',1,'sa','auto','확인 놀이 다섯 문장 가운데 알맞지 않은 문장은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C6","difficulty":1,"kind":"sa","stem":"확인 놀이 다섯 문장 가운데 알맞지 않은 문장은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["④를 봐요.","⑤도 봐요.","두 개예요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"},"mis":"SO4-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#3','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',1,'ox','auto','확인 놀이 ②는 알맞은 문장이에요.',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C6","difficulty":1,"kind":"ox","stem":"확인 놀이 ②는 알맞은 문장이에요.","answer":"O","reason_options":[{"t":"지역문제는 주민의 삶을 불편하게 하거나 갈등을 일으키기 때문에","correct":true},{"t":"지역문제는 주민에게 아무 영향이 없기 때문에","mis":"SO4-2-u2-X20"}],"mis":"SO4-2-u2-X20","explanation":["②를 읽어요.","지역문제의 뜻이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#4','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',1,'mc','auto','확인 놀이 ④를 알맞게 고친 것은 무엇인가요?',ARRAY['SO4-2-u2-X20','SO4-2-u2-X16']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C6","difficulty":1,"kind":"mc","stem":"확인 놀이 ④를 알맞게 고친 것은 무엇인가요?","options":[{"t":"원인을 알아본 후에 해결 방안을 정해요","correct":true},{"t":"해결 방안을 정한 후에도 원인은 알아보지 않아요","mis":"SO4-2-u2-X20"},{"t":"원인과 해결 방안은 관계없어요","mis":"SO4-2-u2-X20"},{"t":"해결 방안은 정하지 않아요","mis":"SO4-2-u2-X16"}],"explanation":["차례가 바뀌었어요.","원인이 먼저예요.","그다음 방안이에요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#5','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',2,'mc','auto','차례가 섞인 다섯 걸음을 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"mc","stem":"차례가 섞인 다섯 걸음을 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"나 → 마 → 라 → 가 → 다","correct":true},{"t":"가 → 나 → 다 → 라 → 마","mis":"SO4-2-u2-X20"},{"t":"나 → 가 → 라 → 마 → 다","mis":"SO4-2-u2-X20"},{"t":"마 → 나 → 가 → 라 → 다","mis":"SO4-2-u2-X20"}],"explanation":["뜻과 종류가 먼저예요.","우리 지역 문제, 원인이에요.","방안, 실천이에요."],"asset":{"type":"passage","lines":["가. 토의로 해결 방안 찾기","나. 지역문제의 의미와 종류 알아보기","다. 해결 방안 실천하기","라. 자료를 분석해 원인 알아보기","마. 우리 지역에 어떤 문제가 있는지 알아보기"],"title":"차례가 섞인 다섯 걸음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#6','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',2,'match','auto','주제①의 걸음과 그 걸음에서 한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"match","stem":"주제①의 걸음과 그 걸음에서 한 일을 알맞게 이으세요.","pairs":[{"l":"문제 확인하기","r":"둘러보기·면담으로 우리 지역의 문제 알아보기"},{"l":"원인 찾기","r":"자료를 모아 분석하기"},{"l":"해결 방안 정하기","r":"기준으로 재고 토의하기"},{"l":"실천하기","r":"캠페인·제안서"}],"mis":"SO4-2-u2-X20","explanation":["확인은 둘러보기예요.","원인은 자료예요.","방안과 실천도 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#7','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',2,'ox','auto','확인 놀이 ⑤는 알맞은 문장이에요.',ARRAY['SO4-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"ox","stem":"확인 놀이 ⑤는 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"해결 방안은 주민과 공공 기관이 함께 실천하기 때문에","correct":true},{"t":"공공 기관만 지역의 일을 할 수 있기 때문에","mis":"SO4-2-u2-X19"}],"mis":"SO4-2-u2-X19","explanation":["⑤를 읽어요.","주민 몫도 있었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#8','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',2,'blank','auto','공익 광고 영상을 기획할 때는 장면 순서, 장면, 장면 설명·대사·(    ), 배경음·효과음을 함께 적어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X21']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"blank","stem":"공익 광고 영상을 기획할 때는 장면 순서, 장면, 장면 설명·대사·(    ), 배경음·효과음을 함께 적어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"자막","correct":true},{"t":"가격","mis":"SO4-2-u2-X21"},{"t":"날씨","mis":"SO4-2-u2-X21"},{"t":"주소","mis":"SO4-2-u2-X21"}],"explanation":["화면에 글이 나와요.","자◯이에요.","자막이에요."],"asset":{"type":"passage","lines":["해결하고 싶은 지역문제 — 길거리에 버린 쓰레기","장면 1 — 쓰레기가 쌓인 골목을 보며 찡그리는 주민","장면 2 — 친구들이 쓰레기를 주워 분리배출하는 모습","장면 3 — 깨끗해진 골목에서 웃는 주민들","자막 — 「우리 골목은 우리가 지켜요」 · 배경음 — 밝은 음악"],"title":"공익 광고 영상 기획(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#9','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',2,'mc','auto','공익 광고 영상 기획(예시)이 알리려는 해결 방안은 무엇인가요?',ARRAY['SO4-2-u2-X21','SO4-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"mc","stem":"공익 광고 영상 기획(예시)이 알리려는 해결 방안은 무엇인가요?","options":[{"t":"쓰레기를 주워 분리배출해 골목을 깨끗이 지켜요","correct":true},{"t":"골목에 쓰레기를 더 모아요","mis":"SO4-2-u2-X21"},{"t":"골목을 막아 아무도 못 다니게 해요","mis":"SO4-2-u2-X21"},{"t":"다른 동네에 쓰레기를 보내요","mis":"SO4-2-u2-X02"}],"explanation":["장면 2를 봐요.","줍고 분리배출해요.","골목을 지켜요."],"asset":{"type":"passage","lines":["해결하고 싶은 지역문제 — 길거리에 버린 쓰레기","장면 1 — 쓰레기가 쌓인 골목을 보며 찡그리는 주민","장면 2 — 친구들이 쓰레기를 주워 분리배출하는 모습","장면 3 — 깨끗해진 골목에서 웃는 주민들","자막 — 「우리 골목은 우리가 지켜요」 · 배경음 — 밝은 음악"],"title":"공익 광고 영상 기획(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_basic#10','soc',4,2,'u2','L06','g4_2_soc_u2_L06_basic','lesson_basic','SO4-2-u2-C6',3,'mc','auto','모두가 행복한 공원을 꾸밀 때 가장 중요하게 생각할 것은 무엇인가요?',ARRAY['SO4-2-u2-X21']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"모두가 행복한 공원을 꾸밀 때 가장 중요하게 생각할 것은 무엇인가요?","options":[{"t":"공원에 담은 가치","correct":true},{"t":"그림을 가장 잘 그리는 솜씨","mis":"SO4-2-u2-X21"},{"t":"공원을 가장 크게 그리는 것","mis":"SO4-2-u2-X21"},{"t":"색을 가장 많이 쓰는 것","mis":"SO4-2-u2-X21"}],"explanation":["㉠~㉢을 읽어요.","누구를 위한 공간인가요?","담은 가치예요."],"asset":{"type":"passage","lines":["㉠ 친구들과 마음껏 뛰어놀 수 있는 공간","㉡ 장애가 있는 친구들도 안전하게 이용할 수 있는 공간","㉢ 자연을 느끼며 편안하게 쉴 수 있는 공간"],"title":"모두가 행복한 공원에 담고 싶은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#1','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',2,'mc','auto','확인 놀이 다섯 문장 가운데 알맞은 문장끼리 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20','SO4-2-u2-X19']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"mc","stem":"확인 놀이 다섯 문장 가운데 알맞은 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"① · ② · ③","correct":true},{"t":"① · ④ · ⑤","mis":"SO4-2-u2-X20"},{"t":"③ · ④ · ⑤","mis":"SO4-2-u2-X19"},{"t":"② · ④","mis":"SO4-2-u2-X20"}],"explanation":["④는 차례가 바뀌었어요.","⑤는 공공 기관만이에요.","①·②·③이에요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#2','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',2,'ox','auto','차례가 섞인 다섯 걸음에서 라는 가보다 먼저 해요.',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C6","difficulty":2,"kind":"ox","stem":"차례가 섞인 다섯 걸음에서 라는 가보다 먼저 해요.","answer":"O","reason_options":[{"t":"원인을 알아본 뒤에 해결 방안을 찾기 때문에","correct":true},{"t":"해결 방안을 찾은 뒤에 원인을 알아보기 때문에","mis":"SO4-2-u2-X20"}],"mis":"SO4-2-u2-X20","explanation":["라는 원인이에요.","가는 방안이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["가. 토의로 해결 방안 찾기","나. 지역문제의 의미와 종류 알아보기","다. 해결 방안 실천하기","라. 자료를 분석해 원인 알아보기","마. 우리 지역에 어떤 문제가 있는지 알아보기"],"title":"차례가 섞인 다섯 걸음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#3','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',3,'mc','auto','확인 놀이 ⑤를 알맞게 고친 것은 무엇인가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X16','SO4-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"확인 놀이 ⑤를 알맞게 고친 것은 무엇인가요?","options":[{"t":"해결 방안은 주민과 공공 기관이 함께 실천해요","correct":true},{"t":"해결 방안은 주민 한 사람만 실천해요","mis":"SO4-2-u2-X19"},{"t":"해결 방안은 실천하지 않아도 돼요","mis":"SO4-2-u2-X16"},{"t":"해결 방안은 다른 지역이 실천해요","mis":"SO4-2-u2-X02"}],"explanation":["공공 기관만일까요?","주민 몫도 있어요.","함께 실천해요."],"asset":{"type":"passage","lines":["① 지역에는 환경 오염, 주차 문제, 교통 혼잡 등 다양한 지역문제가 있어요.","② 지역문제는 주민의 삶을 불편하게 하거나 주민 사이에 갈등을 일으켜요.","③ 해결 방안을 정할 때는 대화와 타협으로 의견을 조정해요.","④ 해결 방안을 정한 후에 원인을 알아봐요.","⑤ 해결 방안은 공공 기관에서만 실천할 수 있어요."],"title":"확인 놀이 다섯 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#4','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',3,'error','auto','주제①을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X20','SO4-2-u2-X09','SO4-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"error","stem":"주제①을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「해결 방안을 먼저 정하고 원인은 나중에 찾아.」","correct":true,"mis_target":"SO4-2-u2-X20"},{"t":"친구 나 — 「원인은 자료를 모아 분석해서 찾아.」","mis":"SO4-2-u2-X09"},{"t":"친구 다 — 「방안이 여럿이면 대화와 타협으로 조정해.」","mis":"SO4-2-u2-X15"}],"explanation":["차례를 떠올려요.","원인이 먼저예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#5','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',3,'mc','auto','공익 광고 영상 기획(예시)에서 장면 1과 장면 3을 견주면 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u2-X21']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"공익 광고 영상 기획(예시)에서 장면 1과 장면 3을 견주면 알 수 있는 것은 무엇인가요?","options":[{"t":"해결 방안을 실천하기 전과 후에 지역이 어떻게 달라지는지","correct":true},{"t":"광고에 나오는 사람의 수","mis":"SO4-2-u2-X21"},{"t":"배경음의 크기","mis":"SO4-2-u2-X21"},{"t":"골목의 길이","mis":"SO4-2-u2-X21"}],"explanation":["1은 쌓인 쓰레기예요.","3은 깨끗해요.","전과 후예요."],"asset":{"type":"passage","lines":["해결하고 싶은 지역문제 — 길거리에 버린 쓰레기","장면 1 — 쓰레기가 쌓인 골목을 보며 찡그리는 주민","장면 2 — 친구들이 쓰레기를 주워 분리배출하는 모습","장면 3 — 깨끗해진 골목에서 웃는 주민들","자막 — 「우리 골목은 우리가 지켜요」 · 배경음 — 밝은 음악"],"title":"공익 광고 영상 기획(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#6','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',3,'ox','auto','공원을 꾸밀 때 ㉡처럼 장애가 있는 친구도 안전하게 쓰는 공간을 담는 것은 모두를 생각한 거예요.',ARRAY['SO4-2-u2-X21']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"ox","stem":"공원을 꾸밀 때 ㉡처럼 장애가 있는 친구도 안전하게 쓰는 공간을 담는 것은 모두를 생각한 거예요.","answer":"O","reason_options":[{"t":"지역에 사는 여러 사람이 함께 행복하게 이용할 수 있기 때문에","correct":true},{"t":"공원은 한 사람만 쓰는 곳이기 때문에","mis":"SO4-2-u2-X21"}],"mis":"SO4-2-u2-X21","explanation":["㉡을 읽어요.","모두가 이용해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 친구들과 마음껏 뛰어놀 수 있는 공간","㉡ 장애가 있는 친구들도 안전하게 이용할 수 있는 공간","㉢ 자연을 느끼며 편안하게 쉴 수 있는 공간"],"title":"모두가 행복한 공원에 담고 싶은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#7','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',3,'mc','auto','지역문제를 해결할 때 대화와 타협으로 의견을 조정하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X15']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"지역문제를 해결할 때 대화와 타협으로 의견을 조정하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 주민의 생각을 담아 모두가 받아들일 수 있는 방안을 정하려고","correct":true},{"t":"목소리 큰 사람의 뜻대로 정하려고","mis":"SO4-2-u2-X15"},{"t":"의견이 갈리면 미뤄 두려고","mis":"SO4-2-u2-X15"},{"t":"가장 먼저 말한 의견으로 정하려고","mis":"SO4-2-u2-X15"}],"explanation":["의견이 여럿이에요.","서로 맞춰요.","모두가 받아들여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#8','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',4,'mc','auto','확인 놀이 다섯 문장과 차례가 섞인 다섯 걸음을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20','SO4-2-u2-X19','SO4-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C6","difficulty":4,"kind":"mc","stem":"확인 놀이 다섯 문장과 차례가 섞인 다섯 걸음을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문제를 확인하고 원인을 찾아 방안을 정한 뒤 주민과 공공 기관이 함께 실천해요","correct":true},{"t":"방안을 정한 뒤에 원인을 찾아요","mis":"SO4-2-u2-X20"},{"t":"공공 기관만 실천하면 돼요","mis":"SO4-2-u2-X19"},{"t":"문제는 확인하지 않아도 돼요","mis":"SO4-2-u2-X05"}],"explanation":["차례를 봐요.","실천도 봐요.","함께 실천해요."],"asset":{"type":"passage","lines":["가. 토의로 해결 방안 찾기","나. 지역문제의 의미와 종류 알아보기","다. 해결 방안 실천하기","라. 자료를 분석해 원인 알아보기","마. 우리 지역에 어떤 문제가 있는지 알아보기"],"title":"차례가 섞인 다섯 걸음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#9','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',4,'mc','auto','「지역문제의 해결」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X16','SO4-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C6","difficulty":4,"kind":"mc","stem":"「지역문제의 해결」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"지역 주민 모두가 관심을 갖고 꾸준히 노력해야 지역문제를 해결할 수 있어요","correct":true},{"t":"한 사람이 아주 열심히 하면 해결돼요","mis":"SO4-2-u2-X19"},{"t":"공공 기관이 알아서 해 줄 때까지 기다려요","mis":"SO4-2-u2-X16"},{"t":"시간이 지나면 저절로 사라져요","mis":"SO4-2-u2-X04"}],"explanation":["누가 함께했나요?","주민 모두예요.","꾸준히 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L06_challenge#10','soc',4,2,'u2','L06','g4_2_soc_u2_L06_challenge','lesson_challenge','SO4-2-u2-C6',4,'essay','teacher','공익 광고 영상 기획(예시)처럼 우리 동네의 지역문제 하나를 골라 장면 세 개와 자막 하나를 기획하세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C6","difficulty":4,"kind":"essay","stem":"공익 광고 영상 기획(예시)처럼 우리 동네의 지역문제 하나를 골라 장면 세 개와 자막 하나를 기획하세요.","answer_guide":{"answer":"예: 학교 앞 통학로에서 차가 빠르게 달리는 문제를 골랐어요. 장면 1은 빠른 차를 피해 깜짝 놀라는 학생, 장면 2는 주민들이 안전 캠페인을 벌이고 시청에 제안서를 보내는 모습, 장면 3은 천천히 달리는 차 옆을 안전하게 걷는 학생이에요. 자막은 「천천히, 우리 아이들이 다녀요」예요.","scoring_points":["지역문제를 골랐는가","장면 셋에 해결 방안이 담겼는가","자막을 썼는가"]},"explanation":["문제를 골라요.","장면을 나눠요.","자막을 써요."],"asset":{"type":"passage","lines":["해결하고 싶은 지역문제 — 길거리에 버린 쓰레기","장면 1 — 쓰레기가 쌓인 골목을 보며 찡그리는 주민","장면 2 — 친구들이 쓰레기를 주워 분리배출하는 모습","장면 3 — 깨끗해진 골목에서 웃는 주민들","자막 — 「우리 골목은 우리가 지켜요」 · 배경음 — 밝은 음악"],"title":"공익 광고 영상 기획(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#1','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',1,'mc','auto','지역의 자랑거리와 관련 있는 것으로 알맞게 묶인 것은 무엇인가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"mc","stem":"지역의 자랑거리와 관련 있는 것으로 알맞게 묶인 것은 무엇인가요?","options":[{"t":"자연환경, 역사, 문화, 생산물","correct":true},{"t":"날씨, 인구, 나이, 키","mis":"SO4-2-u2-X22"},{"t":"이름, 번호, 색깔, 크기","mis":"SO4-2-u2-X22"},{"t":"값, 무게, 길이, 넓이","mis":"SO4-2-u2-X22"}],"explanation":["네 갈래예요.","산과 강, 옛 자취가 있어요.","자연환경·역사·문화·생산물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#2','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',1,'sa','auto','옛날 백성이 나라나 자기 고장을 지키려고 스스로 만든 군대를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"sa","stem":"옛날 백성이 나라나 자기 고장을 지키려고 스스로 만든 군대를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["의병"],"explanation":["나라가 만든 군대가 아니에요.","의◯이에요.","의병이에요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"},"mis":"SO4-2-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#3','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',1,'ox','auto','지역의 자랑거리를 살펴보면 그 지역의 독특한 점이나 특징을 알 수 있어요.',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"ox","stem":"지역의 자랑거리를 살펴보면 그 지역의 독특한 점이나 특징을 알 수 있어요.","answer":"O","reason_options":[{"t":"자랑거리에 그 지역이 어떤 곳인지가 담겨 있기 때문에","correct":true},{"t":"자랑거리로는 이름만 알 수 있기 때문에","mis":"SO4-2-u2-X23"}],"mis":"SO4-2-u2-X23","explanation":["자랑거리를 살펴봐요.","어떤 곳인지 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#4','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',1,'mc','auto','○○군의 자랑거리 ②는 어느 갈래에 들어가나요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"mc","stem":"○○군의 자랑거리 ②는 어느 갈래에 들어가나요?","options":[{"t":"자연환경","correct":true},{"t":"역사","mis":"SO4-2-u2-X22"},{"t":"문화","mis":"SO4-2-u2-X22"},{"t":"생산물","mis":"SO4-2-u2-X22"}],"explanation":["높은 산이에요.","동식물이 많아요.","자연환경이에요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#5','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',2,'mc','auto','○○군의 자랑거리 가운데 생산물과 관련 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"mc","stem":"○○군의 자랑거리 가운데 생산물과 관련 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"⑦ · ⑧","correct":true},{"t":"① · ②","mis":"SO4-2-u2-X22"},{"t":"③ · ④","mis":"SO4-2-u2-X22"},{"t":"⑤ · ⑥","mis":"SO4-2-u2-X22"}],"explanation":["그곳에서 나는 것이에요.","대나무 물건과 김이에요.","⑦·⑧이에요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#6','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',2,'match','auto','자랑거리와 그 자랑거리가 알려 주는 ○○군의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"match","stem":"자랑거리와 그 자랑거리가 알려 주는 ○○군의 모습을 알맞게 이으세요.","pairs":[{"l":"① 큰 강","r":"㉠ 큰 강이 흐르는 곳"},{"l":"④ 고인돌 유적","r":"㉡ 아주 오래전부터 사람이 살던 곳"},{"l":"⑤ 도자기 축제","r":"㉢ 옛 솜씨를 이어 오는 곳"},{"l":"⑧ 김","r":"㉣ 바다에서 길러 거두는 곳"}],"mis":"SO4-2-u2-X23","explanation":["강은 강이에요.","고인돌은 오래전이에요.","축제와 김도 이어요."],"asset":{"type":"passage","lines":["㉠ 큰 강이 흐르는 곳이에요.","㉡ 아주 오래전부터 사람이 살던 곳이에요.","㉢ 옛 솜씨를 오늘까지 이어 오는 곳이에요.","㉣ 바다에서 길러 거두는 곳이에요."],"title":"자랑거리가 알려 주는 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#7','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',2,'ox','auto','자랑거리를 조사할 때 옆 지역의 자랑거리를 그대로 옮겨 적어도 돼요.',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"ox","stem":"자랑거리를 조사할 때 옆 지역의 자랑거리를 그대로 옮겨 적어도 돼요.","answer":"X","reason_options":[{"t":"옮겨 적으면 우리 지역의 특징을 알 수 없기 때문에","correct":true},{"t":"어느 지역이나 자랑거리가 같기 때문에","mis":"SO4-2-u2-X24"}],"mis":"SO4-2-u2-X24","explanation":["누구의 자랑거리인가요?","우리 지역이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 시·도청이나 지역 문화원 누리집에서 검색해요.","㉯ 부모님이나 지역에 오래 사신 어른께 여쭈어봐요.","㉰ 지역 안내 자료나 안내 책자를 찾아봐요."],"title":"자랑거리를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#8','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',2,'blank','auto','지역에서 관광 안내 자료를 무료로 주는 까닭은 그 지역과 자랑거리를 널리 (    ) 위해서예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"blank","stem":"지역에서 관광 안내 자료를 무료로 주는 까닭은 그 지역과 자랑거리를 널리 (    ) 위해서예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"알리기","correct":true},{"t":"감추기","mis":"SO4-2-u2-X23"},{"t":"줄이기","mis":"SO4-2-u2-X23"},{"t":"팔기","mis":"SO4-2-u2-X23"}],"explanation":["누구나 받아요.","많이 알게 돼요.","알리기예요."],"asset":{"type":"passage","lines":["어느 지역에서 집으로 관광 안내 자료를 보내 주었다.","자료에는 그 지역의 산과 바다, 옛 유적, 축제, 특산물이 실려 있었다.","자료는 누구나 무료로 받을 수 있다."],"title":"우편으로 온 안내 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#9','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',2,'mc','auto','자랑거리를 조사하는 방법 ㉯로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"mc","stem":"자랑거리를 조사하는 방법 ㉯로 알맞은 것은 무엇인가요?","options":[{"t":"할머니께 우리 고장에 전해 오는 이야기를 여쭈어봐요","correct":true},{"t":"옆 지역 누리집 글을 옮겨 적어요","mis":"SO4-2-u2-X24"},{"t":"아무에게도 묻지 않아요","mis":"SO4-2-u2-X24"},{"t":"상상해서 적어요","mis":"SO4-2-u2-X24"}],"explanation":["㉯를 읽어요.","어른께 여쭈어요.","할머니께 여쭈어요."],"asset":{"type":"passage","lines":["㉮ 시·도청이나 지역 문화원 누리집에서 검색해요.","㉯ 부모님이나 지역에 오래 사신 어른께 여쭈어봐요.","㉰ 지역 안내 자료나 안내 책자를 찾아봐요."],"title":"자랑거리를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_basic#10','soc',4,2,'u2','L07','g4_2_soc_u2_L07_basic','lesson_basic','SO4-2-u2-C7',3,'mc','auto','자랑거리가 알려 주는 ○○군 ㉠~㉣을 모두 읽고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"mc","stem":"자랑거리가 알려 주는 ○○군 ㉠~㉣을 모두 읽고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"○○군은 강과 바다가 있고, 오래전부터 사람이 살며 옛 솜씨를 이어 온 곳이에요","correct":true},{"t":"○○군은 사람이 산 지 얼마 안 된 곳이에요","mis":"SO4-2-u2-X23"},{"t":"○○군에는 바다가 없어요","mis":"SO4-2-u2-X23"},{"t":"○○군은 자랑거리의 이름만 많은 곳이에요","mis":"SO4-2-u2-X23"}],"explanation":["㉠은 강이에요.","㉡·㉢은 오래된 삶이에요.","㉣은 바다예요."],"asset":{"type":"passage","lines":["㉠ 큰 강이 흐르는 곳이에요.","㉡ 아주 오래전부터 사람이 살던 곳이에요.","㉢ 옛 솜씨를 오늘까지 이어 오는 곳이에요.","㉣ 바다에서 길러 거두는 곳이에요."],"title":"자랑거리가 알려 주는 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#1','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',2,'mc','auto','○○군의 자랑거리 여덟을 네 갈래로 나누면 한 갈래에 몇 개씩 들어가나요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"mc","stem":"○○군의 자랑거리 여덟을 네 갈래로 나누면 한 갈래에 몇 개씩 들어가나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"SO4-2-u2-X22"},{"t":"3개","mis":"SO4-2-u2-X22"},{"t":"4개","mis":"SO4-2-u2-X22"}],"explanation":["①②는 자연환경이에요.","③④는 역사예요.","두 개씩이에요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#2','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',2,'ox','auto','○○군의 자랑거리 ⑥ 정원 박람회는 문화와 관련 있는 자랑거리예요.',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"ox","stem":"○○군의 자랑거리 ⑥ 정원 박람회는 문화와 관련 있는 자랑거리예요.","answer":"O","reason_options":[{"t":"사람들이 모여 즐기고 보여 주는 행사이기 때문에","correct":true},{"t":"산과 강처럼 자연이 만든 것이기 때문에","mis":"SO4-2-u2-X22"}],"mis":"SO4-2-u2-X22","explanation":["⑥을 읽어요.","박람회는 행사예요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#3','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',3,'mc','auto','자랑거리를 살펴보는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"mc","stem":"자랑거리를 살펴보는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 지역이 어떤 곳인지, 독특한 점과 특징을 알려고","correct":true},{"t":"자랑거리의 이름을 많이 외우려고","mis":"SO4-2-u2-X23"},{"t":"그 지역의 내일 날씨를 알려고","mis":"SO4-2-u2-X23"},{"t":"그 지역에 사는 사람 수를 알려고","mis":"SO4-2-u2-X23"}],"explanation":["이름을 외울까요?","어떤 곳인지 알아요.","특징을 알려고요."],"asset":{"type":"passage","lines":["㉠ 큰 강이 흐르는 곳이에요.","㉡ 아주 오래전부터 사람이 살던 곳이에요.","㉢ 옛 솜씨를 오늘까지 이어 오는 곳이에요.","㉣ 바다에서 길러 거두는 곳이에요."],"title":"자랑거리가 알려 주는 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#4','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',3,'error','auto','자랑거리를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"error","stem":"자랑거리를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「③ 의병을 이끈 사람은 생산물 갈래야.」","correct":true,"mis_target":"SO4-2-u2-X22"},{"t":"친구 가 — 「① 큰 강은 자연환경 갈래야.」","mis":"SO4-2-u2-X22"},{"t":"친구 나 — 「④ 고인돌 유적은 역사 갈래야.」","mis":"SO4-2-u2-X22"}],"explanation":["③은 옛사람이에요.","고장을 지켰어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#5','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',3,'mc','auto','「주차 공간 부족」을 ○○군의 자랑거리로 쓸 수 없는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X22','SO4-2-u2-X23']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"mc","stem":"「주차 공간 부족」을 ○○군의 자랑거리로 쓸 수 없는 까닭은 무엇인가요?","options":[{"t":"주민의 생활을 불편하게 하는 지역문제이기 때문이에요","correct":true},{"t":"너무 오래된 것이기 때문이에요","mis":"SO4-2-u2-X22"},{"t":"바다에서 나는 것이기 때문이에요","mis":"SO4-2-u2-X22"},{"t":"사람들이 모르기 때문이에요","mis":"SO4-2-u2-X23"}],"explanation":["자랑거리일까요?","불편을 줘요.","지역문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#6','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',3,'ox','auto','우편으로 온 안내 자료를 보면 그 지역이 어떤 곳인지 짐작할 수 있어요.',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"ox","stem":"우편으로 온 안내 자료를 보면 그 지역이 어떤 곳인지 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"산과 바다, 유적, 축제, 특산물 같은 자랑거리가 실려 있기 때문에","correct":true},{"t":"안내 자료에는 지역에 대한 내용이 없기 때문에","mis":"SO4-2-u2-X23"}],"mis":"SO4-2-u2-X23","explanation":["무엇이 실려 있나요?","자랑거리예요.","그래서 O예요."],"asset":{"type":"passage","lines":["어느 지역에서 집으로 관광 안내 자료를 보내 주었다.","자료에는 그 지역의 산과 바다, 옛 유적, 축제, 특산물이 실려 있었다.","자료는 누구나 무료로 받을 수 있다."],"title":"우편으로 온 안내 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#7','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',3,'mc','auto','우리 고장에 전해 오는 옛이야기를 조사할 때 ㉮~㉰ 가운데 함께 쓰면 좋은 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C7","difficulty":3,"kind":"mc","stem":"우리 고장에 전해 오는 옛이야기를 조사할 때 ㉮~㉰ 가운데 함께 쓰면 좋은 것은 무엇인가요?","options":[{"t":"㉮ 누리집 검색과 ㉯ 오래 사신 어른께 여쭈어보기","correct":true},{"t":"㉮만 쓰고 나머지는 쓰지 않기","mis":"SO4-2-u2-X24"},{"t":"어느 방법도 쓰지 않기","mis":"SO4-2-u2-X24"},{"t":"옆 지역 자료만 보기","mis":"SO4-2-u2-X24"}],"explanation":["옛이야기예요.","기록과 기억이 있어요.","둘을 함께 써요."],"asset":{"type":"passage","lines":["㉮ 시·도청이나 지역 문화원 누리집에서 검색해요.","㉯ 부모님이나 지역에 오래 사신 어른께 여쭈어봐요.","㉰ 지역 안내 자료나 안내 책자를 찾아봐요."],"title":"자랑거리를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#8','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',4,'mc','auto','○○군의 자랑거리 여덟과 ㉠~㉣을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X22','SO4-2-u2-X23','SO4-2-u2-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C7","difficulty":4,"kind":"mc","stem":"○○군의 자랑거리 여덟과 ㉠~㉣을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자랑거리는 네 갈래로 나눌 수 있고, 살펴보면 그 지역의 특징이 드러나요","correct":true},{"t":"자랑거리는 한 갈래뿐이에요","mis":"SO4-2-u2-X22"},{"t":"자랑거리는 이름만 알면 돼요","mis":"SO4-2-u2-X23"},{"t":"자랑거리는 다른 지역과 똑같아요","mis":"SO4-2-u2-X24"}],"explanation":["갈래를 나눠요.","줄을 읽어요.","특징이 보여요."],"asset":{"type":"passage","lines":["㉠ 큰 강이 흐르는 곳이에요.","㉡ 아주 오래전부터 사람이 살던 곳이에요.","㉢ 옛 솜씨를 오늘까지 이어 오는 곳이에요.","㉣ 바다에서 길러 거두는 곳이에요."],"title":"자랑거리가 알려 주는 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#9','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',4,'mc','auto','지역의 퍼레이드 연기자가 하는 일과 지역 축제를 함께 생각할 때 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X25','SO4-2-u2-X22']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C7","difficulty":4,"kind":"mc","stem":"지역의 퍼레이드 연기자가 하는 일과 지역 축제를 함께 생각할 때 알맞은 것은 무엇인가요?","options":[{"t":"축제 공연으로 관람객을 즐겁게 하며 지역의 자랑거리를 알리는 데 힘을 보태요","correct":true},{"t":"축제를 열지 못하게 막아요","mis":"SO4-2-u2-X25"},{"t":"지역의 자랑거리를 감춰요","mis":"SO4-2-u2-X25"},{"t":"축제와 아무 관계가 없어요","mis":"SO4-2-u2-X22"}],"explanation":["공연을 해요.","축제에서요.","알리는 데 보태요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L07_challenge#10','soc',4,2,'u2','L07','g4_2_soc_u2_L07_challenge','lesson_challenge','SO4-2-u2-C7',4,'essay','teacher','우리 지역의 자랑거리 하나를 골라 네 갈래 가운데 어디에 들어가는지 쓰고, 그 자랑거리로 우리 지역이 어떤 곳인지 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C7","difficulty":4,"kind":"essay","stem":"우리 지역의 자랑거리 하나를 골라 네 갈래 가운데 어디에 들어가는지 쓰고, 그 자랑거리로 우리 지역이 어떤 곳인지 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리 지역의 오래된 성곽을 골랐어요. 역사 갈래에 들어가요. 이 성곽을 보면 우리 지역은 옛날부터 사람들이 모여 살며 고장을 지켜 온 곳이라는 것을 알 수 있어요.","scoring_points":["자랑거리를 하나 골랐는가","갈래를 바르게 썼는가","지역이 어떤 곳인지 썼는가"]},"explanation":["하나를 골라요.","갈래를 정해요.","어떤 곳인지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#1','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',1,'mc','auto','지역 사람들이 지역의 자랑거리를 알리려고 노력하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X25']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"mc","stem":"지역 사람들이 지역의 자랑거리를 알리려고 노력하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"지역을 알리고 지역을 발전시킬 수 있기 때문이에요","correct":true},{"t":"지역에 사는 사람의 수를 줄이려고요","mis":"SO4-2-u2-X25"},{"t":"자랑거리를 다른 지역에 넘겨주려고요","mis":"SO4-2-u2-X25"},{"t":"지역에 오는 사람을 막으려고요","mis":"SO4-2-u2-X25"}],"explanation":["알리면 사람이 와요.","지역이 알려져요.","발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#2','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',1,'sa','auto','생산자와 소비자가 중간 단계 없이 바로 사고파는 곳은 「○○○ 장터」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"sa","stem":"생산자와 소비자가 중간 단계 없이 바로 사고파는 곳은 「○○○ 장터」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["직거래"],"explanation":["바로 사고팔아요.","직◯◯예요.","직거래예요."],"asset":{"type":"passage","lines":["㉠ 축제를 열어요.","㉡ 자연환경을 이용한 관광 상품으로 개발해요.","㉢ 전시회를 열어요.","㉣ 체험 프로그램을 운영해요.","㉤ 민속놀이와 체육 행사를 함께 열어요.","㉥ 박람회를 열어요.","㉦ 직거래 장터를 열어요."],"title":"자랑거리를 알리는 방법 일곱"},"mis":"SO4-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#3','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',1,'ox','auto','관광객이 많이 찾아오면 지역 경제에도 도움이 돼요.',ARRAY['SO4-2-u2-X25']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"ox","stem":"관광객이 많이 찾아오면 지역 경제에도 도움이 돼요.","answer":"O","reason_options":[{"t":"관광객이 지역에서 먹고 자고 물건을 사기 때문에","correct":true},{"t":"관광객은 지역과 관계없기 때문에","mis":"SO4-2-u2-X25"}],"mis":"SO4-2-u2-X25","explanation":["관광객이 와요.","지역에서 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#4','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',1,'mc','auto','여러 지역의 알리는 노력 가운데 생산물을 알리는 노력은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"mc","stem":"여러 지역의 알리는 노력 가운데 생산물을 알리는 노력은 무엇인가요?","options":[{"t":"마","correct":true},{"t":"나","mis":"SO4-2-u2-X26"},{"t":"다","mis":"SO4-2-u2-X26"},{"t":"라","mis":"SO4-2-u2-X26"}],"explanation":["그 고장에서 나는 것이에요.","쌀이에요.","마예요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#5','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',2,'mc','auto','자연환경과 관련 있는 자랑거리를 알리는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X25','SO4-2-u2-X26']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"mc","stem":"자연환경과 관련 있는 자랑거리를 알리는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"자연환경을 이용한 관광 상품으로 개발해 알려요","correct":true},{"t":"자연환경을 아무에게도 알리지 않아요","mis":"SO4-2-u2-X25"},{"t":"다른 지역의 자연환경을 가져와요","mis":"SO4-2-u2-X26"},{"t":"자연환경을 사진으로만 남겨 두어요","mis":"SO4-2-u2-X26"}],"explanation":["갯벌을 떠올려요.","머드 상품이에요.","관광 상품이에요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#6','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',2,'match','auto','알리는 노력과 그 노력이 알리는 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"match","stem":"알리는 노력과 그 노력이 알리는 갈래를 알맞게 이으세요.","pairs":[{"l":"가. 머드 축제와 머드 상품","r":"자연환경"},{"l":"나. 유적지 견학과 퀴즈","r":"역사"},{"l":"다. 줄다리기와 민속놀이","r":"문화"},{"l":"바. 인삼 직거래 장터","r":"생산물"}],"mis":"SO4-2-u2-X26","explanation":["갯벌은 자연이에요.","유적지는 역사예요.","민속놀이와 인삼도 이어요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#7','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',2,'ox','auto','축제는 자연환경·역사·문화·생산물 네 갈래 모두를 알리는 데 쓰여요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"ox","stem":"축제는 자연환경·역사·문화·생산물 네 갈래 모두를 알리는 데 쓰여요.","answer":"O","reason_options":[{"t":"머드 축제, 역사 축제, 민속 축제, 생산물 축제가 모두 있기 때문에","correct":true},{"t":"축제는 생산물만 알리기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["㉠ 축제예요.","네 갈래에 다 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 축제를 열어요.","㉡ 자연환경을 이용한 관광 상품으로 개발해요.","㉢ 전시회를 열어요.","㉣ 체험 프로그램을 운영해요.","㉤ 민속놀이와 체육 행사를 함께 열어요.","㉥ 박람회를 열어요.","㉦ 직거래 장터를 열어요."],"title":"자랑거리를 알리는 방법 일곱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#8','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',2,'blank','auto','각 지역은 전해 내려오는 역사를 보존하고 알리려고 축제나 (    ) 등 다양한 행사를 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"blank","stem":"각 지역은 전해 내려오는 역사를 보존하고 알리려고 축제나 (    ) 등 다양한 행사를 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전시회","correct":true},{"t":"운동회","mis":"SO4-2-u2-X26"},{"t":"반상회","mis":"SO4-2-u2-X26"},{"t":"졸업식","mis":"SO4-2-u2-X26"}],"explanation":["여러 사람이 와서 봐요.","역사를 펼쳐 보여요.","전시회예요."],"asset":{"type":"passage","lines":["㉠ 축제를 열어요.","㉡ 자연환경을 이용한 관광 상품으로 개발해요.","㉢ 전시회를 열어요.","㉣ 체험 프로그램을 운영해요.","㉤ 민속놀이와 체육 행사를 함께 열어요.","㉥ 박람회를 열어요.","㉦ 직거래 장터를 열어요."],"title":"자랑거리를 알리는 방법 일곱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#9','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',2,'mc','auto','검은 모래 축제에서 알리려는 자랑거리는 어느 갈래와 가장 관련 있나요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"mc","stem":"검은 모래 축제에서 알리려는 자랑거리는 어느 갈래와 가장 관련 있나요?","options":[{"t":"자연환경","correct":true},{"t":"역사","mis":"SO4-2-u2-X26"},{"t":"문화","mis":"SO4-2-u2-X26"},{"t":"생산물","mis":"SO4-2-u2-X26"}],"explanation":["검은 모래 해변이에요.","자연이 만들었어요.","자연환경이에요."],"asset":{"type":"passage","lines":["○○ 바닷가 마을에는 검은 모래 해변이 있다.","마을은 검은 모래를 알리려고 축제를 연다.","축제에서는 모래 조각 전시회와 모래찜질 체험이 펼쳐진다."],"title":"검은 모래 축제(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_basic#10','soc',4,2,'u2','L08','g4_2_soc_u2_L08_basic','lesson_basic','SO4-2-u2-C8',3,'mc','auto','우리 지역이 자랑거리를 알리려고 어떤 노력을 하는지 조사하는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"우리 지역이 자랑거리를 알리려고 어떤 노력을 하는지 조사하는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"다른 지역의 노력을 그대로 옮겨 적어요","correct":true},{"t":"시·군·구청 누리집을 방문해요","mis":"SO4-2-u2-X24"},{"t":"지역 소식지를 찾아봐요","mis":"SO4-2-u2-X24"},{"t":"관광 안내 자료를 활용해요","mis":"SO4-2-u2-X24"}],"explanation":["우리 지역을 조사해요.","옮겨 적으면 안 돼요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#1','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',2,'mc','auto','알리는 방법 일곱 가운데 역사와 문화 두 갈래에 모두 쓰인 방법은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"mc","stem":"알리는 방법 일곱 가운데 역사와 문화 두 갈래에 모두 쓰인 방법은 무엇인가요?","options":[{"t":"㉣ 체험 프로그램","correct":true},{"t":"㉥ 박람회","mis":"SO4-2-u2-X26"},{"t":"㉦ 직거래 장터","mis":"SO4-2-u2-X26"},{"t":"㉡ 관광 상품 개발","mis":"SO4-2-u2-X26"}],"explanation":["나는 역사 체험이에요.","라는 문화 체험이에요.","체험 프로그램이에요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#2','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',2,'ox','auto','박람회와 직거래 장터는 주로 생산물을 알리는 방법이에요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"ox","stem":"박람회와 직거래 장터는 주로 생산물을 알리는 방법이에요.","answer":"O","reason_options":[{"t":"쌀이나 인삼처럼 그 고장에서 나는 것을 알리고 팔기 때문에","correct":true},{"t":"산과 강을 알리는 방법이기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["마와 바를 봐요.","쌀과 인삼이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#3','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',3,'mc','auto','검은 모래 축제에 들어 있는 알리는 방법을 모두 고른 것은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"검은 모래 축제에 들어 있는 알리는 방법을 모두 고른 것은 무엇인가요?","options":[{"t":"축제 · 전시회 · 체험 프로그램","correct":true},{"t":"축제 · 박람회 · 직거래 장터","mis":"SO4-2-u2-X26"},{"t":"관광 상품 개발 · 박람회","mis":"SO4-2-u2-X26"},{"t":"직거래 장터 하나뿐","mis":"SO4-2-u2-X26"}],"explanation":["축제를 열어요.","조각 전시회가 있어요.","모래찜질 체험도 있어요."],"asset":{"type":"passage","lines":["○○ 바닷가 마을에는 검은 모래 해변이 있다.","마을은 검은 모래를 알리려고 축제를 연다.","축제에서는 모래 조각 전시회와 모래찜질 체험이 펼쳐진다."],"title":"검은 모래 축제(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#4','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',3,'error','auto','알리는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X26','SO4-2-u2-X25']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"error","stem":"알리는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지역마다 자랑거리는 한 가지 방법으로만 알려.」","correct":true,"mis_target":"SO4-2-u2-X26"},{"t":"친구 가 — 「갯벌로 축제도 열고 상품도 만들어.」","mis":"SO4-2-u2-X26"},{"t":"친구 다 — 「알리면 지역이 발전할 수 있어.」","mis":"SO4-2-u2-X25"}],"explanation":["가를 떠올려요.","방법이 둘이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#5','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',3,'mc','auto','알리는 방법 ㉠ 축제를 다른 갈래로 옮겨도 네 갈래가 그대로 다 채워지는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X26','SO4-2-u2-X22']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"알리는 방법 ㉠ 축제를 다른 갈래로 옮겨도 네 갈래가 그대로 다 채워지는 까닭은 무엇인가요?","options":[{"t":"갈래마다 그 갈래에만 쓰이는 방법이 따로 있기 때문이에요","correct":true},{"t":"옮긴 방법이 원래 자리에도 그대로 남기 때문이에요","mis":"SO4-2-u2-X26"},{"t":"갈래가 넷보다 많기 때문이에요","mis":"SO4-2-u2-X22"},{"t":"축제는 어느 갈래에도 쓰이지 않기 때문이에요","mis":"SO4-2-u2-X26"}],"explanation":["관광 상품은 자연환경이에요.","박람회는 생산물이에요.","따로 있어요."],"asset":{"type":"passage","lines":["㉠ 축제를 열어요.","㉡ 자연환경을 이용한 관광 상품으로 개발해요.","㉢ 전시회를 열어요.","㉣ 체험 프로그램을 운영해요.","㉤ 민속놀이와 체육 행사를 함께 열어요.","㉥ 박람회를 열어요.","㉦ 직거래 장터를 열어요."],"title":"자랑거리를 알리는 방법 일곱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#6','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',3,'ox','auto','자랑거리를 알리면 그 지역에 사는 사람들도 우리 지역에 자부심을 가질 수 있어요.',ARRAY['SO4-2-u2-X25']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"ox","stem":"자랑거리를 알리면 그 지역에 사는 사람들도 우리 지역에 자부심을 가질 수 있어요.","answer":"O","reason_options":[{"t":"우리 지역의 좋은 점을 함께 알고 자랑하게 되기 때문에","correct":true},{"t":"알리는 노력은 지역 사람과 관계없기 때문에","mis":"SO4-2-u2-X25"}],"mis":"SO4-2-u2-X25","explanation":["누가 알게 될까요?","우리도 알게 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#7','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',3,'mc','auto','우리 지역의 알리는 노력을 조사할 때 쓸 수 있는 방법을 모두 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"우리 지역의 알리는 노력을 조사할 때 쓸 수 있는 방법을 모두 묶은 것은 무엇인가요?","options":[{"t":"시·군·구청 누리집, 사회 관계망 서비스, 지역 소식지, 관광 안내 자료","correct":true},{"t":"다른 지역 소식지만","mis":"SO4-2-u2-X24"},{"t":"상상해서 쓰기","mis":"SO4-2-u2-X24"},{"t":"아무 방법도 없어요","mis":"SO4-2-u2-X24"}],"explanation":["누리집이 있어요.","소식지와 안내 자료도 있어요.","모두 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#8','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',4,'mc','auto','알리는 방법 일곱과 여러 지역의 노력을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X26','SO4-2-u2-X25']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C8","difficulty":4,"kind":"mc","stem":"알리는 방법 일곱과 여러 지역의 노력을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역 사람들은 네 갈래의 자랑거리를 여러 가지 방법으로 알리려고 노력해요","correct":true},{"t":"자랑거리는 생산물만 알려요","mis":"SO4-2-u2-X26"},{"t":"알리는 방법은 한 가지뿐이에요","mis":"SO4-2-u2-X26"},{"t":"자랑거리는 알리지 않는 것이 좋아요","mis":"SO4-2-u2-X25"}],"explanation":["갈래가 넷이에요.","방법은 일곱이에요.","여러 가지로 알려요."],"asset":{"type":"passage","lines":["가. 갯벌에서 얻은 머드로 머드 축제를 열고 여러 가지 상품을 만들어요.","나. 유적지를 견학하고 퀴즈를 풀며 거북선을 그려 봐요.","다. 줄다리기 대회에 민속놀이와 체육 행사를 함께 열어요.","라. 부채를 알리려고 부채 만들기 체험 행사를 해요.","마. 박람회를 열어 그 고장에서 나는 쌀을 알려요.","바. 직거래 장터를 열어 그 고장의 인삼을 알리고 팔아요."],"title":"여러 지역의 알리는 노력(지역 이름은 뺌)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#9','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',4,'mc','auto','같은 방법이 여러 갈래에 쓰이기도 한다는 것을 가장 잘 보여 주는 것은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C8","difficulty":4,"kind":"mc","stem":"같은 방법이 여러 갈래에 쓰이기도 한다는 것을 가장 잘 보여 주는 것은 무엇인가요?","options":[{"t":"축제와 체험 프로그램","correct":true},{"t":"박람회와 직거래 장터","mis":"SO4-2-u2-X26"},{"t":"관광 상품 개발 하나","mis":"SO4-2-u2-X26"},{"t":"민속놀이·체육 행사 하나","mis":"SO4-2-u2-X26"}],"explanation":["여러 갈래에 쓰였나요?","축제는 넷이에요.","체험은 둘이에요."],"asset":{"type":"passage","lines":["㉠ 축제를 열어요.","㉡ 자연환경을 이용한 관광 상품으로 개발해요.","㉢ 전시회를 열어요.","㉣ 체험 프로그램을 운영해요.","㉤ 민속놀이와 체육 행사를 함께 열어요.","㉥ 박람회를 열어요.","㉦ 직거래 장터를 열어요."],"title":"자랑거리를 알리는 방법 일곱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L08_challenge#10','soc',4,2,'u2','L08','g4_2_soc_u2_L08_challenge','lesson_challenge','SO4-2-u2-C8',4,'essay','teacher','○○군의 자랑거리 ⑧ 김을 알리는 노력을 두 가지 계획하고, 그렇게 알리면 ○○군에 어떤 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C8","difficulty":4,"kind":"essay","stem":"○○군의 자랑거리 ⑧ 김을 알리는 노력을 두 가지 계획하고, 그렇게 알리면 ○○군에 어떤 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 김 박람회를 열어 여러 가지 김을 알리고, 직거래 장터를 열어 김을 바로 팔 거예요. 그러면 많은 사람이 ○○군을 알게 되고 관광객이 찾아와 지역 경제에 도움이 되며 지역이 발전할 수 있어요.","scoring_points":["알리는 방법 두 가지를 썼는가","생산물에 알맞은 방법인가","지역에 도움이 되는 점을 썼는가"]},"explanation":["방법을 정해요.","둘이에요.","도움을 써요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#1','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',1,'mc','auto','우리 지역의 자랑거리 소개 자료를 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"mc","stem":"우리 지역의 자랑거리 소개 자료를 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"소개할 자랑거리 정하기 → 소개 방법 정하기 → 소개 자료 만들기","correct":true},{"t":"소개 자료 만들기 → 소개할 자랑거리 정하기","mis":"SO4-2-u2-X27"},{"t":"소개 방법 정하기 → 소개 자료 만들기 → 자랑거리 정하기","mis":"SO4-2-u2-X27"},{"t":"소개 자료 만들기 → 소개 방법 정하기","mis":"SO4-2-u2-X27"}],"explanation":["무엇을 소개할까요?","그다음 방법이에요.","마지막에 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#2','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',1,'sa','auto','안내도를 만들 때 자랑거리가 있는 곳을 색칠하는, 땅의 모양만 그려진 지도를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"sa","stem":"안내도를 만들 때 자랑거리가 있는 곳을 색칠하는, 땅의 모양만 그려진 지도를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["백지도"],"explanation":["하얀 지도예요.","백◯◯예요.","백지도예요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"},"mis":"SO4-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#3','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',1,'ox','auto','만화로 소개 자료를 만들면 자랑거리를 쉽고 재미있게 표현할 수 있어요.',ARRAY['SO4-2-u2-X28']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"ox","stem":"만화로 소개 자료를 만들면 자랑거리를 쉽고 재미있게 표현할 수 있어요.","answer":"O","reason_options":[{"t":"장면과 말풍선으로 이야기처럼 보여 줄 수 있기 때문에","correct":true},{"t":"만화는 그림이 하나도 없기 때문에","mis":"SO4-2-u2-X28"}],"mis":"SO4-2-u2-X28","explanation":["장면을 나눠요.","말풍선이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#4','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',1,'mc','auto','세 가지 소개 자료의 첫 걸음은 무엇인가요?',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"mc","stem":"세 가지 소개 자료의 첫 걸음은 무엇인가요?","options":[{"t":"꾸밀 자랑거리 정리하기","correct":true},{"t":"그림 그리기","mis":"SO4-2-u2-X27"},{"t":"선으로 잇기","mis":"SO4-2-u2-X27"},{"t":"설명 문구 쓰기","mis":"SO4-2-u2-X27"}],"explanation":["①을 봐요.","셋 다 같아요.","자랑거리 정리예요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#5','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',2,'mc','auto','안내도를 만들면 좋은 점은 무엇인가요?',ARRAY['SO4-2-u2-X28']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"mc","stem":"안내도를 만들면 좋은 점은 무엇인가요?","options":[{"t":"자랑거리가 있는 곳과 특징을 한눈에 살펴볼 수 있어요","correct":true},{"t":"자랑거리를 감출 수 있어요","mis":"SO4-2-u2-X28"},{"t":"자랑거리를 하나만 나타낼 수 있어요","mis":"SO4-2-u2-X28"},{"t":"그림을 하나도 그리지 않아도 돼요","mis":"SO4-2-u2-X28"}],"explanation":["백지도에 색칠해요.","선으로 이어요.","위치가 한눈에 보여요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#6','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',2,'match','auto','소개 자료와 그 자료를 만드는 걸음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"match","stem":"소개 자료와 그 자료를 만드는 걸음을 알맞게 이으세요.","pairs":[{"l":"만화","r":"4~6개의 장면으로 나누기"},{"l":"포스터","r":"설명 문구 쓰기"},{"l":"안내도","r":"색칠한 곳과 자료를 선으로 잇기"}],"mis":"SO4-2-u2-X28","explanation":["만화는 장면이에요.","포스터는 문구예요.","안내도는 선이에요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#7','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',2,'ox','auto','사회 관계망 서비스로 소개할 때 확인되지 않은 정보도 빨리 올리는 것이 좋아요.',ARRAY['SO4-2-u2-X29']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"ox","stem":"사회 관계망 서비스로 소개할 때 확인되지 않은 정보도 빨리 올리는 것이 좋아요.","answer":"X","reason_options":[{"t":"확인되지 않은 정보는 잘못 알려질 수 있어 올리지 않아야 하기 때문에","correct":true},{"t":"빨리 올릴수록 언제나 정확하기 때문에","mis":"SO4-2-u2-X29"}],"mis":"SO4-2-u2-X29","explanation":["①을 읽어요.","확인이 먼저예요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 확인되지 않은 정보를 게시하지 않아요.","② 저작권에 문제없는 자료를 게시해요.","③ 다른 사람의 개인적인 소식과 사진을 허락 없이 게시하지 않아요."],"title":"사회 관계망 서비스로 소개할 때 지킬 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#8','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',2,'blank','auto','사회 관계망 서비스에는 (    )에 문제없는 자료를 게시해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X29']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"blank","stem":"사회 관계망 서비스에는 (    )에 문제없는 자료를 게시해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"저작권","correct":true},{"t":"날씨","mis":"SO4-2-u2-X29"},{"t":"주차장","mis":"SO4-2-u2-X29"},{"t":"시간표","mis":"SO4-2-u2-X29"}],"explanation":["만든 사람의 권리예요.","저작◯이에요.","저작권이에요."],"asset":{"type":"passage","lines":["① 확인되지 않은 정보를 게시하지 않아요.","② 저작권에 문제없는 자료를 게시해요.","③ 다른 사람의 개인적인 소식과 사진을 허락 없이 게시하지 않아요."],"title":"사회 관계망 서비스로 소개할 때 지킬 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_basic#9','soc',4,2,'u2','L09','g4_2_soc_u2_L09_basic','lesson_basic','SO4-2-u2-C9',2,'mc','auto','친구들의 발표를 듣는 모습으로 알맞은 친구는 누구인가요?',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"mc","stem":"친구들의 발표를 듣는 모습으로 알맞은 친구는 누구인가요?","options":[{"t":"친구 다","correct":true},{"t":"친구 나","mis":"SO4-2-u2-X27"},{"t":"친구 가와 나 모두","mis":"SO4-2-u2-X27"},{"t":"아무도 없어요","mis":"SO4-2-u2-X27"}],"explanation":["바라보며 들어요.","궁금한 점을 적어요.","친구 다예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"우리 모둠은 ○○군 김을 포스터로 소개할게요."},{"who":"친구 나","text":"(다른 모둠 발표 때 고개를 숙이고 딴 책을 본다.)"},{"who":"친구 다","text":"발표하는 친구를 바라보며 궁금한 점을 적어 두었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
