INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#1','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',2,'mc','auto','세 가지 소개 자료를 모두 만들면 걸음은 모두 몇 걸음인가요?',ARRAY['SO4-2-u2-X28']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"mc","stem":"세 가지 소개 자료를 모두 만들면 걸음은 모두 몇 걸음인가요?","options":[{"t":"10걸음","correct":true},{"t":"9걸음","mis":"SO4-2-u2-X28"},{"t":"11걸음","mis":"SO4-2-u2-X28"},{"t":"12걸음","mis":"SO4-2-u2-X28"}],"explanation":["만화 셋, 포스터 셋이에요.","안내도는 넷이에요.","열 걸음이에요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#2','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',2,'ox','auto','어떤 방법으로 만들든 꾸밀 자랑거리를 먼저 정리해요.',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C9","difficulty":2,"kind":"ox","stem":"어떤 방법으로 만들든 꾸밀 자랑거리를 먼저 정리해요.","answer":"O","reason_options":[{"t":"무엇을 소개할지 알아야 그에 맞게 꾸밀 수 있기 때문에","correct":true},{"t":"방법마다 첫 걸음이 모두 다르기 때문에","mis":"SO4-2-u2-X27"}],"mis":"SO4-2-u2-X27","explanation":["①을 견줘요.","셋 다 정리예요.","그래서 O예요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#3','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',3,'mc','auto','우리 지역의 여러 자랑거리가 어디에 있는지 한눈에 알리고 싶어요. 가장 알맞은 소개 방법은 무엇인가요?',ARRAY['SO4-2-u2-X28','SO4-2-u2-X27']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"mc","stem":"우리 지역의 여러 자랑거리가 어디에 있는지 한눈에 알리고 싶어요. 가장 알맞은 소개 방법은 무엇인가요?","options":[{"t":"안내도 만들기","correct":true},{"t":"만화 그리기","mis":"SO4-2-u2-X28"},{"t":"포스터 만들기","mis":"SO4-2-u2-X28"},{"t":"동네 친구에게만 말하기","mis":"SO4-2-u2-X27"}],"explanation":["어디에 있는지예요.","지도를 써요.","안내도예요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#4','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',3,'error','auto','소개 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"error","stem":"소개 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「포스터부터 다 만들고 무엇을 소개할지는 나중에 정하자.」","correct":true,"mis_target":"SO4-2-u2-X27"},{"t":"친구 가 — 「소개할 자랑거리부터 정하자.」","mis":"SO4-2-u2-X27"},{"t":"친구 다 — 「우리 모둠이 함께 방법을 정하자.」","mis":"SO4-2-u2-X27"}],"explanation":["차례를 떠올려요.","자랑거리가 먼저예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#5','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',3,'mc','auto','사회 관계망 서비스에 ○○군 축제 사진을 올리려고 해요. 친구가 찍힌 사진이라면 어떻게 해야 하나요?',ARRAY['SO4-2-u2-X29']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"mc","stem":"사회 관계망 서비스에 ○○군 축제 사진을 올리려고 해요. 친구가 찍힌 사진이라면 어떻게 해야 하나요?","options":[{"t":"그 친구에게 허락을 받은 뒤에 올려요","correct":true},{"t":"허락 없이 바로 올려요","mis":"SO4-2-u2-X29"},{"t":"친구 얼굴만 크게 올려요","mis":"SO4-2-u2-X29"},{"t":"친구 이름도 함께 마음대로 써요","mis":"SO4-2-u2-X29"}],"explanation":["③을 읽어요.","남의 사진이에요.","허락을 받아요."],"asset":{"type":"passage","lines":["① 확인되지 않은 정보를 게시하지 않아요.","② 저작권에 문제없는 자료를 게시해요.","③ 다른 사람의 개인적인 소식과 사진을 허락 없이 게시하지 않아요."],"title":"사회 관계망 서비스로 소개할 때 지킬 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#6','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',3,'ox','auto','친구 나처럼 다른 모둠 발표 때 딴 책을 보아도 괜찮아요.',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"ox","stem":"친구 나처럼 다른 모둠 발표 때 딴 책을 보아도 괜찮아요.","answer":"X","reason_options":[{"t":"친구들이 소개하는 자랑거리에 관심을 가지고 들어야 하기 때문에","correct":true},{"t":"내 발표만 끝나면 활동이 끝나기 때문에","mis":"SO4-2-u2-X27"}],"mis":"SO4-2-u2-X27","explanation":["친구 나를 봐요.","관심을 가져야 해요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"우리 모둠은 ○○군 김을 포스터로 소개할게요."},{"who":"친구 나","text":"(다른 모둠 발표 때 고개를 숙이고 딴 책을 본다.)"},{"who":"친구 다","text":"발표하는 친구를 바라보며 궁금한 점을 적어 두었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#7','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',3,'mc','auto','다른 지역의 소개 자료를 그대로 옮겨 붙이면 안 되는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X27','SO4-2-u2-X29','SO4-2-u2-X28']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"mc","stem":"다른 지역의 소개 자료를 그대로 옮겨 붙이면 안 되는 까닭은 무엇인가요?","options":[{"t":"우리 지역을 소개한 자료가 아니기 때문이에요","correct":true},{"t":"옮겨 붙이면 자료가 너무 예뻐지기 때문이에요","mis":"SO4-2-u2-X27"},{"t":"옮겨 붙이는 것이 더 정확하기 때문이에요","mis":"SO4-2-u2-X29"},{"t":"소개 자료는 꼭 하나여야 하기 때문이에요","mis":"SO4-2-u2-X28"}],"explanation":["누구의 자랑거리예요?","우리 지역이에요.","옮기면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#8','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',4,'mc','auto','세 가지 소개 자료 만드는 차례를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X28','SO4-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":4,"kind":"mc","stem":"세 가지 소개 자료 만드는 차례를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"방법은 달라도 꾸밀 자랑거리를 먼저 정리하고, 방법에 맞게 자료를 만들어요","correct":true},{"t":"세 방법은 모두 같은 방법이에요","mis":"SO4-2-u2-X28"},{"t":"걸음 수가 많은 방법이 언제나 좋아요","mis":"SO4-2-u2-X28"},{"t":"자랑거리는 마지막에 정해요","mis":"SO4-2-u2-X27"}],"explanation":["첫 걸음이 같아요.","나머지는 달라요.","방법에 맞게 만들어요."],"asset":{"type":"passage","lines":["만화 — ① 꾸밀 자랑거리 정리 ② 4~6개의 장면으로 나누기 ③ 그림·말풍선을 넣어 완성","포스터 — ① 꾸밀 자랑거리 정리 ② 그림을 그리거나 사진 붙이기 ③ 설명 문구 쓰기","안내도 — ① 꾸밀 자랑거리 정리 ② 백지도에 색칠 ③ 설명 자료 붙이기 ④ 선으로 잇기"],"title":"세 가지 소개 자료 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#9','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',4,'mc','auto','자랑거리를 소개하는 활동에 적극적으로 참여하면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X27','SO4-2-u2-X30']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C9","difficulty":4,"kind":"mc","stem":"자랑거리를 소개하는 활동에 적극적으로 참여하면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 지역을 더 깊이 이해하고 우리 지역에 자부심을 가질 수 있어요","correct":true},{"t":"다른 지역을 싫어하게 돼요","mis":"SO4-2-u2-X27"},{"t":"발표한 사람만 지역을 알게 돼요","mis":"SO4-2-u2-X27"},{"t":"지역문제가 저절로 사라져요","mis":"SO4-2-u2-X30"}],"explanation":["소개하고 들어요.","우리 지역을 알아요.","자부심이 생겨요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"우리 모둠은 ○○군 김을 포스터로 소개할게요."},{"who":"친구 나","text":"(다른 모둠 발표 때 고개를 숙이고 딴 책을 본다.)"},{"who":"친구 다","text":"발표하는 친구를 바라보며 궁금한 점을 적어 두었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L09_challenge#10','soc',4,2,'u2','L09','g4_2_soc_u2_L09_challenge','lesson_challenge','SO4-2-u2-C9',4,'essay','teacher','○○군의 자랑거리 하나를 골라 만화·포스터·안내도 가운데 하나로 소개하려고 해요. 고른 방법과 까닭을 쓰고, 만드는 걸음을 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C9","difficulty":4,"kind":"essay","stem":"○○군의 자랑거리 하나를 골라 만화·포스터·안내도 가운데 하나로 소개하려고 해요. 고른 방법과 까닭을 쓰고, 만드는 걸음을 차례대로 쓰세요.","answer_guide":{"answer":"예: ① 큰 강을 포스터로 소개할래요. 강의 아름다운 모습이 그림으로 잘 드러나기 때문이에요. 먼저 큰 강에 대해 정리하고, 강 그림을 그리거나 사진을 붙인 뒤, 강을 설명하는 문구를 쓸 거예요.","scoring_points":["방법을 고르고 까닭을 썼는가","첫 걸음이 자랑거리 정리인가","방법에 맞는 걸음을 차례대로 썼는가"]},"explanation":["방법을 골라요.","까닭을 써요.","걸음을 써요."],"asset":{"type":"passage","lines":["① 군 한가운데를 지나 바다로 흐르는 큰 강","② 동식물이 다양하고 경관이 아름다운 높은 산","③ 옛날 고장을 지키려고 의병을 이끈 사람","④ 옛사람의 생활을 알 수 있는 고인돌 유적","⑤ 옛 도자기 굽는 솜씨를 보여 주는 도자기 축제","⑥ 세계 여러 나라의 정원을 볼 수 있는 정원 박람회","⑦ 군에서 자란 대나무로 만든 물건","⑧ 앞바다에서 길러 거둔 김"],"title":"○○군의 자랑거리 여덟(가상의 군)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#1','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',1,'mc','auto','지역의 자랑거리와 관련 있는 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C10","difficulty":1,"kind":"mc","stem":"지역의 자랑거리와 관련 있는 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"다른 지역에만 있는 것","correct":true},{"t":"자연환경","mis":"SO4-2-u2-X22"},{"t":"역사","mis":"SO4-2-u2-X22"},{"t":"생산물","mis":"SO4-2-u2-X22"}],"explanation":["우리 지역에 있어요.","다른 곳에만 있으면요?","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#2','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',1,'sa','auto','「문제를 풀고 암호를 알아내요」에서 알맞은 문장은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C10","difficulty":1,"kind":"sa","stem":"「문제를 풀고 암호를 알아내요」에서 알맞은 문장은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["①과 ③을 봐요.","②·④는 아니에요.","두 개예요."],"asset":{"type":"passage","lines":["① 지역에는 자연환경, 역사, 문화, 생산물 등과 관련 있는 자랑거리가 있어요.","② 지역의 자랑거리로 지역에서 일어나는 문제를 알 수 있어요.","③ 지역에서는 축제, 전시회 등을 열어서 지역의 역사를 알려요.","④ 지역마다 자연환경, 역사, 문화 등이 달라도 생산물은 같아요."],"title":"문제를 풀고 암호를 알아내요"},"mis":"SO4-2-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#3','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',1,'ox','auto','「문제를 풀고 암호를 알아내요」의 ③은 알맞은 문장이에요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C10","difficulty":1,"kind":"ox","stem":"「문제를 풀고 암호를 알아내요」의 ③은 알맞은 문장이에요.","answer":"O","reason_options":[{"t":"지역에서 축제와 전시회를 열어 역사를 알리기 때문에","correct":true},{"t":"역사는 축제로 알릴 수 없기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["③을 읽어요.","축제와 전시회예요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 지역에는 자연환경, 역사, 문화, 생산물 등과 관련 있는 자랑거리가 있어요.","② 지역의 자랑거리로 지역에서 일어나는 문제를 알 수 있어요.","③ 지역에서는 축제, 전시회 등을 열어서 지역의 역사를 알려요.","④ 지역마다 자연환경, 역사, 문화 등이 달라도 생산물은 같아요."],"title":"문제를 풀고 암호를 알아내요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#4','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',1,'mc','auto','선택 활동 1 동시 짓기에서 가장 먼저 할 일은 무엇인가요?',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C10","difficulty":1,"kind":"mc","stem":"선택 활동 1 동시 짓기에서 가장 먼저 할 일은 무엇인가요?","options":[{"t":"동시에 넣을 생산물을 세 가지 이상 정해요","correct":true},{"t":"사진을 붙이거나 그림을 그려요","mis":"SO4-2-u2-X31"},{"t":"친구들 앞에서 발표해요","mis":"SO4-2-u2-X31"},{"t":"동시를 큰 소리로 읽어요","mis":"SO4-2-u2-X31"}],"explanation":["①을 봐요.","무엇을 넣을까요?","생산물을 정해요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#5','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',2,'mc','auto','지역마다 자연환경, 역사, 문화 등이 다르면 생산물은 어떨까요?',ARRAY['SO4-2-u2-X30','SO4-2-u2-X22']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"mc","stem":"지역마다 자연환경, 역사, 문화 등이 다르면 생산물은 어떨까요?","options":[{"t":"지역마다 생산물도 달라요","correct":true},{"t":"지역마다 생산물은 모두 같아요","mis":"SO4-2-u2-X30"},{"t":"생산물은 자랑거리가 될 수 없어요","mis":"SO4-2-u2-X22"},{"t":"생산물은 한 가지뿐이에요","mis":"SO4-2-u2-X30"}],"explanation":["땅과 날씨가 달라요.","나는 것도 달라요.","생산물도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#6','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',2,'match','auto','상품 기획서의 칸과 한 친구가 쓴 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"match","stem":"상품 기획서의 칸과 한 친구가 쓴 내용을 알맞게 이으세요.","pairs":[{"l":"상품으로 만들 자랑거리","r":"○○군 앞바다 김"},{"l":"정한 까닭","r":"정성껏 길러 거두어 맛이 좋아서"},{"l":"기획한 상품","r":"김 모양 열쇠고리와 김 과자"}],"mis":"SO4-2-u2-X31","explanation":["자랑거리는 김이에요.","까닭은 맛이에요.","상품은 열쇠고리예요."],"asset":{"type":"passage","lines":["상품으로 만들 자랑거리 — ○○군 앞바다 김","정한 까닭 — 맛이 좋고 바다에서 정성껏 길러 거두기 때문에","기획한 상품 — 김 모양 열쇠고리와 김 과자 꾸러미"],"title":"한 친구의 상품 기획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#7','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',2,'ox','auto','「문제를 풀고 암호를 알아내요」의 ②는 알맞은 문장이에요.',ARRAY['SO4-2-u2-X30']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"ox","stem":"「문제를 풀고 암호를 알아내요」의 ②는 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"자랑거리로는 지역의 특징을 알 수 있고, 지역문제를 알 수 있는 것은 아니기 때문에","correct":true},{"t":"자랑거리는 곧 지역문제이기 때문에","mis":"SO4-2-u2-X30"}],"mis":"SO4-2-u2-X30","explanation":["②를 읽어요.","자랑거리와 지역문제예요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 지역에는 자연환경, 역사, 문화, 생산물 등과 관련 있는 자랑거리가 있어요.","② 지역의 자랑거리로 지역에서 일어나는 문제를 알 수 있어요.","③ 지역에서는 축제, 전시회 등을 열어서 지역의 역사를 알려요.","④ 지역마다 자연환경, 역사, 문화 등이 달라도 생산물은 같아요."],"title":"문제를 풀고 암호를 알아내요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#8','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',2,'blank','auto','지역을 알리는 노력 정리 활동은 두 활동 가운데 (    )를 골라 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"blank","stem":"지역을 알리는 노력 정리 활동은 두 활동 가운데 (    )를 골라 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하나","correct":true},{"t":"둘 다","mis":"SO4-2-u2-X31"},{"t":"셋","mis":"SO4-2-u2-X31"},{"t":"아무것도","mis":"SO4-2-u2-X31"}],"explanation":["맨 아래 줄을 읽어요.","골라서 해요.","하나예요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#9','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',2,'mc','auto','자랑거리를 알리는 다양한 노력을 조사할 때 쓴 자료로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"mc","stem":"자랑거리를 알리는 다양한 노력을 조사할 때 쓴 자료로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"누리집 · 사회 관계망 서비스 · 소식지 · 관광 안내 자료","correct":true},{"t":"상상 · 꿈 · 느낌","mis":"SO4-2-u2-X24"},{"t":"다른 지역 소식지만","mis":"SO4-2-u2-X24"},{"t":"아무 자료도 없어요","mis":"SO4-2-u2-X24"}],"explanation":["누리집이 있어요.","소식지도 있어요.","여러 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_basic#10','soc',4,2,'u2','L10','g4_2_soc_u2_L10_basic','lesson_basic','SO4-2-u2-C10',3,'mc','auto','「문제를 풀고 암호를 알아내요」의 ④를 알맞게 고친 것은 무엇인가요?',ARRAY['SO4-2-u2-X30']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「문제를 풀고 암호를 알아내요」의 ④를 알맞게 고친 것은 무엇인가요?","options":[{"t":"지역마다 자연환경, 역사, 문화 등이 다르고 생산물도 달라요","correct":true},{"t":"지역마다 생산물은 하나도 없어요","mis":"SO4-2-u2-X30"},{"t":"생산물은 날씨와만 관계있어요","mis":"SO4-2-u2-X30"},{"t":"지역마다 자연환경도 같아요","mis":"SO4-2-u2-X30"}],"explanation":["④를 읽어요.","생산물도 다를까요?","다르게 고쳐요."],"asset":{"type":"passage","lines":["① 지역에는 자연환경, 역사, 문화, 생산물 등과 관련 있는 자랑거리가 있어요.","② 지역의 자랑거리로 지역에서 일어나는 문제를 알 수 있어요.","③ 지역에서는 축제, 전시회 등을 열어서 지역의 역사를 알려요.","④ 지역마다 자연환경, 역사, 문화 등이 달라도 생산물은 같아요."],"title":"문제를 풀고 암호를 알아내요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#1','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',2,'mc','auto','「문제를 풀고 암호를 알아내요」에서 알맞지 않은 문장끼리 묶은 것은 무엇인가요?',ARRAY['SO4-2-u2-X30']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「문제를 풀고 암호를 알아내요」에서 알맞지 않은 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"② · ④","correct":true},{"t":"① · ③","mis":"SO4-2-u2-X30"},{"t":"① · ②","mis":"SO4-2-u2-X30"},{"t":"③ · ④","mis":"SO4-2-u2-X30"}],"explanation":["②는 지역문제예요.","④는 생산물이에요.","②·④예요."],"asset":{"type":"passage","lines":["① 지역에는 자연환경, 역사, 문화, 생산물 등과 관련 있는 자랑거리가 있어요.","② 지역의 자랑거리로 지역에서 일어나는 문제를 알 수 있어요.","③ 지역에서는 축제, 전시회 등을 열어서 지역의 역사를 알려요.","④ 지역마다 자연환경, 역사, 문화 등이 달라도 생산물은 같아요."],"title":"문제를 풀고 암호를 알아내요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#2','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',2,'ox','auto','동시 짓기를 골랐다면 상품 기획하기는 하지 않아도 정리를 마칠 수 있어요.',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"ox","stem":"동시 짓기를 골랐다면 상품 기획하기는 하지 않아도 정리를 마칠 수 있어요.","answer":"O","reason_options":[{"t":"두 활동 가운데 하나를 골라 하는 활동이기 때문에","correct":true},{"t":"두 활동을 모두 해야만 끝나기 때문에","mis":"SO4-2-u2-X31"}],"mis":"SO4-2-u2-X31","explanation":["맨 아래 줄이에요.","하나를 골라요.","그래서 O예요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#3','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',3,'mc','auto','한 친구의 상품 기획서에서 「정한 까닭」이 하는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X31','SO4-2-u2-X30']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"한 친구의 상품 기획서에서 「정한 까닭」이 하는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"왜 그 자랑거리를 상품으로 골랐는지 알려 줘요","correct":true},{"t":"상품의 값을 알려 줘요","mis":"SO4-2-u2-X31"},{"t":"다른 지역의 상품을 알려 줘요","mis":"SO4-2-u2-X30"},{"t":"지역문제를 알려 줘요","mis":"SO4-2-u2-X30"}],"explanation":["둘째 줄을 읽어요.","김을 고른 까닭이에요.","왜 골랐는지예요."],"asset":{"type":"passage","lines":["상품으로 만들 자랑거리 — ○○군 앞바다 김","정한 까닭 — 맛이 좋고 바다에서 정성껏 길러 거두기 때문에","기획한 상품 — 김 모양 열쇠고리와 김 과자 꾸러미"],"title":"한 친구의 상품 기획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#4','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',3,'error','auto','주제②를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X31','SO4-2-u2-X22','SO4-2-u2-X30']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"error","stem":"주제②를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「정리 활동 두 가지를 모두 해야만 끝나.」","correct":true,"mis_target":"SO4-2-u2-X31"},{"t":"친구 가 — 「자랑거리는 네 갈래로 나눌 수 있어.」","mis":"SO4-2-u2-X22"},{"t":"친구 나 — 「지역마다 생산물이 달라.」","mis":"SO4-2-u2-X30"}],"explanation":["두 활동을 떠올려요.","하나를 골라요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#5','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',3,'mc','auto','정리 활동의 칸을 세 칸 채웠는데, 그 세 칸이 두 활동에 나뉘어 있다면 어떻게 될까요?',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"정리 활동의 칸을 세 칸 채웠는데, 그 세 칸이 두 활동에 나뉘어 있다면 어떻게 될까요?","options":[{"t":"어느 한 활동도 다 채워지지 않아 정리를 마치지 못해요","correct":true},{"t":"세 칸이니 정리를 마쳐요","mis":"SO4-2-u2-X31"},{"t":"두 활동이 모두 끝나요","mis":"SO4-2-u2-X31"},{"t":"칸 수와 관계없이 언제나 끝나요","mis":"SO4-2-u2-X31"}],"explanation":["한 활동이 다 찼나요?","나뉘어 있어요.","아직 못 마쳐요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#6','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',3,'ox','auto','김 과자 꾸러미 같은 상품을 기획하는 것도 지역의 자랑거리를 알리는 방법이 될 수 있어요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"ox","stem":"김 과자 꾸러미 같은 상품을 기획하는 것도 지역의 자랑거리를 알리는 방법이 될 수 있어요.","answer":"O","reason_options":[{"t":"상품을 보고 사는 사람들이 그 지역의 생산물을 알게 되기 때문에","correct":true},{"t":"상품은 지역과 관계없기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["기획한 상품이에요.","김을 담았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["상품으로 만들 자랑거리 — ○○군 앞바다 김","정한 까닭 — 맛이 좋고 바다에서 정성껏 길러 거두기 때문에","기획한 상품 — 김 모양 열쇠고리와 김 과자 꾸러미"],"title":"한 친구의 상품 기획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#7','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',3,'mc','auto','선택 활동 1과 선택 활동 2가 함께 다루는 것은 무엇인가요?',ARRAY['SO4-2-u2-X30','SO4-2-u2-X24','SO4-2-u2-X31']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"선택 활동 1과 선택 활동 2가 함께 다루는 것은 무엇인가요?","options":[{"t":"우리 지역의 자랑거리","correct":true},{"t":"우리 지역의 지역문제","mis":"SO4-2-u2-X30"},{"t":"다른 지역의 축제 날짜","mis":"SO4-2-u2-X24"},{"t":"우리 반의 시간표","mis":"SO4-2-u2-X31"}],"explanation":["동시는 생산물이에요.","상품도 자랑거리예요.","둘 다 자랑거리예요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#8','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',4,'mc','auto','주제② 「지역을 알리는 노력」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u2-X26','SO4-2-u2-X30']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C10","difficulty":4,"kind":"mc","stem":"주제② 「지역을 알리는 노력」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"지역의 네 갈래 자랑거리를 조사하고, 여러 방법으로 알리는 노력과 활동을 해요","correct":true},{"t":"자랑거리는 한 가지 방법으로만 알려요","mis":"SO4-2-u2-X26"},{"t":"지역마다 생산물과 자랑거리가 똑같아요","mis":"SO4-2-u2-X30"},{"t":"자랑거리로 지역문제를 찾아요","mis":"SO4-2-u2-X30"}],"explanation":["조사했어요.","알리는 노력을 봤어요.","활동도 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#9','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',4,'mc','auto','「문제를 풀고 암호를 알아내요」와 정리 활동을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C10","difficulty":4,"kind":"mc","stem":"「문제를 풀고 암호를 알아내요」와 정리 활동을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"배운 내용은 문제 풀이, 동시, 기획서처럼 다양한 방법으로 정리할 수 있어요","correct":true},{"t":"정리는 글로만 해야 해요","mis":"SO4-2-u2-X31"},{"t":"정리하는 방법은 한 가지로 정해져 있어요","mis":"SO4-2-u2-X31"},{"t":"정리 활동은 모두 해야 해요","mis":"SO4-2-u2-X31"}],"explanation":["문제 풀이가 있어요.","동시와 기획서도 있어요.","다양하게 정리해요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_L10_challenge#10','soc',4,2,'u2','L10','g4_2_soc_u2_L10_challenge','lesson_challenge','SO4-2-u2-C10',4,'essay','teacher','우리 지역의 생산물 세 가지를 넣어 짧은 동시를 지을 계획을 쓰고, 이 동시로 우리 지역을 어떻게 알릴 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C10","difficulty":4,"kind":"essay","stem":"우리 지역의 생산물 세 가지를 넣어 짧은 동시를 지을 계획을 쓰고, 이 동시로 우리 지역을 어떻게 알릴 수 있는지 쓰세요.","answer_guide":{"answer":"예: 우리 지역의 쌀, 사과, 인삼을 넣어 「햇살 먹고 자란 우리 고장」이라는 동시를 지을 거예요. 동시를 친구들 앞에서 발표하고 그림과 함께 전시하면, 우리 지역에서 맛있는 생산물이 많이 난다는 것을 알릴 수 있어요.","scoring_points":["생산물 세 가지를 썼는가","동시 계획을 썼는가","알리는 방법을 썼는가"]},"explanation":["생산물을 정해요.","동시를 계획해요.","알리는 방법을 써요."],"asset":{"type":"passage","lines":["선택 활동 1 — 동시 짓기","① 동시에 넣을 우리 지역의 생산물을 세 가지 이상 정해요.","② 동시를 쓰고, 사진을 붙이거나 그림을 그려 완성해요.","③ 친구들 앞에서 발표해요.","선택 활동 2 — 상품 기획하기","① 상품으로 만들 자랑거리 ② 그 자랑거리로 정한 까닭 ③ 기획한 상품 그리기","두 활동 가운데 하나를 골라 해요."],"title":"지역을 알리는 노력 정리 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#1','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C1',1,'mc','auto','소식지 ①에서 공터 쓰레기가 지역문제인 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X04','SO4-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"mc","stem":"소식지 ①에서 공터 쓰레기가 지역문제인 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"놀이터를 쓰는 여러 주민의 생활을 불편하게 하기 때문이에요","correct":true},{"t":"한 사람에게만 생긴 일이기 때문이에요","mis":"SO4-2-u2-X01"},{"t":"저절로 사라지기 때문이에요","mis":"SO4-2-u2-X04"},{"t":"다른 지역의 일이기 때문이에요","mis":"SO4-2-u2-X02"}],"explanation":["누가 불편한가요?","여러 주민이에요.","지역문제예요."],"asset":{"type":"passage","lines":["○○동 놀이터 옆 공터에 쓰레기를 몰래 버리는 일이 늘었다.","냄새가 나고 벌레가 꼬여 놀이터를 쓰는 주민들이 불편해졌다.","주민들은 공터를 직접 둘러보고 구청 누리집에 올라온 글도 찾아보았다."],"title":"소식지 ① — 공터 쓰레기 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#2','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C2',1,'mc','auto','소식지 ①에서 주민들이 우리 지역의 문제를 확인한 방법은 무엇인가요?',ARRAY['SO4-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"mc","stem":"소식지 ①에서 주민들이 우리 지역의 문제를 확인한 방법은 무엇인가요?","options":[{"t":"공터를 직접 둘러보고 누리집 글을 찾아보았어요","correct":true},{"t":"눈을 감고 상상했어요","mis":"SO4-2-u2-X05"},{"t":"옆 동네 소식지를 옮겨 적었어요","mis":"SO4-2-u2-X05"},{"t":"아무것도 하지 않았어요","mis":"SO4-2-u2-X05"}],"explanation":["③째 줄을 읽어요.","둘러보았어요.","누리집도 봤어요."],"asset":{"type":"passage","lines":["○○동 놀이터 옆 공터에 쓰레기를 몰래 버리는 일이 늘었다.","냄새가 나고 벌레가 꼬여 놀이터를 쓰는 주민들이 불편해졌다.","주민들은 공터를 직접 둘러보고 구청 누리집에 올라온 글도 찾아보았다."],"title":"소식지 ① — 공터 쓰레기 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#3','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C3',1,'mc','auto','소식지 ②의 자료 ㉠은 어떤 종류의 자료인가요?',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"mc","stem":"소식지 ②의 자료 ㉠은 어떤 종류의 자료인가요?","options":[{"t":"통계 자료","correct":true},{"t":"신문 기사","mis":"SO4-2-u2-X11"},{"t":"설문 조사 결과","mis":"SO4-2-u2-X11"},{"t":"공익 광고","mis":"SO4-2-u2-X11"}],"explanation":["㉠은 표예요.","수를 정리했어요.","통계 자료예요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#4','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C4',1,'mc','auto','소식지 ③의 방안 셋 가운데 1점인 자리가 없는 방안은 무엇인가요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"mc","stem":"소식지 ③의 방안 셋 가운데 1점인 자리가 없는 방안은 무엇인가요?","options":[{"t":"방안 ㉯","correct":true},{"t":"방안 ㉮","mis":"SO4-2-u2-X14"},{"t":"방안 ㉰","mis":"SO4-2-u2-X14"},{"t":"셋 다 1점이 있어요","mis":"SO4-2-u2-X14"}],"explanation":["1을 찾아요.","㉮·㉰에 있어요.","㉯예요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#5','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C5',1,'mc','auto','소식지 ④에서 주민들이 직접 한 일은 무엇인가요?',ARRAY['SO4-2-u2-X17','SO4-2-u2-X16']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"mc","stem":"소식지 ④에서 주민들이 직접 한 일은 무엇인가요?","options":[{"t":"안내문을 붙이고 함께 캠페인을 벌였어요","correct":true},{"t":"쓰레기통을 직접 설치했어요","mis":"SO4-2-u2-X17"},{"t":"단속을 직접 했어요","mis":"SO4-2-u2-X17"},{"t":"구청이 해 줄 때까지 기다렸어요","mis":"SO4-2-u2-X16"}],"explanation":["첫째 줄을 읽어요.","안내문과 캠페인이에요.","주민이 했어요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#6','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C7',1,'mc','auto','소식지 ⑤의 ㉱ 복숭아는 어느 갈래의 자랑거리인가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"mc","stem":"소식지 ⑤의 ㉱ 복숭아는 어느 갈래의 자랑거리인가요?","options":[{"t":"생산물","correct":true},{"t":"자연환경","mis":"SO4-2-u2-X22"},{"t":"역사","mis":"SO4-2-u2-X22"},{"t":"문화","mis":"SO4-2-u2-X22"}],"explanation":["과수원에서 거둬요.","그곳에서 나요.","생산물이에요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#7','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C8',1,'mc','auto','소식지 ⑥에서 복숭아를 알리고 파는 곳은 어디인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"mc","stem":"소식지 ⑥에서 복숭아를 알리고 파는 곳은 어디인가요?","options":[{"t":"직거래 장터","correct":true},{"t":"전시회","mis":"SO4-2-u2-X26"},{"t":"주민 회의","mis":"SO4-2-u2-X26"},{"t":"공터","mis":"SO4-2-u2-X26"}],"explanation":["첫째 줄을 읽어요.","팔기도 해요.","직거래 장터예요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#8','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C9',1,'mc','auto','소식지 ⑦에서 푸른반 모둠이 고른 소개 방법은 무엇인가요?',ARRAY['SO4-2-u2-X28','SO4-2-u2-X31']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"mc","stem":"소식지 ⑦에서 푸른반 모둠이 고른 소개 방법은 무엇인가요?","options":[{"t":"안내도","correct":true},{"t":"만화","mis":"SO4-2-u2-X28"},{"t":"포스터","mis":"SO4-2-u2-X28"},{"t":"동시","mis":"SO4-2-u2-X31"}],"explanation":["첫째 줄을 읽어요.","백지도를 써요.","안내도예요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#9','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C1',2,'mc','auto','소식지 ①의 공터 쓰레기 문제를 그냥 두면 어떻게 될까요?',ARRAY['SO4-2-u2-X04','SO4-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"mc","stem":"소식지 ①의 공터 쓰레기 문제를 그냥 두면 어떻게 될까요?","options":[{"t":"냄새와 벌레가 계속되어 주민들의 불편이 이어져요","correct":true},{"t":"저절로 깨끗해져요","mis":"SO4-2-u2-X04"},{"t":"아무 일도 일어나지 않아요","mis":"SO4-2-u2-X04"},{"t":"다른 동네가 해결해 줘요","mis":"SO4-2-u2-X02"}],"explanation":["그냥 두면요?","불편이 남아요.","계속 이어져요."],"asset":{"type":"passage","lines":["○○동 놀이터 옆 공터에 쓰레기를 몰래 버리는 일이 늘었다.","냄새가 나고 벌레가 꼬여 놀이터를 쓰는 주민들이 불편해졌다.","주민들은 공터를 직접 둘러보고 구청 누리집에 올라온 글도 찾아보았다."],"title":"소식지 ① — 공터 쓰레기 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#10','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C2',2,'mc','auto','칸이 가장 많은 문제가 둘일 때 해결하고 싶은 문제를 정하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u2-X08','SO4-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"mc","stem":"칸이 가장 많은 문제가 둘일 때 해결하고 싶은 문제를 정하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)","options":[{"t":"기준에 맞춰 견주고 모둠에서 토의해 정해요","correct":true},{"t":"먼저 적힌 문제로 정해요","mis":"SO4-2-u2-X08"},{"t":"칸이 가장 적은 문제로 정해요","mis":"SO4-2-u2-X06"},{"t":"제비뽑기로 정해요","mis":"SO4-2-u2-X06"}],"explanation":["횟수가 같아요.","기준으로 견줘요.","토의로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#11','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C3',2,'mc','auto','소식지 ②에서 「공터에 쓰레기통이 부족하다」는 원인을 세우려면 함께 볼 자료로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X10','SO4-2-u2-X09']::text[],false,'{"seq":11,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"mc","stem":"소식지 ②에서 「공터에 쓰레기통이 부족하다」는 원인을 세우려면 함께 볼 자료로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자료 ㉠과 ㉣","correct":true},{"t":"자료 ㉢만","mis":"SO4-2-u2-X10"},{"t":"자료 ㉡만","mis":"SO4-2-u2-X10"},{"t":"자료가 필요 없어요","mis":"SO4-2-u2-X09"}],"explanation":["쓰레기통 수가 있어요.","더러워진 공터도 있어요.","㉠과 ㉣이에요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#12','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C4',2,'mc','auto','소식지 ③에서 방안 ㉰를 「계속」으로 바꾸려면 어느 자리를 보완해야 하나요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"mc","stem":"소식지 ③에서 방안 ㉰를 「계속」으로 바꾸려면 어느 자리를 보완해야 하나요?","options":[{"t":"피해 없음","correct":true},{"t":"효과","mis":"SO4-2-u2-X14"},{"t":"비용","mis":"SO4-2-u2-X14"},{"t":"실천","mis":"SO4-2-u2-X14"}],"explanation":["㉰의 1을 찾아요.","넷째 칸이에요.","피해 없음이에요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#13','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C5',2,'mc','auto','소식지 ④에서 주민들의 실천으로 달라진 점은 무엇인가요?',ARRAY['SO4-2-u2-X16','SO4-2-u2-X19']::text[],false,'{"seq":13,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"mc","stem":"소식지 ④에서 주민들의 실천으로 달라진 점은 무엇인가요?","options":[{"t":"공터가 깨끗해지고 놀이터를 찾는 주민이 늘었어요","correct":true},{"t":"공터가 더 더러워졌어요","mis":"SO4-2-u2-X16"},{"t":"놀이터가 문을 닫았어요","mis":"SO4-2-u2-X16"},{"t":"아무것도 달라지지 않았어요","mis":"SO4-2-u2-X19"}],"explanation":["셋째 줄을 읽어요.","깨끗해졌어요.","주민이 늘었어요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#14','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C7',2,'mc','auto','소식지 ⑤의 자랑거리 넷을 보고 ○○동이 어떤 곳인지 알맞게 말한 것은 무엇인가요?',ARRAY['SO4-2-u2-X23','SO4-2-u2-X22']::text[],false,'{"seq":14,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"mc","stem":"소식지 ⑤의 자랑거리 넷을 보고 ○○동이 어떤 곳인지 알맞게 말한 것은 무엇인가요?","options":[{"t":"오래전부터 사람이 살며 옛것을 이어 오고, 과일이 나는 곳이에요","correct":true},{"t":"사람이 산 지 얼마 안 된 곳이에요","mis":"SO4-2-u2-X23"},{"t":"바다에서 고기를 잡는 곳이에요","mis":"SO4-2-u2-X23"},{"t":"자랑거리가 하나도 없는 곳이에요","mis":"SO4-2-u2-X22"}],"explanation":["느티나무와 우물터예요.","탈춤도 있어요.","복숭아가 나요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#15','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C8',2,'mc','auto','소식지 ⑥에서 축제 소식을 알리는 데 쓴 것이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":15,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"mc","stem":"소식지 ⑥에서 축제 소식을 알리는 데 쓴 것이 아닌 것은 무엇인가요?","options":[{"t":"다른 동네의 게시판","correct":true},{"t":"구청 누리집","mis":"SO4-2-u2-X24"},{"t":"사회 관계망 서비스","mis":"SO4-2-u2-X24"},{"t":"마을 소식지","mis":"SO4-2-u2-X24"}],"explanation":["셋째 줄을 읽어요.","셋이 적혀 있어요.","아닌 것을 골라요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#16','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C10',2,'mc','auto','소식지 ⑧에서 푸른반이 단원을 정리한 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":16,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"mc","stem":"소식지 ⑧에서 푸른반이 단원을 정리한 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두 활동 가운데 하나를 골라 동시를 짓거나 상품을 기획했어요","correct":true},{"t":"두 활동을 모두 꼭 했어요","mis":"SO4-2-u2-X31"},{"t":"글로만 정리했어요","mis":"SO4-2-u2-X31"},{"t":"정리를 하지 않았어요","mis":"SO4-2-u2-X31"}],"explanation":["첫째 줄을 읽어요.","하나를 골랐어요.","동시와 상품이에요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#17','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C6',3,'mc','auto','소식지 ①~④를 지역문제 해결의 차례에 맞게 늘어놓은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":17,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"소식지 ①~④를 지역문제 해결의 차례에 맞게 늘어놓은 것은 무엇인가요?","options":[{"t":"① 문제 확인 → ② 원인 → ③ 방안 → ④ 실천","correct":true},{"t":"③ 방안 → ② 원인 → ① 문제 확인 → ④ 실천","mis":"SO4-2-u2-X20"},{"t":"② 원인 → ① 문제 확인 → ④ 실천 → ③ 방안","mis":"SO4-2-u2-X20"},{"t":"④ 실천 → ③ 방안 → ② 원인 → ① 문제 확인","mis":"SO4-2-u2-X20"}],"explanation":["문제부터예요.","원인과 방안이에요.","실천이 끝이에요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#18','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C3',3,'mc','auto','소식지 ②의 자료 ㉡과 ㉢을 종합해 세울 수 있는 원인으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X10','SO4-2-u2-X11','SO4-2-u2-X09']::text[],false,'{"seq":18,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"mc","stem":"소식지 ②의 자료 ㉡과 ㉢을 종합해 세울 수 있는 원인으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"밤에 분리배출 방법을 모른 채 몰래 버리는 주민이 있어요","correct":true},{"t":"쓰레기통이 너무 많아요","mis":"SO4-2-u2-X10"},{"t":"낮에 공터를 청소하지 않아요","mis":"SO4-2-u2-X11"},{"t":"원인은 알 수 없어요","mis":"SO4-2-u2-X09"}],"explanation":["㉡은 밤이에요.","㉢은 방법을 몰라요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#19','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C5',3,'mc','auto','소식지 ④에서 쓰레기통 설치를 제안서로 부탁한 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X17','SO4-2-u2-X18','SO4-2-u2-X19']::text[],false,'{"seq":19,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"소식지 ④에서 쓰레기통 설치를 제안서로 부탁한 까닭은 무엇인가요?","options":[{"t":"설치는 주민이 직접 시작할 수 없어 공공 기관의 협조가 필요하기 때문이에요","correct":true},{"t":"주민이 하기 싫었기 때문이에요","mis":"SO4-2-u2-X17"},{"t":"제안서는 아무 때나 쓰기 때문이에요","mis":"SO4-2-u2-X18"},{"t":"공공 기관이 혼자 다 하기 때문이에요","mis":"SO4-2-u2-X19"}],"explanation":["설치는 누가 하나요?","공공 기관이에요.","협조를 구해요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#20','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C8',3,'mc','auto','소식지 ⑥에 나온 알리는 방법을 모두 고른 것은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"소식지 ⑥에 나온 알리는 방법을 모두 고른 것은 무엇인가요?","options":[{"t":"축제 · 직거래 장터 · 체험 프로그램","correct":true},{"t":"박람회 · 전시회","mis":"SO4-2-u2-X26"},{"t":"관광 상품 개발 하나","mis":"SO4-2-u2-X26"},{"t":"직거래 장터 하나","mis":"SO4-2-u2-X26"}],"explanation":["여름을 봐요.","가을도 봐요.","셋이에요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#21','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C9',3,'mc','auto','소식지 ⑦의 안내도로 소개하면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X28']::text[],false,'{"seq":21,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"mc","stem":"소식지 ⑦의 안내도로 소개하면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"○○동 자랑거리가 어디에 있는지와 특징을 한눈에 볼 수 있어요","correct":true},{"t":"이야기처럼 장면을 나누어 볼 수 있어요","mis":"SO4-2-u2-X28"},{"t":"자랑거리를 감출 수 있어요","mis":"SO4-2-u2-X28"},{"t":"그림 없이 글만 쓸 수 있어요","mis":"SO4-2-u2-X28"}],"explanation":["백지도를 썼어요.","선으로 이었어요.","위치가 보여요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#22','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C10',3,'mc','auto','소식지 ⑧에서 느티나무 책갈피 상품을 기획한 모둠이 「정한 까닭」에 쓸 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X31','SO4-2-u2-X30']::text[],false,'{"seq":22,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"소식지 ⑧에서 느티나무 책갈피 상품을 기획한 모둠이 「정한 까닭」에 쓸 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"수백 년 동안 동네를 지켜 온 나무라 ○○동을 잘 보여 주기 때문이에요","correct":true},{"t":"책갈피가 가장 싸기 때문이에요","mis":"SO4-2-u2-X31"},{"t":"다른 동네에도 똑같은 나무가 많기 때문이에요","mis":"SO4-2-u2-X30"},{"t":"느티나무가 지역문제이기 때문이에요","mis":"SO4-2-u2-X30"}],"explanation":["왜 골랐을까요?","오래된 나무예요.","○○동을 보여 줘요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#23','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C6',4,'mc','auto','소식지 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X20','SO4-2-u2-X19','SO4-2-u2-X04']::text[],false,'{"seq":23,"concept":"SO4-2-u2-C6","difficulty":4,"kind":"mc","stem":"소식지 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문제를 확인하고 자료로 원인을 찾아 방안을 정한 뒤, 주민과 공공 기관이 함께 실천하면 지역이 나아져요","correct":true},{"t":"방안을 먼저 정하고 원인은 나중에 찾아요","mis":"SO4-2-u2-X20"},{"t":"공공 기관이 혼자 하면 돼요","mis":"SO4-2-u2-X19"},{"t":"지역문제는 그냥 두면 사라져요","mis":"SO4-2-u2-X04"}],"explanation":["①은 확인이에요.","②③은 원인과 방안이에요.","④는 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#24','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C3',4,'essay','teacher','소식지 ②의 자료 넷 가운데 둘을 골라 겹쳐 보고, 공터 쓰레기 문제의 원인을 하나 쓰세요. 왜 자료를 겹쳐 보아야 하는지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u2-C3","difficulty":4,"kind":"essay","stem":"소식지 ②의 자료 넷 가운데 둘을 골라 겹쳐 보고, 공터 쓰레기 문제의 원인을 하나 쓰세요. 왜 자료를 겹쳐 보아야 하는지도 쓰세요.","answer_guide":{"answer":"예: 자료 ㉡ 그래프와 ㉢ 설문 조사를 겹쳐 보면, 분리배출 방법을 잘 모르는 주민이 밤에 몰래 쓰레기를 버리는 것이 원인이라고 볼 수 있어요. 자료 한 장만으로는 까닭을 확실히 알기 어렵고, 여러 자료의 정보를 종합해야 원인이 보이기 때문이에요.","scoring_points":["자료 둘을 골랐는가","두 자료와 이어진 원인을 썼는가","겹쳐 보는 까닭을 썼는가"]},"explanation":["자료를 골라요.","원인을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_a#25','soc',4,2,'u2','','g4_2_soc_u2_review_a','unit_review','SO4-2-u2-C5',4,'essay','teacher','소식지 ④처럼 우리 동네의 지역문제를 하나 골라, 주민이 할 일과 공공 기관에 부탁할 일을 나누어 쓰고 제안서의 「주요 제안 내용」을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u2-C5","difficulty":4,"kind":"essay","stem":"소식지 ④처럼 우리 동네의 지역문제를 하나 골라, 주민이 할 일과 공공 기관에 부탁할 일을 나누어 쓰고 제안서의 「주요 제안 내용」을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 학교 앞 횡단보도에 신호등이 없어 위험해요. 주민은 등하교 시간에 안전 지킴이 활동을 하고, 신호등 설치는 공공 기관에 부탁할 거예요. 주요 제안 내용은 「학교 앞 횡단보도에 신호등을 설치해 주세요」예요.","scoring_points":["지역문제를 골랐는가","주민 몫과 공공 기관 몫을 나누었는가","제안 내용을 구체적으로 썼는가"]},"explanation":["문제를 골라요.","두 몫을 나눠요.","제안 내용을 써요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#1','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C1',1,'sa','auto','지역 주민의 생활을 불편하게 하거나 주민들 사이에 갈등을 일으키는 문제를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"sa","stem":"지역 주민의 생활을 불편하게 하거나 주민들 사이에 갈등을 일으키는 문제를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["지역문제","지역 문제"],"explanation":["지역에서 생겨요.","지역◯◯예요.","지역문제예요."],"mis":"SO4-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#2','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C2',1,'sa','auto','지역 주민을 만나 이야기를 나누며 지역의 문제를 알아보는 방법은 무엇인가요? 두 글자로 쓰세요. (단원 정리)','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"sa","stem":"지역 주민을 만나 이야기를 나누며 지역의 문제를 알아보는 방법은 무엇인가요? 두 글자로 쓰세요. (단원 정리)","answer":["면담"],"explanation":["만나서 들어요.","면◯이에요.","면담이에요."],"mis":"SO4-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#3','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C3',1,'sa','auto','소식지 ②에서 쓰레기가 주로 버려지는 때는 언제인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"sa","stem":"소식지 ②에서 쓰레기가 주로 버려지는 때는 언제인가요? 한 글자로 쓰세요.","answer":["밤"],"explanation":["㉡ 그래프를 봐요.","어두울 때예요.","밤이에요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"},"mis":"SO4-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#4','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C4',1,'sa','auto','해결 방안을 평가하는 기준 가운데 「돈이 적게 드나요?」를 묻는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"sa","stem":"해결 방안을 평가하는 기준 가운데 「돈이 적게 드나요?」를 묻는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["비용"],"explanation":["돈이 드는 정도예요.","비◯이에요.","비용이에요."],"mis":"SO4-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#5','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C5',1,'sa','auto','소식지 ④에서 주민들이 구청에 협조를 구하려고 보낸 글은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"sa","stem":"소식지 ④에서 주민들이 구청에 협조를 구하려고 보낸 글은 무엇인가요? 세 글자로 쓰세요.","answer":["제안서"],"explanation":["둘째 줄이에요.","제안◯예요.","제안서예요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"},"mis":"SO4-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#6','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C7',1,'sa','auto','소식지 ⑤의 ㉰ 마을 탈춤은 자연환경·역사·문화·생산물 가운데 어느 갈래인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"sa","stem":"소식지 ⑤의 ㉰ 마을 탈춤은 자연환경·역사·문화·생산물 가운데 어느 갈래인가요? 두 글자로 쓰세요.","answer":["문화"],"explanation":["공연이에요.","사람들이 이어 와요.","문화예요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"},"mis":"SO4-2-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#7','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C8',1,'sa','auto','소식지 ⑥에서 여름에 복숭아를 알리려고 여는 행사는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"sa","stem":"소식지 ⑥에서 여름에 복숭아를 알리려고 여는 행사는 무엇인가요? 두 글자로 쓰세요.","answer":["축제"],"explanation":["첫째 줄이에요.","복숭아 ◯◯예요.","축제예요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"},"mis":"SO4-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#8','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C9',1,'sa','auto','소식지 ⑦에서 푸른반 모둠이 있는 곳을 색칠한 지도는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"sa","stem":"소식지 ⑦에서 푸른반 모둠이 있는 곳을 색칠한 지도는 무엇인가요? 세 글자로 쓰세요.","answer":["백지도"],"explanation":["둘째 줄이에요.","백◯◯예요.","백지도예요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"},"mis":"SO4-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#9','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C1',2,'ox','auto','지역문제는 어느 지역에서나 똑같이 나타나요.',ARRAY['SO4-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"ox","stem":"지역문제는 어느 지역에서나 똑같이 나타나요.","answer":"X","reason_options":[{"t":"지역의 상황에 따라 다르게 나타나기 때문에","correct":true},{"t":"모든 지역은 상황이 같기 때문에","mis":"SO4-2-u2-X03"}],"mis":"SO4-2-u2-X03","explanation":["지역마다 같을까요?","상황이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#10','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C2',2,'ox','auto','사람마다 해결하고 싶은 지역문제가 다를 수 있어요.',ARRAY['SO4-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"ox","stem":"사람마다 해결하고 싶은 지역문제가 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 생각과 경험이 다르기 때문에","correct":true},{"t":"지역문제는 한 가지뿐이기 때문에","mis":"SO4-2-u2-X07"}],"mis":"SO4-2-u2-X07","explanation":["친구마다 겪은 일이 같나요?","서로 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#11','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C3',2,'ox','auto','자료 한 장만 보아도 지역문제의 원인을 확실히 알 수 있어요.',ARRAY['SO4-2-u2-X10']::text[],false,'{"seq":11,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"ox","stem":"자료 한 장만 보아도 지역문제의 원인을 확실히 알 수 있어요.","answer":"X","reason_options":[{"t":"여러 자료에서 찾은 정보를 종합해야 원인이 보이기 때문에","correct":true},{"t":"자료는 한 장이 가장 정확하기 때문에","mis":"SO4-2-u2-X10"}],"mis":"SO4-2-u2-X10","explanation":["한 장이면 될까요?","겹쳐 봐야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#12','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C4',2,'ox','auto','소식지 ③에서 방안 ㉮는 실천 자리를 보완하면 쓸 수 있어요.',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"ox","stem":"소식지 ③에서 방안 ㉮는 실천 자리를 보완하면 쓸 수 있어요.","answer":"O","reason_options":[{"t":"1점인 자리가 실천 하나뿐이기 때문에","correct":true},{"t":"㉮는 고칠 수 없는 방안이기 때문에","mis":"SO4-2-u2-X14"}],"mis":"SO4-2-u2-X14","explanation":["㉮의 1은 몇 개죠?","실천 하나예요.","그래서 O예요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#13','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C5',2,'ox','auto','소식지 ④에서 공터가 깨끗해진 것은 주민과 구청이 힘을 모은 결과예요.',ARRAY['SO4-2-u2-X19']::text[],false,'{"seq":13,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"ox","stem":"소식지 ④에서 공터가 깨끗해진 것은 주민과 구청이 힘을 모은 결과예요.","answer":"O","reason_options":[{"t":"주민은 캠페인을, 구청은 설치와 단속을 함께 했기 때문에","correct":true},{"t":"구청 혼자 모두 했기 때문에","mis":"SO4-2-u2-X19"}],"mis":"SO4-2-u2-X19","explanation":["주민이 한 일이 있어요.","구청도 했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#14','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C7',2,'ox','auto','자랑거리를 살펴보는 것은 자랑거리 이름을 외우기 위해서예요.',ARRAY['SO4-2-u2-X23']::text[],false,'{"seq":14,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"ox","stem":"자랑거리를 살펴보는 것은 자랑거리 이름을 외우기 위해서예요.","answer":"X","reason_options":[{"t":"그 지역의 독특한 점과 특징을 알기 위해서이기 때문에","correct":true},{"t":"이름만 알면 지역을 다 알기 때문에","mis":"SO4-2-u2-X23"}],"mis":"SO4-2-u2-X23","explanation":["이름을 외울까요?","특징을 알아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#15','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C8',2,'ox','auto','축제는 생산물뿐 아니라 자연환경·역사·문화를 알리는 데도 쓰여요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":15,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"ox","stem":"축제는 생산물뿐 아니라 자연환경·역사·문화를 알리는 데도 쓰여요.","answer":"O","reason_options":[{"t":"네 갈래 모두 축제를 열어 자랑거리를 알리기 때문에","correct":true},{"t":"축제는 생산물만 알리기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["머드 축제가 있었어요.","민속 축제도 있었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#16','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C10',2,'ox','auto','지역마다 자연환경과 역사가 달라도 생산물은 모두 같아요.',ARRAY['SO4-2-u2-X30']::text[],false,'{"seq":16,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"ox","stem":"지역마다 자연환경과 역사가 달라도 생산물은 모두 같아요.","answer":"X","reason_options":[{"t":"지역마다 땅과 날씨가 달라 나는 것도 다르기 때문에","correct":true},{"t":"생산물은 어디서나 같기 때문에","mis":"SO4-2-u2-X30"}],"mis":"SO4-2-u2-X30","explanation":["나는 것이 같을까요?","지역마다 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#17','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C6',3,'ox','auto','해결 방안을 정한 뒤에 원인을 알아보는 것이 알맞은 차례예요.',ARRAY['SO4-2-u2-X20']::text[],false,'{"seq":17,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"ox","stem":"해결 방안을 정한 뒤에 원인을 알아보는 것이 알맞은 차례예요.","answer":"X","reason_options":[{"t":"원인을 알아야 그 원인에 맞는 해결 방안을 정할 수 있기 때문에","correct":true},{"t":"원인은 방안과 관계없기 때문에","mis":"SO4-2-u2-X20"}],"mis":"SO4-2-u2-X20","explanation":["무엇이 먼저일까요?","원인이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#18','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C4',3,'ox','auto','소식지 ③의 방안 ㉯는 자료 ㉢에서 찾은 원인과 이어진 해결 방안이에요.',ARRAY['SO4-2-u2-X12']::text[],false,'{"seq":18,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"ox","stem":"소식지 ③의 방안 ㉯는 자료 ㉢에서 찾은 원인과 이어진 해결 방안이에요.","answer":"O","reason_options":[{"t":"분리배출 방법을 모르는 주민에게 방법을 알려 주기 때문에","correct":true},{"t":"안내문은 원인과 관계없기 때문에","mis":"SO4-2-u2-X12"}],"mis":"SO4-2-u2-X12","explanation":["㉢은 방법을 몰라요.","㉯는 안내문이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#19','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C5',3,'ox','auto','제안서의 「제안한 까닭」에는 공터가 왜 문제인지 실태를 분명하게 써야 해요.',ARRAY['SO4-2-u2-X18']::text[],false,'{"seq":19,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"ox","stem":"제안서의 「제안한 까닭」에는 공터가 왜 문제인지 실태를 분명하게 써야 해요.","answer":"O","reason_options":[{"t":"받는 곳이 무엇을 왜 해야 하는지 알 수 있기 때문에","correct":true},{"t":"까닭은 짧을수록 좋기 때문에","mis":"SO4-2-u2-X18"}],"mis":"SO4-2-u2-X18","explanation":["까닭 칸이에요.","실태를 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#20','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C8',3,'ox','auto','소식지 ⑥의 탈 만들기 체험은 문화와 관련 있는 자랑거리를 알리는 노력이에요.',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"ox","stem":"소식지 ⑥의 탈 만들기 체험은 문화와 관련 있는 자랑거리를 알리는 노력이에요.","answer":"O","reason_options":[{"t":"마을 탈춤이라는 문화를 직접 해 보며 알게 하기 때문에","correct":true},{"t":"체험은 생산물만 알리기 때문에","mis":"SO4-2-u2-X26"}],"mis":"SO4-2-u2-X26","explanation":["탈춤은 문화예요.","탈을 만들어요.","그래서 O예요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#21','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C9',3,'ox','auto','소식지 ⑦의 푸른반 모둠은 안내도를 만드는 걸음을 차례대로 밟았어요.',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":21,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"ox","stem":"소식지 ⑦의 푸른반 모둠은 안내도를 만드는 걸음을 차례대로 밟았어요.","answer":"O","reason_options":[{"t":"정리 → 색칠 → 자료 붙이기 → 선으로 잇기 차례로 했기 때문에","correct":true},{"t":"선부터 이었기 때문에","mis":"SO4-2-u2-X27"}],"mis":"SO4-2-u2-X27","explanation":["둘째·셋째 줄을 읽어요.","차례가 맞아요.","그래서 O예요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#22','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C10',3,'ox','auto','소식지 ⑧에서 동시를 지은 모둠은 상품 기획을 하지 않았어도 정리를 마쳤어요.',ARRAY['SO4-2-u2-X31']::text[],false,'{"seq":22,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"ox","stem":"소식지 ⑧에서 동시를 지은 모둠은 상품 기획을 하지 않았어도 정리를 마쳤어요.","answer":"O","reason_options":[{"t":"두 활동 가운데 하나를 골라 하는 정리이기 때문에","correct":true},{"t":"두 활동을 모두 해야 끝나기 때문에","mis":"SO4-2-u2-X31"}],"mis":"SO4-2-u2-X31","explanation":["첫째 줄을 읽어요.","하나를 골랐어요.","그래서 O예요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#23','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C8',4,'mc','auto','소식지 ⑤~⑦을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X26','SO4-2-u2-X23','SO4-2-u2-X25']::text[],false,'{"seq":23,"concept":"SO4-2-u2-C8","difficulty":4,"kind":"mc","stem":"소식지 ⑤~⑦을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"네 갈래 자랑거리를 축제·장터·체험·안내도처럼 여러 방법으로 알리면 ○○동을 널리 알릴 수 있어요","correct":true},{"t":"자랑거리는 한 가지 방법으로만 알려요","mis":"SO4-2-u2-X26"},{"t":"자랑거리는 이름만 외우면 돼요","mis":"SO4-2-u2-X23"},{"t":"알리면 동네에 오는 사람이 줄어요","mis":"SO4-2-u2-X25"}],"explanation":["⑤는 자랑거리예요.","⑥은 알리는 노력이에요.","⑦은 소개 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#24','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C4',4,'essay','teacher','소식지 ③에서 방안 ㉮를 골라 부족한 자리를 찾고 보완하는 방법을 쓰세요. 그리고 ㉯를 바로 고르지 않고 ㉮도 보완해 보는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u2-C4","difficulty":4,"kind":"essay","stem":"소식지 ③에서 방안 ㉮를 골라 부족한 자리를 찾고 보완하는 방법을 쓰세요. 그리고 ㉯를 바로 고르지 않고 ㉮도 보완해 보는 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮ 쓰레기통 놓기는 실천이 1점이에요. 쓰레기통은 주민이 직접 놓기 어려우니 구청에 협조를 구하는 제안서를 쓰면 보완할 수 있어요. 부족한 방안도 버리지 않고 보완하면 여러 방안을 함께 써서 문제를 더 잘 해결할 수 있기 때문이에요.","scoring_points":["부족한 자리를 바르게 찾았는가","보완 방법을 썼는가","보완해 보는 까닭을 썼는가"]},"explanation":["㉮의 1을 찾아요.","보완해요.","까닭을 써요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_b#25','soc',4,2,'u2','','g4_2_soc_u2_review_b','unit_review','SO4-2-u2-C8',4,'essay','teacher','소식지 ⑤의 ㉯ 우물터를 알리는 노력을 두 가지 계획하고, 그렇게 알리면 ○○동에 어떤 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u2-C8","difficulty":4,"kind":"essay","stem":"소식지 ⑤의 ㉯ 우물터를 알리는 노력을 두 가지 계획하고, 그렇게 알리면 ○○동에 어떤 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 우물터의 옛이야기를 모은 전시회를 열고, 옛날처럼 물을 길어 보는 체험 프로그램을 운영할 거예요. 그러면 많은 사람이 ○○동을 찾아와 동네를 알게 되고, 동네 경제에도 도움이 되어 ○○동이 발전할 수 있어요.","scoring_points":["알리는 방법 두 가지를 썼는가","역사 갈래에 알맞은 방법인가","동네에 도움이 되는 점을 썼는가"]},"explanation":["방법을 정해요.","둘이에요.","도움을 써요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#1','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C1',1,'ox','auto','지역문제는 지역 주민들이 함께 해결해야 해요.',ARRAY['SO4-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"ox","stem":"지역문제는 지역 주민들이 함께 해결해야 해요.","answer":"O","reason_options":[{"t":"여러 주민과 관련된 공동의 문제이기 때문에","correct":true},{"t":"한 사람이 해결하는 문제이기 때문에","mis":"SO4-2-u2-X02"}],"mis":"SO4-2-u2-X02","explanation":["누구의 문제인가요?","여럿의 문제예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#2','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C2',1,'ox','auto','해결하고 싶은 지역문제는 모둠에서 토의하여 정해요.',ARRAY['SO4-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"ox","stem":"해결하고 싶은 지역문제는 모둠에서 토의하여 정해요.","answer":"O","reason_options":[{"t":"서로의 생각을 나누며 의견의 차이를 좁힐 수 있기 때문에","correct":true},{"t":"가위바위보로 정해야 공평하기 때문에","mis":"SO4-2-u2-X06"}],"mis":"SO4-2-u2-X06","explanation":["어떻게 정했나요?","토의예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#3','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C3',1,'ox','auto','지역문제의 원인을 알려면 관련 있는 다양한 자료가 필요해요.',ARRAY['SO4-2-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"ox","stem":"지역문제의 원인을 알려면 관련 있는 다양한 자료가 필요해요.","answer":"O","reason_options":[{"t":"사실을 확인할 수 있는 자료를 종합해야 원인이 보이기 때문에","correct":true},{"t":"원인은 느낌만으로 알 수 있기 때문에","mis":"SO4-2-u2-X09"}],"mis":"SO4-2-u2-X09","explanation":["무엇이 필요할까요?","다양한 자료예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#4','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C4',1,'ox','auto','부족한 점수를 받은 해결 방안은 곧바로 버려야 해요.',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"ox","stem":"부족한 점수를 받은 해결 방안은 곧바로 버려야 해요.","answer":"X","reason_options":[{"t":"부족한 부분을 보완하여 고쳐 쓸 수 있기 때문에","correct":true},{"t":"한 번 낮으면 고칠 수 없기 때문에","mis":"SO4-2-u2-X14"}],"mis":"SO4-2-u2-X14","explanation":["버릴까요?","보완해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#5','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C5',1,'ox','auto','쓰레기 무단 투기 단속은 공공 기관의 협조가 필요한 일이에요.',ARRAY['SO4-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"ox","stem":"쓰레기 무단 투기 단속은 공공 기관의 협조가 필요한 일이에요.","answer":"O","reason_options":[{"t":"주민이 직접 단속을 시작할 수는 없기 때문에","correct":true},{"t":"단속은 누구나 혼자 할 수 있기 때문에","mis":"SO4-2-u2-X17"}],"mis":"SO4-2-u2-X17","explanation":["단속은 누가 하나요?","공공 기관이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#6','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C7',1,'ox','auto','소식지 ⑤의 ㉯ 우물터는 역사와 관련 있는 자랑거리예요.',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"ox","stem":"소식지 ⑤의 ㉯ 우물터는 역사와 관련 있는 자랑거리예요.","answer":"O","reason_options":[{"t":"옛사람들이 물을 길어 쓰던 자취이기 때문에","correct":true},{"t":"오늘 새로 만든 것이기 때문에","mis":"SO4-2-u2-X22"}],"mis":"SO4-2-u2-X22","explanation":["옛사람이 썼어요.","옛 자취예요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#7','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C8',1,'ox','auto','지역이 자랑거리를 알리면 지역을 발전시킬 수 있어요.',ARRAY['SO4-2-u2-X25']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"ox","stem":"지역이 자랑거리를 알리면 지역을 발전시킬 수 있어요.","answer":"O","reason_options":[{"t":"관광객이 찾아와 지역 경제에 도움이 되기 때문에","correct":true},{"t":"알리면 사람들이 오지 않기 때문에","mis":"SO4-2-u2-X25"}],"mis":"SO4-2-u2-X25","explanation":["알리면 누가 오나요?","관광객이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#8','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C9',1,'ox','auto','소식지 ⑦에서 푸른반 모둠은 소개할 자랑거리를 먼저 정리했어요.',ARRAY['SO4-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"ox","stem":"소식지 ⑦에서 푸른반 모둠은 소개할 자랑거리를 먼저 정리했어요.","answer":"O","reason_options":[{"t":"어떤 방법이든 꾸밀 자랑거리를 먼저 정리하기 때문에","correct":true},{"t":"안내도는 자료부터 붙이기 때문에","mis":"SO4-2-u2-X27"}],"mis":"SO4-2-u2-X27","explanation":["둘째 줄을 읽어요.","먼저 정리했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#9','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C1',2,'mc','auto','개인의 일이 지역문제로 커지는 경우로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X01']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"mc","stem":"개인의 일이 지역문제로 커지는 경우로 알맞은 것은 무엇인가요?","options":[{"t":"독감에 걸린 주민이 예방 수칙을 지키지 않아 이웃에게 옮을 때","correct":true},{"t":"혼자 방 청소를 할 때","mis":"SO4-2-u2-X01"},{"t":"집에서 책을 읽을 때","mis":"SO4-2-u2-X01"},{"t":"가족과 저녁을 먹을 때","mis":"SO4-2-u2-X01"}],"explanation":["이웃에게 번져요.","여러 집에 닿아요.","지역문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#10','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C2',2,'match','auto','우리 지역의 문제를 확인하는 방법과 하는 일을 알맞게 이으세요. (단원 정리)','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"match","stem":"우리 지역의 문제를 확인하는 방법과 하는 일을 알맞게 이으세요. (단원 정리)","pairs":[{"l":"둘러보기","r":"동네를 걸으며 살펴요"},{"l":"누리집","r":"주민이 올린 글을 읽어요"},{"l":"면담","r":"주민의 이야기를 들어요"}],"mis":"SO4-2-u2-X05","explanation":["걸어요.","읽어요.","들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#11','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C3',2,'mc','auto','원인을 찾는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X09','SO4-2-u2-X10','SO4-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"mc","stem":"원인을 찾는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"자료 모으기 → 정보 찾기 → 뜻 해석하기 → 종합해 원인 파악하기","correct":true},{"t":"원인 정하기 → 맞는 자료만 모으기","mis":"SO4-2-u2-X09"},{"t":"자료 한 장 보기 → 원인 정하기","mis":"SO4-2-u2-X10"},{"t":"정보 찾기 → 자료 모으기 → 원인 정하기","mis":"SO4-2-u2-X11"}],"explanation":["자료가 먼저예요.","정보와 뜻이에요.","종합해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#12','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C4',2,'mc','auto','해결 방안의 장단점을 비교하고 의견을 조정하는 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X13','SO4-2-u2-X15','SO4-2-u2-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"mc","stem":"해결 방안의 장단점을 비교하고 의견을 조정하는 까닭은 무엇인가요?","options":[{"t":"더 합리적인 해결 방안을 찾으려고","correct":true},{"t":"빨리 끝내려고","mis":"SO4-2-u2-X13"},{"t":"한 사람의 뜻대로 하려고","mis":"SO4-2-u2-X15"},{"t":"방안의 수를 줄이려고","mis":"SO4-2-u2-X14"}],"explanation":["견주어요.","더 나은 것이 보여요.","합리적인 방안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#13','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C5',2,'match','auto','소식지 ④의 주민들이 구청에 보낸 제안서를 떠올려 칸과 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"match","stem":"소식지 ④의 주민들이 구청에 보낸 제안서를 떠올려 칸과 내용을 알맞게 이으세요.","pairs":[{"l":"제목","r":"공터 쓰레기통 설치를 제안합니다"},{"l":"보낼 곳","r":"○○구청"},{"l":"제안한 까닭","r":"공터에 쓰레기통이 없어 몰래 버려요"},{"l":"주요 제안 내용","r":"공터에 쓰레기통을 놓아 주세요"}],"mis":"SO4-2-u2-X18","explanation":["제목이 맨 앞이에요.","보낼 곳은 구청이에요.","까닭과 내용을 이어요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#14','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C7',2,'match','auto','소식지 ⑤의 자랑거리와 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"match","stem":"소식지 ⑤의 자랑거리와 갈래를 알맞게 이으세요.","pairs":[{"l":"㉮ 느티나무","r":"자연환경"},{"l":"㉯ 우물터","r":"역사"},{"l":"㉰ 탈춤","r":"문화"},{"l":"㉱ 복숭아","r":"생산물"}],"mis":"SO4-2-u2-X22","explanation":["나무는 자연이에요.","우물터는 옛 자취예요.","탈춤과 복숭아도 이어요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#15','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C8',2,'match','auto','알리는 방법과 주로 알리는 갈래를 알맞게 이으세요. (단원 정리)','{}'::text[],false,'{"seq":15,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"match","stem":"알리는 방법과 주로 알리는 갈래를 알맞게 이으세요. (단원 정리)","pairs":[{"l":"관광 상품 개발","r":"자연환경"},{"l":"전시회","r":"역사"},{"l":"민속놀이·체육 행사","r":"문화"},{"l":"박람회","r":"생산물"}],"mis":"SO4-2-u2-X26","explanation":["갯벌 상품이에요.","역사를 펼쳐요.","민속놀이와 박람회도 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#16','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C10',2,'mc','auto','소식지 ⑧에서 동시에 넣은 것은 어느 갈래의 자랑거리인가요?',ARRAY['SO4-2-u2-X30']::text[],false,'{"seq":16,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"mc","stem":"소식지 ⑧에서 동시에 넣은 것은 어느 갈래의 자랑거리인가요?","options":[{"t":"생산물","correct":true},{"t":"역사","mis":"SO4-2-u2-X30"},{"t":"문화","mis":"SO4-2-u2-X30"},{"t":"지역문제","mis":"SO4-2-u2-X30"}],"explanation":["복숭아·쌀·배추예요.","그곳에서 나요.","생산물이에요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#17','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C6',3,'error','auto','지역문제 해결 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u2-X19','SO4-2-u2-X20','SO4-2-u2-X15']::text[],false,'{"seq":17,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"error","stem":"지역문제 해결 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 나 — 「실천은 공공 기관만 하면 돼.」","correct":true,"mis_target":"SO4-2-u2-X19"},{"t":"친구 가 — 「문제를 확인하고 원인을 찾아.」","mis":"SO4-2-u2-X20"},{"t":"친구 다 — 「방안은 대화와 타협으로 정해.」","mis":"SO4-2-u2-X15"}],"explanation":["실천은 누가 하나요?","함께해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#18','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C4',3,'mc','auto','소식지 ③에서 방안 ㉰의 「피해 없음」이 1점인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X13']::text[],false,'{"seq":18,"concept":"SO4-2-u2-C4","difficulty":3,"kind":"mc","stem":"소식지 ③에서 방안 ㉰의 「피해 없음」이 1점인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"밤마다 지키는 주민이 쉬지 못해 힘들어질 수 있기 때문이에요","correct":true},{"t":"비용이 많이 들기 때문이에요","mis":"SO4-2-u2-X13"},{"t":"효과가 전혀 없기 때문이에요","mis":"SO4-2-u2-X13"},{"t":"누가 먼저 말했는지 모르기 때문이에요","mis":"SO4-2-u2-X13"}],"explanation":["밤마다 지켜요.","누가 힘들까요?","지키는 주민이에요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#19','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C5',3,'error','auto','소식지 ④를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X16','SO4-2-u2-X17']::text[],false,'{"seq":19,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"error","stem":"소식지 ④를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「제안서를 보냈으니 우리는 캠페인을 안 해도 돼.」","correct":true,"mis_target":"SO4-2-u2-X16"},{"t":"친구 가 — 「안내문과 캠페인은 우리가 했어.」","mis":"SO4-2-u2-X17"},{"t":"친구 나 — 「설치는 구청에 부탁했어.」","mis":"SO4-2-u2-X17"}],"explanation":["보내면 끝일까요?","우리 몫도 있어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#20','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C8',3,'error','auto','소식지 ⑥을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X25','SO4-2-u2-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"error","stem":"소식지 ⑥을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「축제를 알리면 동네에 오는 사람이 줄어서 좋아.」","correct":true,"mis_target":"SO4-2-u2-X25"},{"t":"친구 가 — 「직거래 장터로 복숭아를 알려.」","mis":"SO4-2-u2-X26"},{"t":"친구 다 — 「알리면 동네가 발전할 수 있어.」","mis":"SO4-2-u2-X25"}],"explanation":["알리면 어떻게 되나요?","사람이 늘어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#21','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C9',3,'error','auto','소개 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u2-X28']::text[],false,'{"seq":21,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"error","stem":"소개 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 가 — 「만화는 백지도에 색칠하고 선으로 이어.」","correct":true,"mis_target":"SO4-2-u2-X28"},{"t":"친구 나 — 「포스터는 설명 문구를 써.」","mis":"SO4-2-u2-X28"},{"t":"친구 다 — 「안내도는 위치를 한눈에 보여 줘.」","mis":"SO4-2-u2-X28"}],"explanation":["만화는 무엇을 나누나요?","장면이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#22','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C10',3,'error','auto','주제②를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u2-X30','SO4-2-u2-X26']::text[],false,'{"seq":22,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"error","stem":"주제②를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 다 — 「자랑거리를 보면 지역문제를 알 수 있어.」","correct":true,"mis_target":"SO4-2-u2-X30"},{"t":"친구 가 — 「지역마다 생산물이 달라.」","mis":"SO4-2-u2-X30"},{"t":"친구 나 — 「축제와 전시회로 역사를 알려.」","mis":"SO4-2-u2-X26"}],"explanation":["자랑거리로 무엇을 알까요?","지역의 특징이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#23','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C3',4,'mc','auto','소식지 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X12','SO4-2-u2-X14','SO4-2-u2-X10']::text[],false,'{"seq":23,"concept":"SO4-2-u2-C3","difficulty":4,"kind":"mc","stem":"소식지 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자료로 찾은 원인에 맞추어 해결 방안을 세우고 기준으로 견주어 보완해요","correct":true},{"t":"원인과 방안은 관계없어요","mis":"SO4-2-u2-X12"},{"t":"점수가 낮은 방안은 바로 버려요","mis":"SO4-2-u2-X14"},{"t":"자료는 한 장만 보면 돼요","mis":"SO4-2-u2-X10"}],"explanation":["②는 원인이에요.","③은 방안이에요.","이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#24','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C7',4,'essay','teacher','소식지 ⑤의 자랑거리 넷을 보고 ○○동이 어떤 곳인지 두 문장으로 쓰세요. 그리고 그렇게 쓴 까닭을 자랑거리와 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u2-C7","difficulty":4,"kind":"essay","stem":"소식지 ⑤의 자랑거리 넷을 보고 ○○동이 어떤 곳인지 두 문장으로 쓰세요. 그리고 그렇게 쓴 까닭을 자랑거리와 이어 쓰세요.","answer_guide":{"answer":"예: ○○동은 오래전부터 사람들이 모여 살아온 곳이에요. 또 옛것을 이어 가며 맛있는 과일이 나는 곳이에요. 수백 년 된 느티나무와 옛 우물터가 있고, 해마다 탈춤을 공연하며 언덕 과수원에서 복숭아를 거두기 때문이에요.","scoring_points":["어떤 곳인지 두 문장으로 썼는가","자랑거리와 이었는가","갈래를 고루 살폈는가"]},"explanation":["넷을 읽어요.","어떤 곳일까요?","까닭과 이어요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_c#25','soc',4,2,'u2','','g4_2_soc_u2_review_c','unit_review','SO4-2-u2-C1',4,'essay','teacher','이 단원에서 배운 주제① 「지역문제의 해결」과 주제② 「지역을 알리는 노력」이 어떻게 이어지는지, 더 살기 좋은 지역과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u2-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 주제① 「지역문제의 해결」과 주제② 「지역을 알리는 노력」이 어떻게 이어지는지, 더 살기 좋은 지역과 이어 쓰세요.","answer_guide":{"answer":"예: 주제①에서는 주민들이 함께 지역문제를 해결해 불편을 줄였고, 주제②에서는 지역의 자랑거리를 알려 지역을 발전시켰어요. 두 주제 모두 주민이 지역에 관심을 갖고 참여하는 일이고, 그렇게 하면 우리 지역이 더 살기 좋은 곳이 돼요.","scoring_points":["주제①을 썼는가","주제②를 썼는가","두 주제를 살기 좋은 지역과 이었는가"]},"explanation":["주제①을 떠올려요.","주제②를 떠올려요.","이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#1','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C1',1,'blank','auto','층간 소음은 이웃 주민들 사이에 (    )을 일으키는 지역문제예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X01','SO4-2-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u2-C1","difficulty":1,"kind":"blank","stem":"층간 소음은 이웃 주민들 사이에 (    )을 일으키는 지역문제예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"갈등","correct":true},{"t":"웃음","mis":"SO4-2-u2-X01"},{"t":"축제","mis":"SO4-2-u2-X22"},{"t":"자랑","mis":"SO4-2-u2-X22"}],"explanation":["서로 다퉈요.","갈◯이에요.","갈등이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#2','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C2',1,'mc','auto','해결하고 싶은 문제를 정하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X08']::text[],false,'{"seq":2,"concept":"SO4-2-u2-C2","difficulty":1,"kind":"mc","stem":"해결하고 싶은 문제를 정하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"얼마나 많은 사람이 해결을 바라는가","correct":true},{"t":"누가 가장 먼저 말했는가","mis":"SO4-2-u2-X08"},{"t":"문제 이름이 얼마나 짧은가","mis":"SO4-2-u2-X08"},{"t":"목소리가 얼마나 큰가","mis":"SO4-2-u2-X08"}],"explanation":["기준 셋을 떠올려요.","많은 사람이 있어요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#3','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C3',1,'mc','auto','소식지 ②의 자료 ㉢은 무엇을 알려 주나요?',ARRAY['SO4-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u2-C3","difficulty":1,"kind":"mc","stem":"소식지 ②의 자료 ㉢은 무엇을 알려 주나요?","options":[{"t":"분리배출 방법을 잘 모르는 주민이 많다는 것","correct":true},{"t":"쓰레기통이 많다는 것","mis":"SO4-2-u2-X11"},{"t":"낮에 쓰레기를 버린다는 것","mis":"SO4-2-u2-X11"},{"t":"공터가 깨끗하다는 것","mis":"SO4-2-u2-X11"}],"explanation":["㉢을 읽어요.","설문 조사예요.","방법을 몰라요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#4','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C4',1,'mc','auto','해결 방안을 찾는 때로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X12']::text[],false,'{"seq":4,"concept":"SO4-2-u2-C4","difficulty":1,"kind":"mc","stem":"해결 방안을 찾는 때로 알맞은 것은 무엇인가요?","options":[{"t":"원인을 알아본 뒤","correct":true},{"t":"문제를 확인하기 전","mis":"SO4-2-u2-X12"},{"t":"실천을 모두 마친 뒤","mis":"SO4-2-u2-X12"},{"t":"원인과 상관없이 아무 때나","mis":"SO4-2-u2-X12"}],"explanation":["원인을 알아야 해요.","그다음이에요.","원인을 알아본 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#5','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C5',1,'mc','auto','제안서에 들어갈 내용으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u2-X18']::text[],false,'{"seq":5,"concept":"SO4-2-u2-C5","difficulty":1,"kind":"mc","stem":"제안서에 들어갈 내용으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"쓴 사람이 좋아하는 노래","correct":true},{"t":"제안서의 제목","mis":"SO4-2-u2-X18"},{"t":"제안한 까닭","mis":"SO4-2-u2-X18"},{"t":"주요 제안 내용","mis":"SO4-2-u2-X18"}],"explanation":["네 칸을 떠올려요.","노래는 없어요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#6','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C7',1,'mc','auto','소식지 ⑤의 ㉮ 느티나무는 어느 갈래와 가장 가까운가요?',ARRAY['SO4-2-u2-X22']::text[],false,'{"seq":6,"concept":"SO4-2-u2-C7","difficulty":1,"kind":"mc","stem":"소식지 ⑤의 ㉮ 느티나무는 어느 갈래와 가장 가까운가요?","options":[{"t":"자연환경","correct":true},{"t":"생산물","mis":"SO4-2-u2-X22"},{"t":"역사","mis":"SO4-2-u2-X22"},{"t":"문화","mis":"SO4-2-u2-X22"}],"explanation":["나무예요.","자연이 키웠어요.","자연환경이에요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#7','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C8',1,'mc','auto','소식지 ⑥에서 탈춤과 함께 운영하는 것은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO4-2-u2-C8","difficulty":1,"kind":"mc","stem":"소식지 ⑥에서 탈춤과 함께 운영하는 것은 무엇인가요?","options":[{"t":"탈 만들기 체험 프로그램","correct":true},{"t":"직거래 장터","mis":"SO4-2-u2-X26"},{"t":"박람회","mis":"SO4-2-u2-X26"},{"t":"관광 상품 개발","mis":"SO4-2-u2-X26"}],"explanation":["둘째 줄을 읽어요.","만들어 봐요.","체험 프로그램이에요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#8','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C9',1,'mc','auto','소식지 ⑦에서 안내도를 사회 관계망 서비스에 올릴 때 친구 얼굴 사진을 뺀 까닭은 무엇인가요?',ARRAY['SO4-2-u2-X29','SO4-2-u2-X22']::text[],false,'{"seq":8,"concept":"SO4-2-u2-C9","difficulty":1,"kind":"mc","stem":"소식지 ⑦에서 안내도를 사회 관계망 서비스에 올릴 때 친구 얼굴 사진을 뺀 까닭은 무엇인가요?","options":[{"t":"다른 사람의 사진은 허락 없이 게시하지 않기 때문이에요","correct":true},{"t":"사진이 너무 커서요","mis":"SO4-2-u2-X29"},{"t":"얼굴은 자랑거리이기 때문이에요","mis":"SO4-2-u2-X22"},{"t":"사진은 저작권과 관계없어서요","mis":"SO4-2-u2-X29"}],"explanation":["넷째 줄을 읽어요.","친구 사진이에요.","허락이 필요해요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#9','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C1',2,'error','auto','지역문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u2-X02','SO4-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u2-C1","difficulty":2,"kind":"error","stem":"지역문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 가 — 「지역문제는 한 사람이 열심히 하면 쉽게 풀려.」","correct":true,"mis_target":"SO4-2-u2-X02"},{"t":"친구 나 — 「주민들이 함께 해결해야 해.」","mis":"SO4-2-u2-X02"},{"t":"친구 다 — 「지역마다 다르게 나타나.」","mis":"SO4-2-u2-X03"}],"explanation":["혼자 풀릴까요?","함께 해야 해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#10','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C2',2,'blank','auto','해결하고 싶은 문제를 정할 때 조사한 횟수는 (    )만 하고, 토의로 정해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO4-2-u2-C2","difficulty":2,"kind":"blank","stem":"해결하고 싶은 문제를 정할 때 조사한 횟수는 (    )만 하고, 토의로 정해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"참고","correct":true},{"t":"비밀","mis":"SO4-2-u2-X06"},{"t":"무시","mis":"SO4-2-u2-X06"},{"t":"반대","mis":"SO4-2-u2-X06"}],"explanation":["횟수를 버리지 않아요.","그렇다고 다 따르지도 않아요.","참고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#11','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C3',2,'match','auto','소식지 ②의 자료와 자료의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO4-2-u2-C3","difficulty":2,"kind":"match","stem":"소식지 ②의 자료와 자료의 종류를 알맞게 이으세요.","pairs":[{"l":"자료 ㉠","r":"표"},{"l":"자료 ㉡","r":"그래프"},{"l":"자료 ㉢","r":"설문 조사"},{"l":"자료 ㉣","r":"신문 기사"}],"mis":"SO4-2-u2-X11","explanation":["㉠은 표예요.","㉡은 그래프예요.","㉢·㉣도 이어요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#12','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C4',2,'error','auto','소식지 ③을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u2-C4","difficulty":2,"kind":"error","stem":"소식지 ③을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉰는 1점이 있으니 그냥 버리자.」","correct":true,"mis_target":"SO4-2-u2-X14"},{"t":"친구 가 — 「㉯는 네 자리가 모두 3이야.」","mis":"SO4-2-u2-X14"},{"t":"친구 나 — 「㉮는 실천을 보완해 보자.」","mis":"SO4-2-u2-X14"}],"explanation":["㉰를 버릴까요?","보완할 수 있어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["방안 ㉮ 공터에 쓰레기통 놓기 — 효과 3 · 비용 2 · 실천 1 · 피해 없음 3","방안 ㉯ 분리배출 방법 안내문 붙이기 — 3 · 3 · 3 · 3","방안 ㉰ 밤마다 주민이 돌아가며 지키기 — 2 · 3 · 2 · 1"],"title":"소식지 ③ — 해결 방안 평가표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#13','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C5',2,'blank','auto','해결 방안을 정한 다음에는 구체적인 (    )을 세워 실천해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X16']::text[],false,'{"seq":13,"concept":"SO4-2-u2-C5","difficulty":2,"kind":"blank","stem":"해결 방안을 정한 다음에는 구체적인 (    )을 세워 실천해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"계획","correct":true},{"t":"담장","mis":"SO4-2-u2-X16"},{"t":"천막","mis":"SO4-2-u2-X16"},{"t":"기둥","mis":"SO4-2-u2-X16"}],"explanation":["무엇을 언제 할까요?","미리 정해요.","계획이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#14','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C7',2,'mc','auto','우리 지역의 자랑거리를 조사하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u2-X24']::text[],false,'{"seq":14,"concept":"SO4-2-u2-C7","difficulty":2,"kind":"mc","stem":"우리 지역의 자랑거리를 조사하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)","options":[{"t":"지역 문화원 누리집에서 검색해요","correct":true},{"t":"옆 지역 자랑거리를 옮겨 적어요","mis":"SO4-2-u2-X24"},{"t":"상상해서 적어요","mis":"SO4-2-u2-X24"},{"t":"아무에게도 묻지 않아요","mis":"SO4-2-u2-X24"}],"explanation":["우리 지역을 찾아요.","누리집이 있어요.","검색해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#15','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C8',2,'blank','auto','소식지 ⑥에서 가을에는 탈춤 공연과 함께 탈 만들기 (    )을 운영해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":15,"concept":"SO4-2-u2-C8","difficulty":2,"kind":"blank","stem":"소식지 ⑥에서 가을에는 탈춤 공연과 함께 탈 만들기 (    )을 운영해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"체험 프로그램","correct":true},{"t":"직거래 장터","mis":"SO4-2-u2-X26"},{"t":"박람회","mis":"SO4-2-u2-X26"},{"t":"관광 상품","mis":"SO4-2-u2-X26"}],"explanation":["직접 만들어 봐요.","해 보는 행사예요.","체험 프로그램이에요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#16','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C10',2,'sa','auto','상품 기획하기에서 「상품으로 만들 자랑거리」, 「정한 까닭」 다음에 채우는 칸은 「기획한 ○○」이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"SO4-2-u2-C10","difficulty":2,"kind":"sa","stem":"상품 기획하기에서 「상품으로 만들 자랑거리」, 「정한 까닭」 다음에 채우는 칸은 「기획한 ○○」이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["상품"],"explanation":["세 칸이에요.","마지막은 그림이에요.","상품이에요."],"mis":"SO4-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#17','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C6',3,'mc','auto','공익 광고 영상을 기획할 때 가장 중요하게 담아야 할 것은 무엇인가요?',ARRAY['SO4-2-u2-X21']::text[],false,'{"seq":17,"concept":"SO4-2-u2-C6","difficulty":3,"kind":"mc","stem":"공익 광고 영상을 기획할 때 가장 중요하게 담아야 할 것은 무엇인가요?","options":[{"t":"알리고 싶은 지역문제와 그 해결 방안","correct":true},{"t":"가장 비싼 장면","mis":"SO4-2-u2-X21"},{"t":"가장 긴 배경음","mis":"SO4-2-u2-X21"},{"t":"출연하는 사람의 수","mis":"SO4-2-u2-X21"}],"explanation":["무엇을 알리나요?","문제와 방안이에요.","그것을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#18','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C3',3,'error','auto','소식지 ②를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u2-X10']::text[],false,'{"seq":18,"concept":"SO4-2-u2-C3","difficulty":3,"kind":"error","stem":"소식지 ②를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉣ 기사 한 장만 보고 원인을 정하자.」","correct":true,"mis_target":"SO4-2-u2-X10"},{"t":"친구 나 — 「㉠과 ㉣을 겹쳐 보자.」","mis":"SO4-2-u2-X10"},{"t":"친구 다 — 「㉡과 ㉢도 함께 보자.」","mis":"SO4-2-u2-X10"}],"explanation":["한 장이면 될까요?","겹쳐 봐야 해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["자료 ㉠ 표 — 공터 둘레에 쓰레기통이 거의 없다.","자료 ㉡ 그래프 — 쓰레기는 주로 밤에 버려진다.","자료 ㉢ 설문 조사 — 분리배출 방법을 잘 모르는 주민이 많다.","자료 ㉣ 신문 기사 — 쓰레기통이 없는 곳일수록 버린 쓰레기가 많다."],"title":"소식지 ② — 원인을 찾는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#19','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C5',3,'mc','auto','소식지 ④처럼 지역문제가 해결되려면 무엇이 가장 필요한가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X16']::text[],false,'{"seq":19,"concept":"SO4-2-u2-C5","difficulty":3,"kind":"mc","stem":"소식지 ④처럼 지역문제가 해결되려면 무엇이 가장 필요한가요?","options":[{"t":"주민 모두가 관심을 갖고 공공 기관과 함께 꾸준히 노력하는 것","correct":true},{"t":"한 사람이 큰 목소리를 내는 것","mis":"SO4-2-u2-X19"},{"t":"공공 기관이 혼자 하는 것","mis":"SO4-2-u2-X19"},{"t":"시간이 지나기를 기다리는 것","mis":"SO4-2-u2-X16"}],"explanation":["누가 움직였나요?","주민과 구청이에요.","꾸준히 함께해요."],"asset":{"type":"passage","lines":["주민들은 분리배출 안내문을 붙이고 함께 캠페인을 벌였다.","쓰레기통 설치와 단속은 구청에 제안서를 보내 협조를 구했다.","몇 달 뒤 공터가 깨끗해졌고, 놀이터를 찾는 주민이 늘었다."],"title":"소식지 ④ — 함께 실천했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#20','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C8',3,'mc','auto','같은 방법이 여러 갈래에 쓰이는 예로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u2-C8","difficulty":3,"kind":"mc","stem":"같은 방법이 여러 갈래에 쓰이는 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"축제는 복숭아도 알리고 탈춤도 알릴 수 있어요","correct":true},{"t":"직거래 장터는 탈춤만 알려요","mis":"SO4-2-u2-X26"},{"t":"박람회는 우물터만 알려요","mis":"SO4-2-u2-X26"},{"t":"방법은 갈래마다 하나뿐이에요","mis":"SO4-2-u2-X26"}],"explanation":["축제를 떠올려요.","여러 갈래에 쓰여요.","그 예예요."],"asset":{"type":"passage","lines":["여름에는 복숭아 축제를 열고, 직거래 장터에서 복숭아를 판다.","가을에는 탈춤 공연과 함께 탈 만들기 체험 프로그램을 운영한다.","축제 소식은 구청 누리집과 사회 관계망 서비스, 마을 소식지로 알린다."],"title":"소식지 ⑥ — 자랑거리를 알려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#21','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C9',3,'mc','auto','소식지 ⑦에서 안내도를 사회 관계망 서비스에 올리기 전에 더 확인할 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u2-X29','SO4-2-u2-X27']::text[],false,'{"seq":21,"concept":"SO4-2-u2-C9","difficulty":3,"kind":"mc","stem":"소식지 ⑦에서 안내도를 사회 관계망 서비스에 올리기 전에 더 확인할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"안내도에 쓴 정보가 정확한지와 쓴 사진이 저작권에 문제없는지","correct":true},{"t":"올리는 시간이 빠른지","mis":"SO4-2-u2-X29"},{"t":"친구 사진을 더 넣었는지","mis":"SO4-2-u2-X29"},{"t":"다른 동네 자료를 붙였는지","mis":"SO4-2-u2-X27"}],"explanation":["정확한가요?","저작권은요?","그것을 확인해요."],"asset":{"type":"passage","lines":["푸른반 모둠은 ○○동 자랑거리를 안내도로 소개하기로 했다.","먼저 소개할 자랑거리를 정리하고, 백지도에 있는 곳을 색칠했다.","설명 자료를 붙이고, 색칠한 곳과 자료를 선으로 이어 완성했다.","안내도를 사회 관계망 서비스에 올릴 때는 친구 얼굴이 나온 사진을 뺐다."],"title":"소식지 ⑦ — 푸른반 안내도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#22','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C10',3,'mc','auto','복숭아·쌀·배추로 동시를 지으면 ○○동을 어떻게 알릴 수 있나요?',ARRAY['SO4-2-u2-X30','SO4-2-u2-X31']::text[],false,'{"seq":22,"concept":"SO4-2-u2-C10","difficulty":3,"kind":"mc","stem":"복숭아·쌀·배추로 동시를 지으면 ○○동을 어떻게 알릴 수 있나요?","options":[{"t":"○○동에서 나는 생산물을 재미있게 알릴 수 있어요","correct":true},{"t":"○○동의 지역문제를 알릴 수 있어요","mis":"SO4-2-u2-X30"},{"t":"다른 동네의 생산물을 알릴 수 있어요","mis":"SO4-2-u2-X30"},{"t":"아무것도 알릴 수 없어요","mis":"SO4-2-u2-X31"}],"explanation":["동시에 넣었어요.","나는 것이에요.","생산물을 알려요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#23','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C1',4,'mc','auto','「지역문제 해결과 지역 알리기」 단원을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u2-X19','SO4-2-u2-X30','SO4-2-u2-X02']::text[],false,'{"seq":23,"concept":"SO4-2-u2-C1","difficulty":4,"kind":"mc","stem":"「지역문제 해결과 지역 알리기」 단원을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"주민이 함께 지역문제를 해결하고, 지역의 자랑거리를 다양한 방법으로 알리며 더 살기 좋은 지역을 만들어요","correct":true},{"t":"지역문제는 공공 기관만 해결해요","mis":"SO4-2-u2-X19"},{"t":"자랑거리로 지역문제를 찾아요","mis":"SO4-2-u2-X30"},{"t":"지역문제와 자랑거리는 한 사람이 맡아요","mis":"SO4-2-u2-X02"}],"explanation":["주제①은 해결이에요.","주제②는 알리기예요.","둘을 합쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#24','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C9',4,'essay','teacher','소식지 ⑤의 자랑거리 하나를 골라 만화·포스터·안내도 가운데 하나로 소개하는 계획을 쓰세요. 사회 관계망 서비스에 올릴 때 지킬 점도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u2-C9","difficulty":4,"kind":"essay","stem":"소식지 ⑤의 자랑거리 하나를 골라 만화·포스터·안내도 가운데 하나로 소개하는 계획을 쓰세요. 사회 관계망 서비스에 올릴 때 지킬 점도 하나 쓰세요.","answer_guide":{"answer":"예: ㉰ 마을 탈춤을 만화로 소개할래요. 먼저 탈춤에 대해 정리하고, 다섯 장면으로 나눈 뒤 그림과 말풍선을 넣어 완성할 거예요. 사회 관계망 서비스에 올릴 때는 공연한 분들의 사진을 허락 없이 올리지 않을 거예요.","scoring_points":["자랑거리와 방법을 골랐는가","만드는 걸음을 차례대로 썼는가","지킬 점을 썼는가"]},"explanation":["하나를 골라요.","걸음을 써요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["㉮ 동네 한가운데 수백 년 된 느티나무","㉯ 옛사람들이 물을 길어 쓰던 우물터","㉰ 해마다 공연하는 마을 탈춤","㉱ 동네 언덕 과수원에서 거두는 복숭아"],"title":"소식지 ⑤ — ○○동의 자랑거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u2_review_d#25','soc',4,2,'u2','','g4_2_soc_u2_review_d','unit_review','SO4-2-u2-C10',4,'essay','teacher','소식지 ⑧처럼 단원을 정리한다면 두 활동 가운데 무엇을 고를지 쓰고, 그 활동에 담을 우리 지역의 자랑거리와 담는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u2-C10","difficulty":4,"kind":"essay","stem":"소식지 ⑧처럼 단원을 정리한다면 두 활동 가운데 무엇을 고를지 쓰고, 그 활동에 담을 우리 지역의 자랑거리와 담는 까닭을 쓰세요.","answer_guide":{"answer":"예: 상품 기획하기를 고를래요. 우리 지역의 오래된 다리를 담은 엽서를 기획하고 싶어요. 다리가 옛날부터 마을과 마을을 이어 주어 우리 지역의 역사를 잘 보여 주기 때문이에요.","scoring_points":["활동 하나를 골랐는가","담을 자랑거리를 썼는가","담는 까닭을 썼는가"]},"explanation":["하나를 골라요.","자랑거리를 정해요.","까닭을 써요."],"asset":{"type":"passage","lines":["푸른반은 단원을 정리하며 두 활동 가운데 하나를 골랐다.","어떤 모둠은 복숭아·쌀·배추를 넣어 동시를 지었다.","어떤 모둠은 느티나무를 담은 책갈피 상품을 기획했다."],"title":"소식지 ⑧ — 푸른반 단원 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
